{"summary": "Inspect all endpoints in openapi.contract.json", "command": "python3 -c "
import json
with open('contracts/openapi.contract.json') as f:
    spec = json.load(f)

print('Paths:', len(spec.get('paths', {})))
for path, methods in sorted(spec.get('paths', {}).items()):
    for method, op in methods.items():
        print(f'{method.upper():<7} {path:<45} -> {op.get(\"operationId\")}')
""}

{"summary": "Dump schema overview of all endpoints", "command": "python3 -c "
import json
with open('contracts/openapi.contract.json') as f:
    spec = json.load(f)

for path, methods in sorted(spec.get('paths', {}).items()):
    for method, op in methods.items():
        op_id = op.get('operationId')
        resps = op.get('responses', {})
        print(f'{method.upper():4} {path}')
        rb = op.get('requestBody', {})
        if rb:
            schema = rb.get('content', {}).get('application/json', {}).get('schema', {})
            print('   REQ:', schema.get('type'), schema.get('properties', {}).keys() if 'properties' in schema else schema.get('$ref'))
        for code, resp in resps.items():
            if code in ['200', '201']:
                content = resp.get('content', {}).get('application/json', {})
                schema = content.get('schema', {})
                print(f'   RESP {code}:', schema.get('type'), schema.get('properties', {}).keys() if 'properties' in schema else schema.get('$ref'))
""}

