    spec = json.load(f)

for path, methods in sorted(spec.get('paths', {}).items()):
    for m, op in methods.items():
        print(f'{m.upper()} {path}')
        req_b = op.get('requestBody', {}).get('content', {}).get('application/json', {}).get('schema', {})
        if '$ref' in req_b:
            ref = req_b['$ref'].split('/')[-1]
            req_b = spec['components']['schemas'].get(ref, {})
        if 'properties' in req_b:
            print('  Req fields:', list(req_b['properties'].keys()))
        for sc in ['200', '201']:
            if sc in op.get('responses', {}):
                resp_b = op['responses'][sc].get('content', {}).get('application/json', {}).get('schema', {})
                if '$ref' in resp_b:
                    ref = resp_b['$ref'].split('/')[-1]
                    resp_b = spec['components']['schemas'].get(ref, {})
                print(f'  Resp {sc} fields:', list(resp_b.get('properties', {}).keys()))
"

