python3 -c "
import json
with open('contracts/openapi.contract.json') as f:
    spec = json.load(f)

for path, methods in sorted(spec.get('paths', {}).items()):
    for m, op in methods.items():
        print(f'=== {m.upper()} {path} ===')
        for sc in ['200', '201']:
            if sc in op.get('responses', {}):
