package auth

import (
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"errors"
	"time"

	"golang.org/x/crypto/bcrypt"
	"lab-transport/internal/models"
)

var (
	ErrInvalidCredentials = errors.New("invalid_credentials")
	ErrUnauthorized       = errors.New("unauthorized")
	ErrForbidden          = errors.New("forbidden")
	ErrRoleNotHeld        = errors.New("role_not_held")
	ErrUserInactive       = errors.New("user_inactive")
)

func GenerateToken() string {
	b := make([]byte, 32)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

func Authenticate(db *sql.DB, username, password string) (string, *models.User, error) {
	row := db.QueryRow(`
		SELECT user_id, username, password_hash, email, full_name, phone, roles, active_role, qualifications, certifications, active, assigned_location_id, available, capacity_units
		FROM users
		WHERE username = $1
	`, username)

	var u models.User
	var rolesJSON, qualsJSON, certsJSON []byte
	var activeRole sql.NullString
	var assignedLoc sql.NullString

	err := row.Scan(&u.UserId, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone, &rolesJSON, &activeRole, &qualsJSON, &certsJSON, &u.Active, &assignedLoc, &u.Available, &u.CapacityUnits)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return "", nil, ErrInvalidCredentials
		}
		return "", nil, err
	}

	if !u.Active {
		return "", nil, ErrUserInactive
	}

	if err := bcrypt.CompareHashAndPassword([]byte(u.PasswordHash), []byte(password)); err != nil {
		return "", nil, ErrInvalidCredentials
	}

	_ = json.Unmarshal(rolesJSON, &u.Roles)
	_ = json.Unmarshal(qualsJSON, &u.Qualifications)
	_ = json.Unmarshal(certsJSON, &u.Certifications)
	if activeRole.Valid && activeRole.String != "" {
		u.ActiveRole = activeRole.String
	} else if len(u.Roles) > 0 {
		u.ActiveRole = u.Roles[0]
	}
	if assignedLoc.Valid {
		loc := assignedLoc.String
		u.AssignedLocationId = &loc
	}

	token := GenerateToken()
	expiresAt := time.Now().Add(7 * 24 * time.Hour)
	_, err = db.Exec(`
		INSERT INTO sessions (token, user_id, expires_at)
		VALUES ($1, $2, $3)
	`, token, u.UserId, expiresAt)
	if err != nil {
		return "", nil, err
	}

	return token, &u, nil
}

func GetUserByToken(db *sql.DB, token string) (*models.User, error) {
	if token == "" {
		return nil, ErrUnauthorized
	}

	row := db.QueryRow(`
		SELECT u.user_id, u.username, u.email, u.full_name, u.phone, u.roles, u.active_role, u.qualifications, u.certifications, u.active, u.assigned_location_id, u.available, u.capacity_units, s.expires_at
		FROM sessions s
		JOIN users u ON s.user_id = u.user_id
		WHERE s.token = $1
	`, token)

	var u models.User
	var rolesJSON, qualsJSON, certsJSON []byte
	var activeRole sql.NullString
	var assignedLoc sql.NullString
	var expiresAt time.Time

	err := row.Scan(&u.UserId, &u.Username, &u.Email, &u.FullName, &u.Phone, &rolesJSON, &activeRole, &qualsJSON, &certsJSON, &u.Active, &assignedLoc, &u.Available, &u.CapacityUnits, &expiresAt)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrUnauthorized
		}
		return nil, err
	}

	if time.Now().After(expiresAt) {
		_, _ = db.Exec("DELETE FROM sessions WHERE token = $1", token)
		return nil, ErrUnauthorized
	}

	if !u.Active {
		return nil, ErrUserInactive
	}

	_ = json.Unmarshal(rolesJSON, &u.Roles)
	_ = json.Unmarshal(qualsJSON, &u.Qualifications)
	_ = json.Unmarshal(certsJSON, &u.Certifications)
	if activeRole.Valid && activeRole.String != "" {
		u.ActiveRole = activeRole.String
	} else if len(u.Roles) > 0 {
		u.ActiveRole = u.Roles[0]
	}
	if assignedLoc.Valid {
		loc := assignedLoc.String
		u.AssignedLocationId = &loc
	}

	return &u, nil
}

func SelectActiveRole(db *sql.DB, userId string, role string) ([]string, string, error) {
	row := db.QueryRow("SELECT roles FROM users WHERE user_id = $1", userId)
	var rolesJSON []byte
	if err := row.Scan(&rolesJSON); err != nil {
		return nil, "", err
	}
	var roles []string
	_ = json.Unmarshal(rolesJSON, &roles)

	roleFound := false
	for _, r := range roles {
		if r == role {
			roleFound = true
			break
		}
	}
	if !roleFound {
		return roles, "", ErrRoleNotHeld
	}

	_, err := db.Exec("UPDATE users SET active_role = $1, updated_at = NOW() WHERE user_id = $2", role, userId)
	if err != nil {
		return nil, "", err
	}

	return roles, role, nil
}

func HasRole(user *models.User, allowedRoles ...string) bool {
	if user == nil {
		return false
	}
	// An administrator can perform administrator and dispatcher actions
	for _, r := range allowedRoles {
		if user.ActiveRole == r {
			return true
		}
		if user.ActiveRole == "administrator" && (r == "dispatcher" || r == "administrator") {
			return true
		}
	}
	return false
}

