			Minutes: c.TravelMinutes,
			Cost:    c.CostUnits,
		})
	}

	locMap := make(map[string]models.OperationsLocation)
	for _, l := range allLocs {
		locMap[l.LocationId] = l
	}

	// Dijkstra
	dist := make(map[string]int)
	costDist := make(map[string]float64)
	prev := make(map[string]string)
	visited := make(map[string]bool)

	for _, l := range allLocs {
		dist[l.LocationId] = math.MaxInt32
		costDist[l.LocationId] = math.MaxFloat64
	}
	dist[startLocId] = 0
	costDist[startLocId] = 0

	for len(visited) < len(allLocs) {
		u := ""
		minD := math.MaxInt32
		for locId, d := range dist {
			if !visited[locId] && d < minD {
				minD = d
				u = locId
			}
		}
		if u == "" || minD == math.MaxInt32 {
			break
		}
		visited[u] = true

		if labMap[u] {
			// Found shortest path to a lab!
			path := []string{}
			curr := u
			for curr != "" {
				path = append([]string{curr}, path...)
				curr = prev[curr]
			}
			return path, u, dist[u], costDist[u], nil
		}

		handling := 0
		if loc, ok := locMap[u]; ok && u != startLocId {
			handling = loc.HandlingMinutes
		}

		for _, edge := range adj[u] {
			if visited[edge.ToLocId] {
				continue
			}
			newDist := dist[u] + edge.Minutes + handling
			newCost := costDist[u] + edge.Cost
			if newDist < dist[edge.ToLocId] {
				dist[edge.ToLocId] = newDist
				costDist[edge.ToLocId] = newCost
				prev[edge.ToLocId] = u
			}
		}
	}

	return nil, "", 0, 0, nil
}

func PublishServiceabilitySnapshot(db *sql.DB) (*models.ServiceabilitySnapshot, error) {
	var maxVer int
	var rev int
	_ = db.QueryRow("SELECT COALESCE(MAX(version), 0), COALESCE(MAX(network_revision), 0) FROM serviceability_snapshots").Scan(&maxVer, &rev)

	newVer := maxVer + 1
	newRev := rev + 1

	rows, err := db.Query(`
		SELECT location_id, name, latitude, longitude, coverage_km
		FROM locations
		WHERE active = true AND func_collection_point = true
	`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var regions []models.ServiceabilityRegion
	for rows.Next() {
		var r models.ServiceabilityRegion
		if err := rows.Scan(&r.LocationId, &r.Name, &r.Latitude, &r.Longitude, &r.CoverageKm); err != nil {
			return nil, err
		}
		regions = append(regions, r)
	}
	if regions == nil {
		regions = make([]models.ServiceabilityRegion, 0)
	}

	regionsJSON, _ := json.Marshal(regions)
	now := time.Now()
	_, err = db.Exec(`
		INSERT INTO serviceability_snapshots (version, status, network_revision, computed_at, regions, active_collection_point_count)
		VALUES ($1, 'complete', $2, $3, $4, $5)
	`, newVer, newRev, now, regionsJSON, len(regions))
	if err != nil {
		return nil, err
	}

	return &models.ServiceabilitySnapshot{
		Version:                    newVer,
		Status:                     "complete",
		ComputedAt:                 now.Format(time.RFC3339Nano),
		NetworkRevision:            newRev,
		Regions:                    regions,
		ActiveCollectionPointCount: len(regions),
	}, nil
}

func GetLatestServiceabilitySnapshot(db *sql.DB) (*models.ServiceabilitySnapshot, error) {
	var snap models.ServiceabilitySnapshot
	var computedAt time.Time
	var regionsJSON []byte
	err := db.QueryRow(`
		SELECT version, status, network_revision, computed_at, regions, active_collection_point_count
		FROM serviceability_snapshots
		WHERE status = 'complete'
		ORDER BY version DESC
		LIMIT 1
	`).Scan(&snap.Version, &snap.Status, &snap.NetworkRevision, &computedAt, &regionsJSON, &snap.ActiveCollectionPointCount)
	if err != nil {
		return PublishServiceabilitySnapshot(db)
	}
	snap.ComputedAt = computedAt.Format(time.RFC3339Nano)
	_ = json.Unmarshal(regionsJSON, &snap.Regions)
	if snap.Regions == nil {
		snap.Regions = make([]models.ServiceabilityRegion, 0)
	}
	return &snap, nil
}
"}

