package service

import (
	"database/sql"
	"encoding/json"
	"math"
	"time"

	"lab-transport/internal/models"
)

func HaversineDistance(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0 // Earth radius in kilometers
	dLat := (lat2 - lat1) * math.Pi / 180.0
	dLon := (lon2 - lon1) * math.Pi / 180.0

	lat1Rad := lat1 * math.Pi / 180.0
	lat2Rad := lat2 * math.Pi / 180.0

	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(lat1Rad)*math.Cos(lat2Rad)*
			math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}

type CheckServiceabilityParams struct {
	Origin               *models.Coordinate `json:"origin"`
	OriginType           string             `json:"originType"`
	OriginNodeId         *string            `json:"originNodeId"`
	SampleTypeId         string             `json:"sampleTypeId"`
	RequestedAt          string             `json:"requestedAt"`
	DeliveryDeadline     string             `json:"deliveryDeadline"`
	EarliestCollectionAt string             `json:"earliestCollectionAt"`
	LatestCollectionAt   string             `json:"latestCollectionAt"`
}

type CheckServiceabilityResult struct {
	Serviceable           bool    `json:"serviceable"`
	Reason                string  `json:"reason"`
	TargetLaboratoryId    *string `json:"targetLaboratoryId,omitempty"`
	EstimatedArrivalAt    *string `json:"estimatedArrivalAt,omitempty"`
	ServiceabilityVersion int     `json:"serviceabilityVersion"`
	ClosestNodeId         *string `json:"-"`
	RoutePath             []string `json:"-"`
	TotalTravelMinutes    int     `json:"-"`
	TotalCostUnits        float64 `json:"-"`
}

func CheckServiceability(db *sql.DB, params CheckServiceabilityParams) (*CheckServiceabilityResult, error) {
	// 1. Get latest serviceability snapshot version
	var snapVersion int
	err := db.QueryRow("SELECT version FROM serviceability_snapshots ORDER BY version DESC LIMIT 1").Scan(&snapVersion)
	if err != nil {
		snapVersion = 1
	}

	result := &CheckServiceabilityResult{
		Serviceable:           false,
		ServiceabilityVersion: snapVersion,
	}

	// Validate times
	earliestTime, err1 := time.Parse(time.RFC3339, params.EarliestCollectionAt)
	latestTime, err2 := time.Parse(time.RFC3339, params.LatestCollectionAt)
	deadlineTime, err3 := time.Parse(time.RFC3339, params.DeliveryDeadline)
	if err1 != nil || err2 != nil || err3 != nil {
		result.Reason = "deadline_unreachable"
		return result, nil
	}
	if earliestTime.After(latestTime) || latestTime.After(deadlineTime) {
		result.Reason = "deadline_unreachable"
		return result, nil
	}

	// 2. Fetch Sample Type
	var st models.SampleType
	var incompJSON []byte
	row := db.QueryRow(`
		SELECT sample_type_id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed
		FROM sample_types
		WHERE sample_type_id = $1
	`, params.SampleTypeId)
	err = row.Scan(&st.SampleTypeId, &st.Name, &st.QualifiedCollectorRequired, &st.RequiredQualification, &st.ContainerType, &st.TemperatureMinC, &st.TemperatureMaxC, &incompJSON, &st.RequiresCooledRoute, &st.BatchingAllowed)
	if err != nil {
		result.Reason = "handling_rules_unsatisfiable"
		return result, nil
	}
	_ = json.Unmarshal(incompJSON, &st.IncompatibleSampleTypes)

	// 3. Find closest active collection point node
	var closestNode *models.Location
	minDist := math.MaxFloat64

	locRows, err := db.Query(`
		SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active, func_collection_point, func_transfer_point, func_hub, func_laboratory, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units, accepted_sample_type_ids
		FROM locations
		WHERE active = true
	`)
	if err != nil {
		return nil, err
	}
	defer locRows.Close()

	var allLocations []models.OperationsLocation
	var labLocations []models.OperationsLocation

	for locRows.Next() {
		var loc models.OperationsLocation
		var funcCP, funcTP, funcHub, funcLab bool
		var capUnits, resUnits, coolCapUnits, coolResUnits int
		var acceptedJSON []byte

		if err := locRows.Scan(&loc.LocationId, &loc.Name, &loc.Coordinate.Latitude, &loc.Coordinate.Longitude, &loc.CoverageKm, &loc.HandlingMinutes, &loc.Active, &funcCP, &funcTP, &funcHub, &funcLab, &capUnits, &resUnits, &coolCapUnits, &coolResUnits, &acceptedJSON); err != nil {
			return nil, err
		}
		loc.ID = loc.LocationId
		loc.Functions = models.LocationFunctionStates{
			CollectionPoint: &funcCP,
			TransferPoint:   &funcTP,
			Hub:             &funcHub,
			Laboratory:      &funcLab,
		}
		loc.Capacity = &models.Capacity{
			CapacityUnits:        capUnits,
			ReservedUnits:        resUnits,
			AvailableUnits:       capUnits - resUnits,
			CooledCapacityUnits:  coolCapUnits,
			CooledReservedUnits:  coolResUnits,
			CooledAvailableUnits: coolCapUnits - coolResUnits,
		}
		_ = json.Unmarshal(acceptedJSON, &loc.AcceptedSampleTypeIds)
		allLocations = append(allLocations, loc)

		if funcLab {
			// Check if lab accepts sample type
			accepted := false
			for _, tid := range loc.AcceptedSampleTypeIds {
				if tid == params.SampleTypeId {
					accepted = true
					break
				}
			}
			if accepted || len(loc.AcceptedSampleTypeIds) == 0 {
				labLocations = append(labLocations, loc)
			}
		}

		if params.OriginNodeId != nil && *params.OriginNodeId == loc.LocationId {
			closestNode = &models.Location{
				LocationId:      loc.LocationId,
				Name:            loc.Name,
				Coordinate:      loc.Coordinate,
				CoverageKm:      loc.CoverageKm,
				HandlingMinutes: loc.HandlingMinutes,
				Active:          loc.Active,
				Functions:       loc.Functions,
			}
			minDist = 0
		} else if params.Origin != nil && funcCP {
			dist := HaversineDistance(params.Origin.Latitude, params.Origin.Longitude, loc.Coordinate.Latitude, loc.Coordinate.Longitude)
			if dist <= loc.CoverageKm && dist < minDist {
				minDist = dist
				closestNode = &models.Location{
					LocationId:      loc.LocationId,
					Name:            loc.Name,
					Coordinate:      loc.Coordinate,
					CoverageKm:      loc.CoverageKm,
					HandlingMinutes: loc.HandlingMinutes,
					Active:          loc.Active,
					Functions:       loc.Functions,
				}
			}
		}
	}

	if closestNode == nil {
		result.Reason = "outside_service_coverage"
		return result, nil
	}
	result.ClosestNodeId = &closestNode.LocationId

	if len(labLocations) == 0 {
		result.Reason = "no_accepting_laboratory"
		return result, nil
	}

	// 4. Fetch connections
	connRows, err := db.Query(`
		SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM connections
		WHERE active = true
	`)
	if err != nil {
		return nil, err
	}
	defer connRows.Close()

	var allConnections []models.OperationsConnection
	for connRows.Next() {
		var c models.OperationsConnection
		var capUnits, resUnits, coolCapUnits, coolResUnits int
		if err := connRows.Scan(&c.ConnectionId, &c.FromLocationId, &c.ToLocationId, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active, &capUnits, &resUnits, &coolCapUnits, &coolResUnits); err != nil {
			return nil, err
		}
		c.ID = c.ConnectionId
		c.Capacity = &models.Capacity{
			CapacityUnits:        capUnits,
			ReservedUnits:        resUnits,
			AvailableUnits:       capUnits - resUnits,
			CooledCapacityUnits:  coolCapUnits,
			CooledReservedUnits:  coolResUnits,
			CooledAvailableUnits: coolCapUnits - coolResUnits,
		}
		allConnections = append(allConnections, c)
	}

	// 5. Shortest path (Dijkstra) from closestNode to any labLocation
	bestPath, bestLabId, totalTravel, totalCost, err := FindShortestRoute(closestNode.LocationId, labLocations, allLocations, allConnections, st.RequiresCooledRoute)
	if err != nil || len(bestPath) == 0 {
		// Check if failure is due to capacity
		result.Reason = "no_route"
		return result, nil
	}

	// Collection leg time: estimated 15 mins for home collection + handling
	collectionMins := 15 + closestNode.HandlingMinutes
	totalMinutes := collectionMins + totalTravel

	estimatedArrival := earliestTime.Add(time.Duration(totalMinutes) * time.Minute)
	if estimatedArrival.After(deadlineTime) {
		result.Reason = "deadline_unreachable"
		return result, nil
	}

	estStr := estimatedArrival.Format(time.RFC3339Nano)
	result.Serviceable = true
	result.Reason = "serviceable"
	result.TargetLaboratoryId = &bestLabId
	result.EstimatedArrivalAt = &estStr
	result.RoutePath = bestPath
	result.TotalTravelMinutes = totalMinutes
	result.TotalCostUnits = totalCost

	return result, nil
}

func FindShortestRoute(startLocId string, targetLabs []models.OperationsLocation, allLocs []models.OperationsLocation, allConns []models.OperationsConnection, requiresCooled bool) ([]string, string, int, float64, error) {
	labMap := make(map[string]bool)
	for _, l := range targetLabs {
		labMap[l.LocationId] = true
	}

	// Direct check: if startLoc is already an accepting lab
	if labMap[startLocId] {
		return []string{startLocId}, startLocId, 0, 0, nil
	}

	// Graph adjacency
	type Edge struct {
		ToLocId string
		Minutes int
		Cost    float64
	}
	adj := make(map[string][]Edge)
	for _, c := range allConns {
		if !c.Active {
			continue
		}
		if requiresCooled && (!c.Cooled || (c.Capacity != nil && c.Capacity.CooledAvailableUnits <= 0)) {
			continue
		}
		if !requiresCooled && c.Capacity != nil && c.Capacity.AvailableUnits <= 0 {
			continue
		}
		adj[c.FromLocationId] = append(adj[c.FromLocationId], Edge{
			ToLocId: c.ToLocationId,
			Minutes: c.TravelMinutes,
			Cost:    c.CostUnits,
		})
	}

	locMap := make(map[string]models.OperationsLocation)
	for _, l := range allLocs {
		locMap[l.LocationId] = l
	}

	// Dijkstra
	dist := make(map[string]int)
	costDist := make(map[string]float64)
	prev := make(map[string]string)
	visited := make(map[string]bool)

	for _, l := range allLocs {
		dist[l.LocationId] = math.MaxInt32
		costDist[l.LocationId] = math.MaxFloat64
	}
	dist[startLocId] = 0
	costDist[startLocId] = 0

	for len(visited) < len(allLocs) {
		u := ""
		minD := math.MaxInt32
		for locId, d := range dist {
			if !visited[locId] && d < minD {
				minD = d
				u = locId
			}
		}
		if u == "" || minD == math.MaxInt32 {
			break
		}
		visited[u] = true

		if labMap[u] {
			// Found shortest path to a lab!
			path := []string{}
			curr := u
			for curr != "" {
				path = append([]string{curr}, path...)
				curr = prev[curr]
			}
			return path, u, dist[u], costDist[u], nil
		}

		handling := 0
		if loc, ok := locMap[u]; ok && u != startLocId {
			handling = loc.HandlingMinutes
		}

		for _, edge := range adj[u] {
			if visited[edge.ToLocId] {
				continue
			}
			newDist := dist[u] + edge.Minutes + handling
			newCost := costDist[u] + edge.Cost
			if newDist < dist[edge.ToLocId] {
				dist[edge.ToLocId] = newDist
				costDist[edge.ToLocId] = newCost
				prev[edge.ToLocId] = u
			}
		}
	}

	return nil, "", 0, 0, nil
}

func PublishServiceabilitySnapshot(db *sql.DB) (*models.ServiceabilitySnapshot, error) {
	var maxVer int
	var rev int
	_ = db.QueryRow("SELECT COALESCE(MAX(version), 0), COALESCE(MAX(network_revision), 0) FROM serviceability_snapshots").Scan(&maxVer, &rev)

	newVer := maxVer + 1
	newRev := rev + 1

	rows, err := db.Query(`
		SELECT location_id, name, latitude, longitude, coverage_km
		FROM locations
		WHERE active = true AND func_collection_point = true
	`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var regions []models.ServiceabilityRegion
	for rows.Next() {
		var r models.ServiceabilityRegion
		if err := rows.Scan(&r.LocationId, &r.Name, &r.Latitude, &r.Longitude, &r.CoverageKm); err != nil {
			return nil, err
		}
		regions = append(regions, r)
	}
	if regions == nil {
		regions = make([]models.ServiceabilityRegion, 0)
	}

	regionsJSON, _ := json.Marshal(regions)
	now := time.Now()
	_, err = db.Exec(`
		INSERT INTO serviceability_snapshots (version, status, network_revision, computed_at, regions, active_collection_point_count)
		VALUES ($1, 'complete', $2, $3, $4, $5)
	`, newVer, newRev, now, regionsJSON, len(regions))
	if err != nil {
		return nil, err
	}

	return &models.ServiceabilitySnapshot{
		Version:                    newVer,
		Status:                     "complete",
		ComputedAt:                 now.Format(time.RFC3339Nano),
		NetworkRevision:            newRev,
		Regions:                    regions,
		ActiveCollectionPointCount: len(regions),
	}, nil
}

func GetLatestServiceabilitySnapshot(db *sql.DB) (*models.ServiceabilitySnapshot, error) {
	var snap models.ServiceabilitySnapshot
	var computedAt time.Time
	var regionsJSON []byte
	err := db.QueryRow(`
		SELECT version, status, network_revision, computed_at, regions, active_collection_point_count
		FROM serviceability_snapshots
		WHERE status = 'complete'
		ORDER BY version DESC
		LIMIT 1
	`).Scan(&snap.Version, &snap.Status, &snap.NetworkRevision, &computedAt, &regionsJSON, &snap.ActiveCollectionPointCount)
	if err != nil {
		return PublishServiceabilitySnapshot(db)
	}
	snap.ComputedAt = computedAt.Format(time.RFC3339Nano)
	_ = json.Unmarshal(regionsJSON, &snap.Regions)
	if snap.Regions == nil {
		snap.Regions = make([]models.ServiceabilityRegion, 0)
	}
	return &snap, nil
}

