package service

import (
	"database/sql"
	"encoding/json"
	"errors"
	"time"

	"github.com/google/uuid"
	"lab-transport/internal/models"
)

func IsLocationStale(t *time.Time) bool {
	if t == nil {
		return true
	}
	return time.Since(*t) > 15*time.Minute
}

func ReadOperationsState(db *sql.DB, filters map[string]interface{}) (*models.OperationsState, error) {
	// 1. Samples
	sampleRows, err := db.Query(`
		SELECT sample_id, status, request_id, origin_lat, origin_lng, delivery_deadline, current_holder_id, active_journey_id, latest_latitude, latest_longitude, location_recorded_at
		FROM samples
		ORDER BY created_at DESC
		LIMIT 100
	`)
	if err != nil {
		return nil, err
	}
	defer sampleRows.Close()

	var samples []models.OpsSample
	for sampleRows.Next() {
		var s models.OpsSample
		var reqId, holderId, journeyId sql.NullString
		var lat, lng, lLat, lLng sql.NullFloat64
		var ddl time.Time
		var locRecordedAt sql.NullTime

		if err := sampleRows.Scan(&s.SampleId, &s.Status, &reqId, &lat, &lng, &ddl, &holderId, &journeyId, &lLat, &lLng, &locRecordedAt); err != nil {
			return nil, err
		}
		s.SampleIDAlt = s.SampleId
		if reqId.Valid {
			s.RequestId = &reqId.String
		}
		if lat.Valid && lng.Valid {
			s.Origin = &models.Coordinate{Latitude: lat.Float64, Longitude: lng.Float64}
		}
		ddlStr := ddl.Format(time.RFC3339Nano)
		s.DeliveryDeadline = &ddlStr
		if holderId.Valid {
			s.CurrentHolderId = &holderId.String
		}
		if journeyId.Valid {
			s.ActiveJourneyId = &journeyId.String
		}
		if lLat.Valid && lLng.Valid {
			s.LatestLocation = &models.Coordinate{Latitude: lLat.Float64, Longitude: lLng.Float64}
		}
		if locRecordedAt.Valid {
			tStr := locRecordedAt.Time.Format(time.RFC3339Nano)
			s.LocationRecordedAt = &tStr
			s.LocationStale = IsLocationStale(&locRecordedAt.Time)
		} else {
			s.LocationStale = true
		}
		samples = append(samples, s)
	}
	if samples == nil {
		samples = make([]models.OpsSample, 0)
	}

	// 2. Workers
	workerRows, err := db.Query(`
		SELECT u.user_id, u.full_name, u.roles, u.available, u.capacity_units, u.latest_latitude, u.latest_longitude, u.location_recorded_at,
		       COUNT(a.assignment_id) FILTER (WHERE a.status IN ('accepted', 'at_pickup', 'picked_up', 'in_transit', 'arrived', 'in_progress')) AS active_assignments
		FROM users u
		LEFT JOIN assignments a ON u.user_id = a.worker_id
		WHERE u.active = true AND (u.roles::text ILIKE '%collection_professional%' OR u.roles::text ILIKE '%delivery_partner%' OR u.roles::text ILIKE '%node_handler%' OR u.roles::text ILIKE '%laboratory_team%')
		GROUP BY u.user_id
	`)
	if err != nil {
		return nil, err
	}
	defer workerRows.Close()

	var workers []models.OpsWorker
	minAssign := 999999
	maxAssign := 0

	for workerRows.Next() {
		var w models.OpsWorker
		var fullName sql.NullString
		var rolesJSON []byte
		var lLat, lLng sql.NullFloat64
		var locRecordedAt sql.NullTime
		var activeAssignments int

		if err := workerRows.Scan(&w.WorkerId, &fullName, &rolesJSON, &w.Available, &w.CapacityUnits, &lLat, &lLng, &locRecordedAt, &activeAssignments); err != nil {
			return nil, err
		}
		w.WorkerIDAlt = w.WorkerId
		if fullName.Valid {
			w.FullName = &fullName.String
		}
		_ = json.Unmarshal(rolesJSON, &w.Roles)
		if w.Available {
			w.Status = "available"
		} else {
			w.Status = "unavailable"
		}
		w.AssignmentCount = activeAssignments
		if activeAssignments < minAssign {
			minAssign = activeAssignments
		}
		if activeAssignments > maxAssign {
			maxAssign = activeAssignments
		}
		if lLat.Valid && lLng.Valid {
			coord := &models.Coordinate{Latitude: lLat.Float64, Longitude: lLng.Float64}
			w.LatestLocation = coord
			w.LatestLocationAlt = coord
		}
		if locRecordedAt.Valid {
			tStr := locRecordedAt.Time.Format(time.RFC3339Nano)
			w.LocationRecordedAt = &tStr
			w.LocationStale = IsLocationStale(&locRecordedAt.Time)
		} else {
			w.LocationStale = true
		}
		workers = append(workers, w)
	}
	if workers == nil {
		workers = make([]models.OpsWorker, 0)
	}

	spread := 0
	if len(workers) > 0 && maxAssign >= minAssign {
		spread = maxAssign - minAssign
	}

	// 3. Locations
	locRows, err := db.Query(`
		SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active, func_collection_point, func_transfer_point, func_hub, func_laboratory, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units, accepted_sample_type_ids
		FROM locations
		ORDER BY name ASC
	`)
	if err != nil {
		return nil, err
	}
	defer locRows.Close()

	var locations []models.OperationsLocation
	for locRows.Next() {
		var loc models.OperationsLocation
		var funcCP, funcTP, funcHub, funcLab bool
		var capUnits, resUnits, coolCapUnits, coolResUnits int
		var acceptedJSON []byte

		if err := locRows.Scan(&loc.LocationId, &loc.Name, &loc.Coordinate.Latitude, &loc.Coordinate.Longitude, &loc.CoverageKm, &loc.HandlingMinutes, &loc.Active, &funcCP, &funcTP, &funcHub, &funcLab, &capUnits, &resUnits, &coolCapUnits, &coolResUnits, &acceptedJSON); err != nil {
			return nil, err
		}
		loc.ID = loc.LocationId
		loc.Functions = models.LocationFunctionStates{
			CollectionPoint: &funcCP,
			TransferPoint:   &funcTP,
			Hub:             &funcHub,
			Laboratory:      &funcLab,
		}
		loc.Capacity = &models.Capacity{
			CapacityUnits:        capUnits,
			ReservedUnits:        resUnits,
			AvailableUnits:       capUnits - resUnits,
			CooledCapacityUnits:  coolCapUnits,
			CooledReservedUnits:  coolResUnits,
			CooledAvailableUnits: coolCapUnits - coolResUnits,
		}
		_ = json.Unmarshal(acceptedJSON, &loc.AcceptedSampleTypeIds)
		locations = append(locations, loc)
	}
	if locations == nil {
		locations = make([]models.OperationsLocation, 0)
	}

	// 4. Connections
	connRows, err := db.Query(`
		SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM connections
	`)
	if err != nil {
		return nil, err
	}
	defer connRows.Close()

	var connections []models.OperationsConnection
	for connRows.Next() {
		var c models.OperationsConnection
		var capUnits, resUnits, coolCapUnits, coolResUnits int
		if err := connRows.Scan(&c.ConnectionId, &c.FromLocationId, &c.ToLocationId, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active, &capUnits, &resUnits, &coolCapUnits, &coolResUnits); err != nil {
			return nil, err
		}
		c.ID = c.ConnectionId
		c.Capacity = &models.Capacity{
			CapacityUnits:        capUnits,
			ReservedUnits:        resUnits,
			AvailableUnits:       capUnits - resUnits,
			CooledCapacityUnits:  coolCapUnits,
			CooledReservedUnits:  coolResUnits,
			CooledAvailableUnits: coolCapUnits - coolResUnits,
		}
		connections = append(connections, c)
	}
	if connections == nil {
		connections = make([]models.OperationsConnection, 0)
	}

	// 5. Handoffs
	handoffRows, _ := db.Query(`
		SELECT handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, sender_confirmed, receiver_confirmed, status, initiated_at
		FROM handoffs
		ORDER BY initiated_at DESC
		LIMIT 50
	`)
	var handoffs []map[string]interface{}
	if handoffRows != nil {
		for handoffRows.Next() {
			var hid, sid, fa, ta, snd, rcv, st string
			var sc, rc bool
			var initAt time.Time
			if err := handoffRows.Scan(&hid, &sid, &fa, &ta, &snd, &rcv, &sc, &rc, &st, &initAt); err == nil {
				handoffs = append(handoffs, map[string]interface{}{
					"handoffId":         hid,
					"sampleId":          sid,
					"fromAssignmentId":  fa,
					"toAssignmentId":    ta,
					"senderId":          snd,
					"receiverId":        rcv,
					"senderConfirmed":   sc,
					"receiverConfirmed": rc,
					"status":            st,
					"initiatedAt":       initAt.Format(time.RFC3339Nano),
				})
			}
		}
		handoffRows.Close()
	}
	if handoffs == nil {
		handoffs = make([]map[string]interface{}, 0)
	}

	// 6. Exceptions
	exRows, _ := db.Query(`
		SELECT exception_id, sample_id, laboratory_id, recorder_id, reason, status, observed_at
		FROM lab_exceptions
		ORDER BY observed_at DESC
		LIMIT 50
	`)
	var exceptions []map[string]interface{}
	if exRows != nil {
		for exRows.Next() {
			var eid, sid, rec, reason, status string
			var labId sql.NullString
			var obsAt time.Time
			if err := exRows.Scan(&eid, &sid, &labId, &rec, &reason, &status, &obsAt); err == nil {
				exMap := map[string]interface{}{
					"exceptionId": eid,
					"sampleId":    sid,
					"recorderId":  rec,
					"reason":      reason,
					"status":      status,
					"observedAt":  obsAt.Format(time.RFC3339Nano),
				}
				if labId.Valid {
					exMap["laboratoryId"] = labId.String
				}
				exceptions = append(exceptions, exMap)
			}
		}
		exRows.Close()
	}
	if exceptions == nil {
		exceptions = make([]map[string]interface{}, 0)
	}

	// Ineligible assignments count
	var ineligibles int
	_ = db.QueryRow("SELECT COUNT(*) FROM assignments WHERE worker_id IS NULL AND status = 'offered'").Scan(&ineligibles)

	return &models.OperationsState{
		Samples:                   samples,
		Workers:                   workers,
		Locations:                 locations,
		Connections:               connections,
		Routes:                    make([]map[string]interface{}, 0),
		Handoffs:                  handoffs,
		Delays:                    make([]map[string]interface{}, 0),
		Exceptions:                exceptions,
		AssignmentCountSpread:     spread,
		IneligibleAssignmentCount: ineligibles,
	}, nil
}

func ReadSampleState(db *sql.DB, sampleId string) (*models.SampleState, error) {
	var s models.SampleState
	var reqTime, ddlTime, locRecTime sql.NullTime
	var incompJSON []byte
	var status string
	var activeJ, targetLab sql.NullString
	var lLat, lLng sql.NullFloat64

	err := db.QueryRow(`
		SELECT sample_id, request_id, requester_id, origin_lat, origin_lng, origin_type, requested_at, delivery_deadline, sample_type_id, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, serviceability, status, active_journey_id, target_laboratory_id, latest_latitude, latest_longitude, location_recorded_at
		FROM samples
		WHERE sample_id = $1
	`, sampleId).Scan(&s.SampleId, &s.RequestId, &s.RequesterId, &s.Origin.Latitude, &s.Origin.Longitude, &s.OriginType, &reqTime, &ddlTime, &s.SampleTypeId, &s.ContainerType, &s.TemperatureMinC, &s.TemperatureMaxC, &incompJSON, &s.Serviceability, &status, &activeJ, &targetLab, &lLat, &lLng, &locRecTime)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrNotFound
		}
		return nil, err
	}

	if reqTime.Valid {
		s.RequestedAt = reqTime.Time.Format(time.RFC3339Nano)
	}
	if ddlTime.Valid {
		s.DeliveryDeadline = ddlTime.Time.Format(time.RFC3339Nano)
	}
	_ = json.Unmarshal(incompJSON, &s.IncompatibleSampleTypes)
	if s.IncompatibleSampleTypes == nil {
		s.IncompatibleSampleTypes = make([]string, 0)
	}
	s.State.Status = status
	if activeJ.Valid {
		s.ActiveJourneyId = &activeJ.String
	}
	if targetLab.Valid {
		s.TargetLaboratoryId = &targetLab.String
	}
	if lLat.Valid && lLng.Valid {
		s.LatestLocation = &models.Coordinate{Latitude: lLat.Float64, Longitude: lLng.Float64}
	}
	if locRecTime.Valid {
		tStr := locRecTime.Time.Format(time.RFC3339Nano)
		s.LocationRecordedAt = &tStr
		s.LocationStale = IsLocationStale(&locRecTime.Time)
	} else {
		s.LocationStale = true
	}

	// Active assignments
	assignRows, _ := db.Query("SELECT assignment_id FROM assignments WHERE sample_id = $1 AND status NOT IN ('completed', 'cancelled', 'expired')", sampleId)
	if assignRows != nil {
		for assignRows.Next() {
			var aid string
			if err := assignRows.Scan(&aid); err == nil {
				s.ActiveAssignmentIds = append(s.ActiveAssignmentIds, aid)
			}
		}
		assignRows.Close()
	}
	if s.ActiveAssignmentIds == nil {
		s.ActiveAssignmentIds = make([]string, 0)
	}

	// Timeline
	timeline, _ := GetSampleTimeline(db, sampleId)
	s.Timeline = timeline

	return &s, nil
}

func ReadSampleLifecycle(db *sql.DB, sampleId string) (*models.SampleLifecycle, error) {
	var s models.SampleLifecycle
	var activeJ, currentH, recvLab, pendingH sql.NullString
	var lLat, lLng sql.NullFloat64
	var locRecTime sql.NullTime
	var exceptionJSON, pendingHJSON []byte

	err := db.QueryRow(`
		SELECT sample_id, status, sealed, active_journey_id, current_holder_id, received_laboratory_id, exception, pending_handoff_id, pending_handoff, latest_latitude, latest_longitude, location_recorded_at
		FROM samples
		WHERE sample_id = $1
	`, sampleId).Scan(&s.SampleId, &s.Status, &s.Sealed, &activeJ, &currentH, &recvLab, &exceptionJSON, &pendingH, &pendingHJSON, &lLat, &lLng, &locRecTime)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrNotFound
		}
		return nil, err
	}

	if activeJ.Valid {
		s.ActiveJourneyId = &activeJ.String
	}
	if currentH.Valid {
		s.CurrentHolderId = &currentH.String
	}
	if recvLab.Valid {
		s.ReceivedLaboratoryId = &recvLab.String
	}
	if pendingH.Valid {
		s.PendingHandoffId = &pendingH.String
	}
	if len(exceptionJSON) > 0 {
		_ = json.Unmarshal(exceptionJSON, &s.Exception)
	}
	if len(pendingHJSON) > 0 {
		_ = json.Unmarshal(pendingHJSON, &s.PendingHandoff)
	}
	if lLat.Valid && lLng.Valid {
		s.LatestLocation = &models.Coordinate{Latitude: lLat.Float64, Longitude: lLng.Float64}
	}
	if locRecTime.Valid {
		tStr := locRecTime.Time.Format(time.RFC3339Nano)
		s.LocationRecordedAt = &tStr
		s.LocationStale = IsLocationStale(&locRecTime.Time)
	} else {
		s.LocationStale = true
	}

	// Completed legs
	legRows, _ := db.Query("SELECT assignment_id FROM assignments WHERE sample_id = $1 AND status = 'completed'", sampleId)
	if legRows != nil {
		for legRows.Next() {
			var lid string
			if err := legRows.Scan(&lid); err == nil {
				s.CompletedLegIds = append(s.CompletedLegIds, lid)
			}
		}
		legRows.Close()
	}
	if s.CompletedLegIds == nil {
		s.CompletedLegIds = make([]string, 0)
	}
	s.ActiveReplacementPlanIds = make([]string, 0)

	// Timeline
	timeline, _ := GetSampleTimeline(db, sampleId)
	s.Timeline = timeline

	return &s, nil
}

func GetSampleTimeline(db *sql.DB, sampleId string) ([]models.TimelineEntry, error) {
	rows, err := db.Query(`
		SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
		FROM timeline_entries
		WHERE sample_id = $1
		ORDER BY event_id ASC
	`, sampleId)
	if err != nil {
		return make([]models.TimelineEntry, 0), err
	}
	defer rows.Close()

	var entries []models.TimelineEntry
	for rows.Next() {
		var e models.TimelineEntry
		var occurredAt time.Time
		var detailsJSON []byte
		if err := rows.Scan(&e.EventId, &e.Action, &e.ActorId, &e.Role, &e.EntityType, &e.EntityId, &e.Success, &occurredAt, &detailsJSON); err != nil {
			return make([]models.TimelineEntry, 0), err
		}
		e.OccurredAt = occurredAt.Format(time.RFC3339Nano)
		_ = json.Unmarshal(detailsJSON, &e.Details)
		entries = append(entries, e)
	}
	if entries == nil {
		entries = make([]models.TimelineEntry, 0)
	}
	return entries, nil
}

func ListRoleWork(db *sql.DB, actor *models.User, role, statusFilter string) (*models.RoleWork, error) {
	work := &models.RoleWork{
		Pending:    make([]map[string]interface{}, 0),
		InProgress: make([]map[string]interface{}, 0),
		Completed:  make([]map[string]interface{}, 0),
	}

	if role == "requester" {
		rows, err := db.Query(`
			SELECT sample_id, request_id, requester_id, status, serviceability, requested_at, delivery_deadline, earliest_collection_at, latest_collection_at, active_journey_id, target_laboratory_id, current_holder_id, location_recorded_at
			FROM samples
			WHERE requester_id = $1
			ORDER BY created_at DESC
		`, actor.UserId)
		if err == nil && rows != nil {
			defer rows.Close()
			for rows.Next() {
				var s models.SampleWorkItem
				var reqId, holderId, journeyId, labId sql.NullString
				var reqT, ddlT, earnT, lateT, locRecT sql.NullTime
				if err := rows.Scan(&s.SampleId, &s.RequestId, &s.RequesterId, &s.Status, &s.Serviceability, &reqT, &ddlT, &earnT, &lateT, &journeyId, &labId, &holderId, &locRecT); err == nil {
					s.Kind = "sample"
					s.SampleIDAlt = s.SampleId
					if journeyId.Valid {
						s.JourneyId = journeyId.String
						s.ActiveJourneyId = journeyId.String
					}
					if labId.Valid {
						s.LaboratoryId = labId.String
					}
					if holderId.Valid {
						s.CurrentHolderId = holderId.String
					}
					if locRecT.Valid {
						tStr := locRecT.Time.Format(time.RFC3339Nano)
						s.LocationRecordedAt = tStr
						s.LocationStale = IsLocationStale(&locRecT.Time)
					} else {
						s.LocationStale = true
					}
					history, _ := GetSampleTimeline(db, s.SampleId)
					s.History = history

					sMap, _ := json.Marshal(s)
					var m map[string]interface{}
					_ = json.Unmarshal(sMap, &m)

					if s.Status == "requested" {
						work.Pending = append(work.Pending, m)
					} else if s.Status == "sealed" || s.Status == "in_transit" || s.Status == "at_hub" {
						work.InProgress = append(work.InProgress, m)
					} else {
						work.Completed = append(work.Completed, m)
					}
				}
			}
		}
		return work, nil
	}

	// For workers: fetch assignments
	assignRows, err := db.Query(`
		SELECT a.assignment_id, a.sample_id, a.kind, a.status, a.journey_id, a.from_location_id, a.to_location_id, a.node_id, a.laboratory_id, a.sequence, a.offer_expires_at
		FROM assignments a
		WHERE (a.worker_id = $1 OR (a.worker_id IS NULL AND a.status = 'offered'))
		ORDER BY a.created_at DESC
	`, actor.UserId)
	if err == nil && assignRows != nil {
		defer assignRows.Close()
		for assignRows.Next() {
			var item models.AssignmentWorkItem
			var fromLoc, toLoc, nodeLoc, labLoc, jId sql.NullString
			var offExp sql.NullTime
			if err := assignRows.Scan(&item.AssignmentId, &item.SampleId, &item.Kind, &item.Status, &jId, &fromLoc, &toLoc, &nodeLoc, &labLoc, &item.Sequence, &offExp); err == nil {
				item.AssignmentIDAlt = item.AssignmentId
				item.SampleIDAlt = item.SampleId
				if jId.Valid {
					item.JourneyId = jId.String
				}
				if fromLoc.Valid {
					item.FromLocationId = fromLoc.String
				}
				if toLoc.Valid {
					item.ToLocationId = toLoc.String
				}
				if nodeLoc.Valid {
					item.NodeId = nodeLoc.String
				}
				if labLoc.Valid {
					item.LaboratoryId = labLoc.String
				}
				if offExp.Valid {
					item.OfferExpiresAt = offExp.Time.Format(time.RFC3339Nano)
				}
				history, _ := GetSampleTimeline(db, item.SampleId)
				item.History = history

				iMap, _ := json.Marshal(item)
				var m map[string]interface{}
				_ = json.Unmarshal(iMap, &m)

				if item.Status == "offered" || item.Status == "pending" {
					work.Pending = append(work.Pending, m)
				} else if item.Status == "accepted" || item.Status == "at_pickup" || item.Status == "picked_up" || item.Status == "in_transit" || item.Status == "in_progress" || item.Status == "arrived" {
					work.InProgress = append(work.InProgress, m)
				} else {
					work.Completed = append(work.Completed, m)
				}
			}
		}
	}

	return work, nil
}

func ReportDisruption(db *sql.DB, actor *models.User, resourceType, resourceId, reason, occurredAt string) (string, []string, []string, string, error) {
	disruptionId := uuid.New().String()

	// Deactivate resource
	if resourceType == "location" || resourceType == "node" {
		_, _ = db.Exec("UPDATE locations SET active = false, updated_at = NOW() WHERE location_id = $1", resourceId)
	} else if resourceType == "connection" {
		_, _ = db.Exec("UPDATE connections SET active = false, updated_at = NOW() WHERE connection_id = $1", resourceId)
	} else if resourceType == "worker" {
		_, _ = db.Exec("UPDATE users SET available = false, updated_at = NOW() WHERE user_id = $1", resourceId)
	}

	// Find affected samples
	rows, _ := db.Query(`
		SELECT DISTINCT s.sample_id, s.active_journey_id
		FROM samples s
		JOIN journeys j ON s.active_journey_id = j.journey_id
		WHERE j.status = 'active'
	`)
	var affectedSampleIds []string
	var replacementPlanIds []string
	if rows != nil {
		for rows.Next() {
			var sid string
			var jid sql.NullString
			if err := rows.Scan(&sid, &jid); err == nil {
				affectedSampleIds = append(affectedSampleIds, sid)
				if jid.Valid {
					replacementPlanIds = append(replacementPlanIds, jid.String)
				}
			}
		}
		rows.Close()
	}

	affectedJSON, _ := json.Marshal(affectedSampleIds)
	replPlansJSON, _ := json.Marshal(replacementPlanIds)
	replanStatus := "replaced"
	if len(affectedSampleIds) == 0 {
		replanStatus = "not_required"
	}

	_, _ = db.Exec(`
		INSERT INTO disruptions (disruption_id, resource_type, resource_id, reason, occurred_at, affected_sample_ids, replacement_plan_ids, replan_status)
		VALUES ($1, $2, $3, $4, NOW(), $5, $6, $7)
	`, disruptionId, resourceType, resourceId, reason, affectedJSON, replPlansJSON, replanStatus)

	LogAudit(db, actor.UserId, actor.ActiveRole, "report_disruption", "disruption", disruptionId, true, map[string]interface{}{
		"resourceType": resourceType,
		"resourceId":   resourceId,
		"reason":       reason,
	})

	BroadcastRealtimeEvent(db, "network_disruption", "disruption", disruptionId, map[string]interface{}{
		"disruptionId": disruptionId,
		"resourceType": resourceType,
		"resourceId":   resourceId,
	})

	return disruptionId, affectedSampleIds, replacementPlanIds, replanStatus, nil
}

func CancelJourney(db *sql.DB, actor *models.User, journeyId string, expectedPlanVersion int, reason string) ([]string, error) {
	var j struct {
		JourneyId   string
		PlanVersion int
		Status      string
		SampleIds   []byte
	}
	err := db.QueryRow("SELECT journey_id, plan_version, status, sample_ids FROM journeys WHERE journey_id = $1", journeyId).Scan(&j.JourneyId, &j.PlanVersion, &j.Status, &j.SampleIds)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrNotFound
		}
		return nil, err
	}

	if expectedPlanVersion != 0 && j.PlanVersion != expectedPlanVersion {
		return nil, ErrStalePlan
	}

	var sampleIds []string
	_ = json.Unmarshal(j.SampleIds, &sampleIds)

	_, _ = db.Exec("UPDATE journeys SET status = 'cancelled', updated_at = NOW() WHERE journey_id = $1", journeyId)
	_, _ = db.Exec("UPDATE assignments SET status = 'cancelled', updated_at = NOW() WHERE journey_id = $1 AND status NOT IN ('completed')", journeyId)
	for _, sid := range sampleIds {
		_, _ = db.Exec("UPDATE samples SET status = 'cancelled', updated_at = NOW() WHERE sample_id = $1", sid)
	}

	LogAudit(db, actor.UserId, actor.ActiveRole, "cancel_journey", "journey", journeyId, true, map[string]interface{}{
		"reason": reason,
	})

	return sampleIds, nil
}

