		var req struct {
			AssignmentId string            `json:"assignmentId"`
			Coordinate   models.Coordinate `json:"coordinate"`
			Sequence     int               `json:"sequence"`
			RecordedAt   string            `json:"recordedAt"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			SendError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON")
			return
		}

		now := time.Now()
		_, _ = db.Exec(`
			UPDATE users
			SET latest_latitude = $1, latest_longitude = $2, location_recorded_at = $3, updated_at = NOW()
			WHERE user_id = $4
		`, req.Coordinate.Latitude, req.Coordinate.Longitude, now, user.UserId)

		if req.AssignmentId != "" {
			var sampleId sql.NullString
			_ = db.QueryRow("SELECT sample_id FROM assignments WHERE assignment_id = $1", req.AssignmentId).Scan(&sampleId)
			if sampleId.Valid {
				_, _ = db.Exec(`
					UPDATE samples
					SET latest_latitude = $1, latest_longitude = $2, location_recorded_at = $3, updated_at = NOW()
					WHERE sample_id = $4
				`, req.Coordinate.Latitude, req.Coordinate.Longitude, now, sampleId.String)
			}
		}

		SendJSON(w, http.StatusCreated, map[string]interface{}{
			"data": map[string]interface{}{
				"assignmentId": req.AssignmentId,
				"coordinate":   req.Coordinate,
				"sequence":     req.Sequence,
				"recordedAt":   now.Format(time.RFC3339Nano),
			},
		})
	}
}

func UpdateAssignmentProgressHandler(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		user, err := GetAuthUser(r, db)
		if err != nil {
			SendError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
			return
		}

		var req struct {
			AssignmentId   string `json:"assignmentId"`
			Status         string `json:"status"`
			OccurredAt     string `json:"occurredAt"`
			IdempotencyKey string `json:"idempotencyKey"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			SendError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON")
			return
		}
		if req.IdempotencyKey == "" {
			SendError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
			return
		}

		var sampleId string
		var journeyId string
		err = db.QueryRow("SELECT sample_id, journey_id FROM assignments WHERE assignment_id = $1", req.AssignmentId).Scan(&sampleId, &journeyId)
		if err != nil {
			SendError(w, http.StatusNotFound, "not_found", "Assignment not found")
			return
		}

		_, err = db.Exec("UPDATE assignments SET status = $1, updated_at = NOW() WHERE assignment_id = $2", req.Status, req.AssignmentId)
		if err != nil {
			SendError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}

		// Sync sample status if applicable
		if req.Status == "in_transit" || req.Status == "picked_up" {
			_, _ = db.Exec("UPDATE samples SET status = 'in_transit', updated_at = NOW() WHERE sample_id = $1", sampleId)
		}

		service.LogAudit(db, user.UserId, user.ActiveRole, "update_assignment_progress", "assignment", req.AssignmentId, true, map[string]interface{}{
			"status": req.Status,
		})

		service.LogTimeline(db, &sampleId, &journeyId, &req.AssignmentId, "assignment_progress", user.UserId, user.ActiveRole, "assignment", req.AssignmentId, true, map[string]interface{}{
			"status": req.Status,
		})

		SendJSON(w, http.StatusCreated, map[string]interface{}{
			"data": map[string]interface{}{
				"assignmentId": req.AssignmentId,
				"sampleId":     sampleId,
				"status":       req.Status,
			},
		})
	}
}

