func ReadJourneyPlanHandler(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		user, err := GetAuthUser(r, db)
		if err != nil {
			SendError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
			return
		}

		var req struct {
			JourneyId string `json:"journeyId"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			SendError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON")
			return
		}

		var j models.JourneyPlan
		var parentJ, estDel, colAssignId, firstT, midT, finalT, replanSt sql.NullString
		var totalCost sql.NullFloat64
		var capUsed, capAvail sql.NullInt64
		var sampleIdsJSON, stopsJSON, legsJSON, assignedWorkersJSON, colAssignIdsJSON, nodeAssignIdsJSON, labAssignIdsJSON []byte

		err = db.QueryRow(`
			SELECT journey_id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, capacity_used, capacity_available, sample_ids, ordered_stops, legs, assigned_worker_ids, collection_assignment_id, collection_assignment_ids, node_assignment_ids, laboratory_assignment_ids, first_transport_assignment_id, middle_transport_assignment_id, final_transport_assignment_id, valid, replan_status
			FROM journeys
			WHERE journey_id = $1
		`, req.JourneyId).Scan(&j.JourneyId, &parentJ, &j.PlanVersion, &j.RouteMode, &j.Status, &estDel, &totalCost, &capUsed, &capAvail, &sampleIdsJSON, &stopsJSON, &legsJSON, &assignedWorkersJSON, &colAssignId, &colAssignIdsJSON, &nodeAssignIdsJSON, &labAssignIdsJSON, &firstT, &midT, &finalT, &j.Valid, &replanSt)
		if err != nil {
			SendError(w, http.StatusNotFound, "not_found", "Journey plan not found")
			return
		}

		if parentJ.Valid {
			j.ParentJourneyId = &parentJ.String
		}
		if estDel.Valid {
			j.EstimatedDeliveryAt = &estDel.String
		}
		if totalCost.Valid {
			j.TotalCostUnits = &totalCost.Float64
		}
		if capUsed.Valid {
			cu := int(capUsed.Int64)
			j.CapacityUsed = &cu
		}
		if capAvail.Valid {
			ca := int(capAvail.Int64)
			j.CapacityAvailable = &ca
		}
		_ = json.Unmarshal(sampleIdsJSON, &j.SampleIds)
		_ = json.Unmarshal(stopsJSON, &j.OrderedStops)
		_ = json.Unmarshal(legsJSON, &j.Legs)
		_ = json.Unmarshal(assignedWorkersJSON, &j.AssignedWorkerIds)
		_ = json.Unmarshal(colAssignIdsJSON, &j.CollectionAssignmentIds)
		_ = json.Unmarshal(nodeAssignIdsJSON, &j.NodeAssignmentIds)
		_ = json.Unmarshal(labAssignIdsJSON, &j.LaboratoryAssignmentIds)

		if user.ActiveRole == "requester" {
			SendJSON(w, http.StatusOK, map[string]interface{}{
				"data": models.RequesterJourneyPlan{
					JourneyId:           j.JourneyId,
					ParentJourneyId:     j.ParentJourneyId,
					PlanVersion:         &j.PlanVersion,
					RouteMode:           &j.RouteMode,
					Status:              &j.Status,
					EstimatedDeliveryAt: j.EstimatedDeliveryAt,
					TotalCostUnits:      j.TotalCostUnits,
					SampleIds:           j.SampleIds,
					OrderedStops:        j.OrderedStops,
					Legs:                j.Legs,
				},
			})
			return
		}

		if user.ActiveRole == "collection_professional" || user.ActiveRole == "delivery_partner" || user.ActiveRole == "node_handler" || user.ActiveRole == "laboratory_team" {
			var assignIds []string
			for _, l := range j.Legs {
				assignIds = append(assignIds, l.AssignmentId)
			}
			SendJSON(w, http.StatusOK, map[string]interface{}{
				"data": models.WorkerJourneyPlan{
					JourneyId:               j.JourneyId,
					ParentJourneyId:         j.ParentJourneyId,
					PlanVersion:             j.PlanVersion,
					RouteMode:               j.RouteMode,
					Status:                  j.Status,
					EstimatedDeliveryAt:     j.EstimatedDeliveryAt,
					Scope:                   "worker_assigned",
					AssignmentIds:           assignIds,
					SampleIds:               j.SampleIds,
					Legs:                    j.Legs,
					OrderedStops:            j.OrderedStops,
					CollectionAssignmentIds: j.CollectionAssignmentIds,
					NodeAssignmentIds:       j.NodeAssignmentIds,
					LaboratoryAssignmentIds: j.LaboratoryAssignmentIds,
					AssignedWorkerIds:       j.AssignedWorkerIds,
				},
			})
			return
		}

		SendJSON(w, http.StatusOK, map[string]interface{}{
			"data": j,
		})
	}
}

