func ConfigureLaboratoryAcceptanceHandler(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		user, err := GetAuthUser(r, db)
		if err != nil {
			SendError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
			return
		}
		if !auth.HasRole(user, "administrator") {
			SendError(w, http.StatusForbidden, "forbidden", "Only administrator can configure laboratory acceptance")
			return
		}

		var req struct {
			LaboratoryId string `json:"laboratoryId"`
			SampleTypeId string `json:"sampleTypeId"`
			Accepts      bool   `json:"accepts"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			SendError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON")
			return
		}

		var acceptedJSON []byte
		_ = db.QueryRow("SELECT accepted_sample_type_ids FROM locations WHERE location_id = $1", req.LaboratoryId).Scan(&acceptedJSON)
		var list []string
		_ = json.Unmarshal(acceptedJSON, &list)

		if req.Accepts {
			found := false
			for _, id := range list {
				if id == req.SampleTypeId {
					found = true
					break
				}
			}
			if !found {
				list = append(list, req.SampleTypeId)
			}
		} else {
			var updated []string
			for _, id := range list {
				if id != req.SampleTypeId {
					updated = append(updated, id)
				}
			}
			list = updated
		}

		newJSON, _ := json.Marshal(list)
		_, err = db.Exec("UPDATE locations SET accepted_sample_type_ids = $1, updated_at = NOW() WHERE location_id = $2", newJSON, req.LaboratoryId)
		if err != nil {
			SendError(w, http.StatusNotFound, "not_found", "Laboratory not found")
			return
		}

		acceptanceId := uuid.New().String()
		SendJSON(w, http.StatusOK, map[string]interface{}{
			"data": map[string]interface{}{
				"acceptanceId": acceptanceId,
				"accepts":      req.Accepts,
			},
		})
	}
}

