			SendError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON format")
			return
		}
		if req.Username == "" || req.Password == "" {
			SendError(w, http.StatusUnauthorized, "invalid_credentials", "Username and password required")
			return
		}

		token, user, err := auth.Authenticate(db, req.Username, req.Password)
		if err != nil {
			if errors.Is(err, auth.ErrInvalidCredentials) || errors.Is(err, auth.ErrUserInactive) {
				SendError(w, http.StatusUnauthorized, "invalid_credentials", "Invalid username or password")
				return
			}
			SendError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}

		SendJSON(w, http.StatusOK, map[string]interface{}{
