package handlers

import (
	"database/sql"
	"encoding/json"
	"errors"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/gorilla/websocket"
	"golang.org/x/crypto/bcrypt"
	"lab-transport/internal/auth"
	"lab-transport/internal/models"
	"lab-transport/internal/service"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool {
		return true
	},
}

func SendJSON(w http.ResponseWriter, status int, data interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(data)
}

func SendError(w http.ResponseWriter, status int, code, message string) {
	SendJSON(w, status, models.ErrorEnvelope{
		Error: message,
		Code:  code,
	})
}

func GetAuthUser(r *http.Request, db *sql.DB) (*models.User, error) {
	authHeader := r.Header.Get("Authorization")
	if authHeader == "" {
		return nil, auth.ErrUnauthorized
	}
	parts := strings.SplitN(authHeader, " ", 2)
	if len(parts) != 2 || strings.ToLower(parts[0]) != "bearer" {
		return nil, auth.ErrUnauthorized
	}
	token := strings.TrimSpace(parts[1])
	return auth.GetUserByToken(db, token)
}

func ReadyHandler(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if db == nil || db.Ping() != nil {
			SendJSON(w, http.StatusServiceUnavailable, map[string]string{"status": "starting"})
			return
		}
		SendJSON(w, http.StatusOK, map[string]string{"status": "ready"})
	}
}

func AuthenticateUserHandler(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			Username string `json:"username"`
			Password string `json:"password"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			SendError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON format")
			return
		}
		if req.Username == "" || req.Password == "" {
			SendError(w, http.StatusUnauthorized, "invalid_credentials", "Username and password required")
			return
		}

		token, user, err := auth.Authenticate(db, req.Username, req.Password)
		if err != nil {
			if errors.Is(err, auth.ErrInvalidCredentials) || errors.Is(err, auth.ErrUserInactive) {
				SendError(w, http.StatusUnauthorized, "invalid_credentials", "Invalid username or password")
				return
			}
			SendError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}

		SendJSON(w, http.StatusOK, map[string]interface{}{
			"data": map[string]interface{}{
				"sessionToken": token,
				"userId":       user.UserId,
				"roles":        user.Roles,
				"activeRole":   user.ActiveRole,
			},
		})
	}
}

func SelectActiveRoleHandler(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		user, err := GetAuthUser(r, db)
		if err != nil {
			SendError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
			return
		}

		var req struct {
			Role string `json:"role"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			SendError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON")
			return
		}

		roles, activeRole, err := auth.SelectActiveRole(db, user.UserId, req.Role)
		if err != nil {
			if errors.Is(err, auth.ErrRoleNotHeld) {
				SendError(w, http.StatusForbidden, "role_not_held", "User does not possess this role")
				return
			}
			SendError(w, http.StatusBadRequest, "invalid_role", err.Error())
			return
		}

		SendJSON(w, http.StatusOK, map[string]interface{}{
			"data": map[string]interface{}{
				"activeRole": activeRole,
				"roles":      roles,
			},
		})
	}
}

func UIBootstrapHandler(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		user, err := GetAuthUser(r, db)
		if err != nil {
			SendError(w, http.StatusUnauthorized, "unauthorized", "Authentication required")
			return
		}

		ops, _ := service.ReadOperationsState(db, nil)
		now := time.Now().Format(time.RFC3339Nano)

		var requesterSamples []map[string]interface{}
		if user.ActiveRole == "requester" {
			work, _ := service.ListRoleWork(db, user, "requester", "")
			if work != nil {
				requesterSamples = append(requesterSamples, work.Pending...)
				requesterSamples = append(requesterSamples, work.InProgress...)
				requesterSamples = append(requesterSamples, work.Completed...)
			}
		}
		if requesterSamples == nil {
			requesterSamples = make([]map[string]interface{}, 0)
		}

		SendJSON(w, http.StatusOK, map[string]interface{}{
			"data": map[string]interface{}{
				"user": map[string]interface{}{
					"userId":                user.UserId,
					"username":              user.Username,
					"fullName":              user.FullName,
					"roles":                 user.Roles,
					"activeRole":            user.ActiveRole,
					"roleSelectionRequired": user.ActiveRole == "",
				},
				"serverTime":       now,
				"requesterSamples": requesterSamples,
				"operations":       ops,
			},
		})
	}
}

func EventsHandler(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if websocket.IsWebSocketUpgrade(r) {
			conn, err := upgrader.Upgrade(w, r, nil)
			if err != nil {
				return
			}
			service.GlobalHub.Register(conn)
			defer service.GlobalHub.Unregister(conn)

			for {
				if _, _, err := conn.ReadMessage(); err != nil {
					break
				}
			}
			return
		}

		var since int64 = 0
		if s := r.URL.Query().Get("since"); s != "" {
			if v, err := strconv.ParseInt(s, 10, 64); err == nil {
				since = v
			}
		}

		events, cursor, err := service.GetRealtimeEventsSince(db, since)
		if err != nil {
			SendError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}

		SendJSON(w, http.StatusOK, map[string]interface{}{
			"data": map[string]interface{}{
				"events": events,
				"cursor": cursor,
			},
		})
	}
}

