		}

		result, err := service.CheckServiceability(db, req)
		if err != nil {
			SendError(w, http.StatusInternalServerError, "internal_error", err.Error())
			return
		}

		respData := map[string]interface{}{
			"serviceable":           result.Serviceable,
			"reason":                result.Reason,
			"serviceabilityVersion": result.ServiceabilityVersion,
		}
		if result.TargetLaboratoryId != nil {
			respData["targetLaboratoryId"] = *result.TargetLaboratoryId
		}
		if result.EstimatedArrivalAt != nil {
			respData["estimatedArrivalAt"] = *result.EstimatedArrivalAt
		}

		SendJSON(w, http.StatusOK, map[string]interface{}{
