	ErrNotFound               = errors.New("not_found")
	ErrForbidden              = errors.New("forbidden")
	ErrIneligibleWorker       = errors.New("ineligible_worker")
	ErrAssignmentInactive     = errors.New("assignment_inactive")
	ErrAssignmentTaken        = errors.New("assignment_taken")
	ErrOfferNotAvailable      = errors.New("offer_not_available")
	ErrStalePlan              = errors.New("stale_plan")
	ErrInactivePlan           = errors.New("inactive_plan")
	ErrInvalidPlanVersion     = errors.New("invalid_plan_version")
	ErrCompletedWorkImmutable = errors.New("completed_work_immutable")
	ErrCustodyMismatch        = errors.New("custody_mismatch")
	ErrCapacityExhausted      = errors.New("capacity_exhausted")
	ErrCapacityExceeded       = errors.New("capacity_exceeded")
	ErrIncompatibleBatch      = errors.New("incompatible_batch")
	ErrUnserviceable          = errors.New("unserviceable")
