		if errors.Is(err, sql.ErrNoRows) {
			return "", ErrNotFound
		}
		return "", err
	}

	exceptionId := uuid.New().String()
	_, err = db.Exec(`
		INSERT INTO lab_exceptions (exception_id, sample_id, laboratory_id, recorder_id, reason, status, observed_at)
		VALUES ($1, $2, $3, $4, $5, 'exception', NOW())
	`, exceptionId, sampleId, laboratoryId, actor.UserId, reason)
	if err != nil {
		return "", err
	}

	_, _ = db.Exec(`
		UPDATE samples
		SET status = 'exception', exception = jsonb_build_object('reason', $1, 'exceptionId', $2, 'occurredAt', NOW()), updated_at = NOW()
		WHERE sample_id = $3
	`, reason, exceptionId, sampleId)

	var jId *string
	if s.JourneyId.Valid {
		jId = &s.JourneyId.String
	}

	LogAudit(db, actor.UserId, actor.ActiveRole, "record_laboratory_exception", "exception", exceptionId, true, map[string]interface{}{
		"sampleId": sampleId,
		"reason":   reason,
	})

	LogTimeline(db, &sampleId, jId, nil, "laboratory_exception", actor.UserId, actor.ActiveRole, "exception", exceptionId, true, map[string]interface{}{
		"reason": reason,
	})

	BroadcastRealtimeEvent(db, "sample_exception", "sample", sampleId, map[string]interface{}{
		"sampleId": sampleId,
		"status":   "exception",
		"reason":   reason,
	})

	return exceptionId, nil
}

