// API Client for Lab Sample Pickup & Delivery System

const API_BASE = '/api';

export interface User {
  id: string;
  username: string;
  name: string;
  roles: string[];
  active_role: string;
  certifications?: string[];
  assigned_node_id?: string;
  assigned_lab_id?: string;
  current_location?: {
    latitude: number;
    longitude: number;
    updated_at: string;
  };
}

export interface SampleType {
  id: string;
  name: string;
  container_type: string;
  min_temperature: number;
  max_temperature: number;
  requires_qualified_collector: boolean;
  requires_cooled_storage: boolean;
  time_critical: boolean;
  incompatible_with: string[];
}

export interface NetworkLocation {
  id: string;
  name: string;
  code: string;
  type: string; // 'collection_point', 'transfer_hub', 'laboratory', 'combined'
  latitude: number;
  longitude: number;
  address: string;
  is_active: boolean;
  functions: string[]; // ['collection_point', 'transfer_hub', 'laboratory']
  regular_capacity: number;
  cooled_capacity: number;
  regular_reserved: number;
  cooled_reserved: number;
  accepted_sample_types?: string[];
  handling_time_minutes?: number;
}

export interface Connection {
  id: string;
  from_node_id: string;
  to_node_id: string;
  travel_time_minutes: number;
  regular_capacity: number;
  cooled_capacity: number;
  regular_reserved: number;
  cooled_reserved: number;
  is_active: boolean;
}

export interface StatusHistoryItem {
  id: string;
  sample_id: string;
  status: string;
  timestamp: string;
  actor_id?: string;
  actor_name?: string;
  actor_role?: string;
  notes?: string;
  location?: {
    latitude: number;
    longitude: number;
    description?: string;
  };
}

export interface Sample {
  id: string;
  request_id?: string;
  sample_type: string;
  origin_type: string;
  origin_address: string;
  origin_latitude: number;
  origin_longitude: number;
  destination_lab_id?: string;
  collection_window_start?: string;
  collection_window_end?: string;
  delivery_deadline: string;
  status: string; // 'requested', 'offered', 'assigned', 'collected', 'in_transit', 'received', 'exception', 'cancelled', 'expired'
  current_holder_id?: string;
  current_holder_name?: string;
  current_holder_role?: string;
  current_location?: {
    latitude: number;
    longitude: number;
    description?: string;
    updated_at: string;
  };
  is_location_stale?: boolean;
  location_freshness?: 'Fresh' | 'Stale';
  is_exception: boolean;
  exception_reason?: string;
  sealed_at?: string;
  sealed_by_id?: string;
  container_type?: string;
  current_temperature?: number;
  temperature_ok?: boolean;
  created_at: string;
  updated_at: string;
  route_progress?: string;
  current_leg_index?: number;
  total_legs?: number;
  status_history?: StatusHistoryItem[];
  legs?: TransportLeg[];
}

export interface TransportLeg {
  id: string;
  journey_id: string;
  sample_id: string;
  sequence: number;
  leg_type: string; // 'collection', 'transfer', 'final_delivery'
  from_location_name: string;
  from_latitude: number;
  from_longitude: number;
  to_location_name: string;
  to_latitude: number;
  to_longitude: number;
  assigned_worker_id?: string;
  assigned_worker_name?: string;
  status: string; // 'pending', 'offered', 'accepted', 'in_progress', 'completed', 'cancelled'
  requires_qualification?: string;
  is_cooled: boolean;
  pickup_confirmed_by_sender?: boolean;
  pickup_confirmed_by_receiver?: boolean;
  handoff_confirmed_by_sender?: boolean;
  handoff_confirmed_by_receiver?: boolean;
}

export interface Assignment {
  id: string;
  leg_id?: string;
  sample_id: string;
  worker_id: string;
  assignment_type: string; // 'collection', 'transport', 'node_handling', 'lab_intake'
  status: string; // 'offered', 'accepted', 'declined', 'completed', 'cancelled'
  created_at: string;
  expires_at?: string;
  sample?: Sample;
  leg?: TransportLeg;
}

export interface AuditRecord {
  id: string;
  timestamp: string;
  user_id?: string;
  username?: string;
  role?: string;
  action: string;
  entity_type: string;
  entity_id: string;
  outcome: 'success' | 'failure' | 'warning';
  details?: any;
  changes?: any;
}

export interface ServiceabilityCheckRequest {
  origin_latitude: number;
  origin_longitude: number;
  sample_type: string;
  collection_window_start?: string;
  collection_window_end?: string;
  delivery_deadline: string;
}

export interface ServiceabilityCheckResponse {
  serviceable: boolean;
  version: string;
  reason?: string;
  nearest_node?: string;
  distance_km?: number;
  available_lab?: string;
  estimated_travel_minutes?: number;
}

function getAuthHeader(): HeadersInit {
  const token = localStorage.getItem('auth_token');
  const activeRole = localStorage.getItem('active_role');
  const headers: HeadersInit = {
    'Content-Type': 'application/json',
  };
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }
  if (activeRole) {
    headers['X-Active-Role'] = activeRole;
  }
  return headers;
}

async function handleResponse<T>(res: Response): Promise<T> {
  if (!res.ok) {
    let errMsg = `Request failed with status ${res.status}`;
    try {
      const data = await res.json();
      if (data.message) errMsg = data.message;
      else if (data.error) errMsg = data.error;
    } catch {}
    throw new Error(errMsg);
  }
  if (res.status === 204) {
    return {} as T;
  }
  return res.json();
}

export const api = {
  // Auth
  async login(credentials: { username: string; password?: string }): Promise<{ token: string; user: User }> {
    const res = await fetch(`${API_BASE}/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(credentials),
    });
    return handleResponse<{ token: string; user: User }>(res);
  },

  async getCurrentUser(): Promise<User> {
    const res = await fetch(`${API_BASE}/auth/me`, {
      headers: getAuthHeader(),
    });
    return handleResponse<User>(res);
  },

  async switchRole(role: string): Promise<User> {
    const res = await fetch(`${API_BASE}/auth/active-role`, {
      method: 'PUT',
      headers: getAuthHeader(),
      body: JSON.stringify({ role }),
    });
    return handleResponse<User>(res);
  },

  // Serviceability Dry Run
  async checkServiceability(req: ServiceabilityCheckRequest): Promise<ServiceabilityCheckResponse> {
    const res = await fetch(`${API_BASE}/serviceability/check`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify(req),
    });
    return handleResponse<ServiceabilityCheckResponse>(res);
  },

  // Collection Requests
  async createCollectionRequest(data: any): Promise<Sample> {
    const res = await fetch(`${API_BASE}/requests`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify(data),
    });
    return handleResponse<Sample>(res);
  },

  async getMyRequests(): Promise<Sample[]> {
    const res = await fetch(`${API_BASE}/requests/my`, {
      headers: getAuthHeader(),
    });
    return handleResponse<Sample[]>(res);
  },

  // Pre-sealed Sample Ingestion
  async ingestPresealedSample(data: any): Promise<Sample> {
    const res = await fetch(`${API_BASE}/samples/pre-sealed`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify(data),
    });
    return handleResponse<Sample>(res);
  },

  // Samples
  async getSample(id: string): Promise<Sample> {
    const res = await fetch(`${API_BASE}/samples/${id}`, {
      headers: getAuthHeader(),
    });
    return handleResponse<Sample>(res);
  },

