// Complete API Client for Lab Sample Pickup & Delivery System
import { v4 as uuidv4 } from 'uuid';

const API_BASE = '/api';

export interface User {
  userId: string;
  username: string;
  fullName: string;
  roles: string[];
  activeRole: string;
  roleSelectionRequired?: boolean;
}

export interface BootstrapData {
  user: User;
  serverTime: string;
  requesterSamples?: any[];
  operations?: OperationsState;
}

export interface OperationsState {
  samples: SampleItem[];
  workers: WorkerItem[];
  collectionNodes: LocationItem[];
  laboratories: LocationItem[];
  routes: RouteItem[];
  exceptions: SampleItem[];
  serviceabilityVersion?: string;
  lastDisruption?: any;
}

export interface SampleItem {
  sampleId: string;
  requestId?: string;
  journeyId?: string;
  sampleType: string;
  status: string;
  origin?: {
    originType: string;
    address?: string;
    locationId?: string;
    coordinate: { latitude: number; longitude: number };
  };
  destinationLabId?: string;
  currentHolderId?: string;
  currentHolderName?: string;
  currentHolderRole?: string;
  collectionWindowStart?: string;
  collectionWindowEnd?: string;
  deliveryDeadline: string;
  sealedAt?: string;
  sealedBy?: string;
  containerType?: string;
  latestLatitude?: number;
  latestLongitude?: number;
  locationRecordedAt?: string;
  isLocationStale?: boolean;
  locationFreshness?: 'Fresh' | 'Stale';
  isException?: boolean;
  exceptionReason?: string;
  createdAt: string;
  updatedAt: string;
}

export interface WorkerItem {
  userId: string;
  username: string;
  fullName: string;
  roles: string[];
  certifications?: string[];
  assignedNodeId?: string;
  assignedLabId?: string;
  isAvailable?: boolean;
  latestLatitude?: number;
  latestLongitude?: number;
  locationRecordedAt?: string;
  workload?: number;
}

export interface LocationItem {
  locationId: string;
  name: string;
  code: string;
  type: string;
  coordinate: { latitude: number; longitude: number };
  address?: string;
  status: string;
  functions?: { [key: string]: boolean };
  regularCapacity: number;
  cooledCapacity: number;
  regularReserved: number;
  cooledReserved: number;
  regularAvailable?: number;
  cooledAvailable?: number;
  acceptedSampleTypes?: string[];
  handlingTimeMinutes?: number;
}

export interface RouteItem {
  connectionId: string;
  fromNodeId: string;
  toNodeId: string;
  travelTimeMinutes: number;
  regularCapacity: number;
  cooledCapacity: number;
  regularReserved: number;
  cooledReserved: number;
  status: string;
}

export interface RoleWorkData {
  role: string;
  pending: any[];
  inProgress: any[];
  completed: any[];
}

export interface SampleLifecycle {
  sampleId: string;
  sampleType: string;
  status: string;
  origin: any;
  destinationLabId?: string;
  currentHolder?: string;
  collectionWindow?: { start?: string; end?: string };
  deliveryDeadline: string;
  sealedAt?: string;
  sealedBy?: string;
  isLocationStale: boolean;
  timestamps: { [key: string]: string };
  transitions: Array<{
    status: string;
    occurredAt: string;
    actorId?: string;
    actorRole?: string;
    reason?: string;
    details?: any;
  }>;
  checkpoints: Array<{
    checkpointId: string;
    containerType: string;
    observedTemperatureC: number;
    compliant: boolean;
    recordedAt: string;
    recordedBy: string;
  }>;
  handoffs: Array<{
    handoffId: string;
    fromAssignmentId: string;
    toAssignmentId: string;
    senderConfirmed: boolean;
    receiverConfirmed: boolean;
    status: string;
    initiatedAt: string;
    completedAt?: string;
  }>;
  assignments: any[];
  exceptions: any[];
}

export interface AuditRecord {
  auditId: string;
  actorId?: string;
  actorRole?: string;
  action: string;
  entityType: string;
  entityId: string;
  success: boolean;
  occurredAt: string;
  details?: any;
}

function getAuthHeader(): HeadersInit {
  const token = localStorage.getItem('auth_token');
  const activeRole = localStorage.getItem('active_role');
  const headers: HeadersInit = {
    'Content-Type': 'application/json',
  };
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }
  if (activeRole) {
    headers['X-Active-Role'] = activeRole;
  }
  return headers;
}

async function handleResponse<T>(res: Response): Promise<T> {
  if (!res.ok) {
    let errMsg = `Request failed with status ${res.status}`;
    try {
      const data = await res.json();
      if (data.error) errMsg = data.error;
      else if (data.message) errMsg = data.message;
    } catch {}
    throw new Error(errMsg);
  }
  if (res.status === 204) {
    return {} as T;
  }
  const json = await res.json();
  return json.data !== undefined ? json.data : json;
}

export const api = {
  // Authentication
  async login(username: string, password?: string): Promise<{ sessionToken: string; userId: string; roles: string[]; activeRole: string }> {
    const res = await fetch(`${API_BASE}/authenticate-user`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, password: password || '' }),
    });
    return handleResponse<{ sessionToken: string; userId: string; roles: string[]; activeRole: string }>(res);
  },

  async selectActiveRole(role: string): Promise<{ activeRole: string; roles: string[] }> {
    const res = await fetch(`${API_BASE}/select-active-role`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({ role }),
    });
    return handleResponse<{ activeRole: string; roles: string[] }>(res);
  },

  async getUIBootstrap(): Promise<BootstrapData> {
    const res = await fetch(`${API_BASE}/ui/bootstrap`, {
      headers: getAuthHeader(),
    });
    return handleResponse<BootstrapData>(res);
  },

  // Serviceability Dry Run
  async checkServiceability(params: {
    originLatitude: number;
    originLongitude: number;
    sampleType: string;
    collectionWindowStart?: string;
    collectionWindowEnd?: string;
    deliveryDeadline: string;
  }): Promise<{
    serviceable: boolean;
    reason?: string;
    serviceabilityVersion?: string;
    targetLaboratoryId?: string;
    estimatedArrivalAt?: string;
  }> {
    const res = await fetch(`${API_BASE}/check-serviceability`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify(params),
    });
    return handleResponse(res);
  },

  async readServiceabilitySnapshot(): Promise<any> {
    const res = await fetch(`${API_BASE}/read-serviceability-snapshot`, {
      headers: getAuthHeader(),
    });
    return handleResponse(res);
  },

  // Requests & Samples
  async createCollectionRequest(params: {
    requesterId?: string;
    originAddress?: string;
    originLatitude: number;
    originLongitude: number;
    sampleType: string;
    collectionWindowStart?: string;
    collectionWindowEnd?: string;
    deliveryDeadline: string;
  }): Promise<any> {
    const res = await fetch(`${API_BASE}/create-collection-request`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async ingestPresealedSample(params: {
    requesterId?: string;
    originType: string;
    originLocationId?: string;
    originLatitude: number;
    originLongitude: number;
    sampleType: string;
    containerType: string;
    currentTemperatureC?: number;
    deliveryDeadline: string;
  }): Promise<any> {
    const res = await fetch(`${API_BASE}/ingest-presealed-sample`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async collectAndSealSample(params: {
    sampleId: string;
    assignmentId: string;
    containerType: string;
    observedTemperatureC: number;
    collectedAt?: string;
  }): Promise<any> {
    const res = await fetch(`${API_BASE}/collect-and-seal-sample`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        collectedAt: params.collectedAt || new Date().toISOString(),
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async recordHandlingCheckpoint(params: {
    sampleId: string;
    assignmentId?: string;
    locationId?: string;
    containerType: string;
    observedTemperatureC: number;
    recordedAt?: string;
  }): Promise<any> {
    const res = await fetch(`${API_BASE}/record-handling-checkpoint`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        recordedAt: params.recordedAt || new Date().toISOString(),
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async confirmLaboratoryReceipt(params: {
    sampleId: string;
    laboratoryId: string;
    receivedAt?: string;
  }): Promise<any> {
    const res = await fetch(`${API_BASE}/confirm-laboratory-receipt`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        receivedAt: params.receivedAt || new Date().toISOString(),
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async recordLaboratoryException(params: {
    sampleId: string;
    laboratoryId: string;
    reason: string;
    observedAt?: string;
  }): Promise<any> {
    const res = await fetch(`${API_BASE}/record-laboratory-exception`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        observedAt: params.observedAt || new Date().toISOString(),
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  // Custody Handoff
  async initiateHandoff(params: {
    sampleId: string;
    fromAssignmentId: string;
    toAssignmentId: string;
    receiverId: string;
    initiatedAt?: string;
  }): Promise<any> {
    const res = await fetch(`${API_BASE}/initiate-handoff`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        initiatedAt: params.initiatedAt || new Date().toISOString(),
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async confirmHandoff(params: {
    handoffId: string;
    confirmationSide: 'sender' | 'receiver';
    confirmedAt?: string;
  }): Promise<any> {
    const res = await fetch(`${API_BASE}/confirm-handoff`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        confirmedAt: params.confirmedAt || new Date().toISOString(),
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  // Work & Assignments
  async listRoleWork(role?: string, status?: string): Promise<RoleWorkData> {
    const res = await fetch(`${API_BASE}/list-role-work`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({ role: role || '', status: status || '' }),
    });
    return handleResponse<RoleWorkData>(res);
  },

  async acceptAssignment(assignmentId: string): Promise<any> {
    const res = await fetch(`${API_BASE}/accept-assignment`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        assignmentId,
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async declineAssignment(assignmentId: string, reason?: string): Promise<any> {
    const res = await fetch(`${API_BASE}/decline-assignment`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        assignmentId,
        reason: reason || 'Declined by worker',
        declinedAt: new Date().toISOString(),
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async recordWorkerLocation(params: {
    assignmentId?: string;
    coordinate: { latitude: number; longitude: number };
    sequence?: number;
    recordedAt?: string;
  }): Promise<any> {
    const res = await fetch(`${API_BASE}/record-worker-location`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        assignmentId: params.assignmentId || '',
        coordinate: params.coordinate,
        sequence: params.sequence || 1,
        recordedAt: params.recordedAt || new Date().toISOString(),
      }),
    });
    return handleResponse(res);
  },

  async updateAssignmentProgress(params: {
    assignmentId: string;
    status: string;
  }): Promise<any> {
    const res = await fetch(`${API_BASE}/update-assignment-progress`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        assignmentId: params.assignmentId,
        status: params.status,
        occurredAt: new Date().toISOString(),
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  // Operations, Sample Lifecycle & Audit
  async readOperationsState(filters?: any): Promise<OperationsState> {
    const res = await fetch(`${API_BASE}/read-operations-state`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({ filters: filters || {} }),
    });
    return handleResponse<OperationsState>(res);
  },

  async readSampleLifecycle(sampleId: string): Promise<SampleLifecycle> {
    const res = await fetch(`${API_BASE}/read-sample-lifecycle`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({ sampleId }),
    });
    return handleResponse<SampleLifecycle>(res);
  },

  async readSampleState(sampleId: string): Promise<SampleItem> {
    const res = await fetch(`${API_BASE}/read-sample-state/${sampleId}`, {
      headers: getAuthHeader(),
    });
    return handleResponse<SampleItem>(res);
  },

  async readJourneyPlan(journeyId: string): Promise<any> {
    const res = await fetch(`${API_BASE}/read-journey-plan`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({ journeyId }),
    });
    return handleResponse(res);
  },

  async searchAuditTrail(params?: {
    query?: string;
    actorId?: string;
    entityType?: string;
    entityId?: string;
    action?: string;
    role?: string;
    limit?: number;
  }): Promise<{ total: number; records: AuditRecord[] }> {
    const res = await fetch(`${API_BASE}/search-audit-trail`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        query: params?.query || '',
        actorId: params?.actorId || '',
        entityType: params?.entityType || '',
        entityId: params?.entityId || '',
        action: params?.action || '',
        role: params?.role || '',
        limit: params?.limit || 50,
      }),
    });
    return handleResponse<{ total: number; records: AuditRecord[] }>(res);
  },

  // Journeys & Disruptions
  async rerouteJourney(params: { journeyId: string; targetLaboratoryId: string; reason?: string }): Promise<any> {
    const res = await fetch(`${API_BASE}/reroute-journey`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        reason: params.reason || 'Rerouted by dispatcher',
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async cancelJourney(params: { journeyId: string; reason?: string }): Promise<any> {
    const res = await fetch(`${API_BASE}/cancel-journey`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        reason: params.reason || 'Cancelled by dispatcher',
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async reportDisruption(params: { resourceType: string; resourceId: string; reason?: string }): Promise<any> {
    const res = await fetch(`${API_BASE}/report-disruption`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        reason: params.reason || 'Resource unavailable disruption',
        occurredAt: new Date().toISOString(),
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  // Capacity & Network Configuration
  async configureCapacity(params: {
    locationId?: string;
    connectionId?: string;
    regularCapacity: number;
    cooledCapacity: number;
  }): Promise<any> {
    const res = await fetch(`${API_BASE}/configure-capacity`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async configureLaboratoryAcceptance(params: {
    laboratoryId: string;
    acceptedSampleTypes: string[];
  }): Promise<any> {
    const res = await fetch(`${API_BASE}/configure-laboratory-acceptance`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async setLocationStatus(params: { locationId: string; status: string }): Promise<any> {
    const res = await fetch(`${API_BASE}/set-location-status`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async createLocation(params: any): Promise<any> {
    const res = await fetch(`${API_BASE}/create-location`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async createSampleType(params: any): Promise<any> {
    const res = await fetch(`${API_BASE}/create-sample-type`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async createUser(params: any): Promise<any> {
    const res = await fetch(`${API_BASE}/create-user`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async updateUserAccess(params: any): Promise<any> {
    const res = await fetch(`${API_BASE}/update-user-access`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },
};

