import React, { useEffect, useState } from 'react';
import { api, SampleLifecycle, SampleItem, User } from '../api';
import { X, AlertTriangle, CheckCircle, Clock, MapPin, User as UserIcon, ShieldAlert, RefreshCw, Thermometer } from 'lucide-react';

interface SampleDetailModalProps {
  sampleId: string;
  currentUser: User;
  onClose: () => void;
  onRefresh?: () => void;
}

export const SampleDetailModal: React.FC<SampleDetailModalProps> = ({
  sampleId,
  currentUser,
  onClose,
  onRefresh,
}) => {
  const [lifecycle, setLifecycle] = useState<SampleLifecycle | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  // Form states for in-modal actions
  const [checkpointTemp, setCheckpointTemp] = useState<string>('4.0');
  const [checkpointContainer, setCheckpointContainer] = useState<string>('insulated_cooler');
  const [checkpointMsg, setCheckpointMsg] = useState<string | null>(null);
  const [actionLoading, setActionLoading] = useState<boolean>(false);

  const loadData = async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await api.readSampleLifecycle(sampleId);
      setLifecycle(data);
    } catch (err: any) {
      setError(err.message || 'Failed to load sample lifecycle');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [sampleId]);

  const handleRecordCheckpoint = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setActionLoading(true);
      setCheckpointMsg(null);
      const res = await api.recordHandlingCheckpoint({
        sampleId,
        containerType: checkpointContainer,
        observedTemperatureC: parseFloat(checkpointTemp),
      });
      setCheckpointMsg(
        res.compliant
          ? 'Checkpoint recorded: Temperature & Container are compliant.'
          : `Warning: Temperature or Container violated specifications! Sample marked as exception (${res.sampleStatus}).`
      );
      await loadData();
      if (onRefresh) onRefresh();
    } catch (err: any) {
      setCheckpointMsg(`Error: ${err.message}`);
    } finally {
      setActionLoading(false);
    }
  };

  const handleConfirmHandoff = async (handoffId: string, side: 'sender' | 'receiver') => {
    try {
      setActionLoading(true);
      await api.confirmHandoff({
        handoffId,
        confirmationSide: side,
      });
      await loadData();
      if (onRefresh) onRefresh();
    } catch (err: any) {
      alert(`Handoff error: ${err.message}`);
    } finally {
      setActionLoading(false);
    }
  };

  const handleLabReceipt = async (accepted: boolean) => {
    const labId = lifecycle?.destinationLabId || 'lab_central';
    try {
      setActionLoading(true);
      if (accepted) {
        await api.confirmLaboratoryReceipt({ sampleId, laboratoryId: labId });
      } else {
        const reason = prompt('Enter exception reason for lab rejection:');
        if (!reason) return;
        await api.recordLaboratoryException({ sampleId, laboratoryId: labId, reason });
      }
      await loadData();
      if (onRefresh) onRefresh();
    } catch (err: any) {
      alert(`Lab receipt error: ${err.message}`);
    } finally {
      setActionLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-4xl w-full max-h-[90vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-200">

        {/* Header */}
        <div className="px-6 py-4 bg-slate-900 text-white flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <span className="text-xl">🧪</span>
            <div>
              <h2 className="text-lg font-bold">Sample Details: {sampleId}</h2>
              <p className="text-xs text-slate-300">Lifecycle, Chain of Custody & Status History</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-slate-400 hover:text-white p-1.5 rounded-lg hover:bg-slate-800 transition"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="p-6 overflow-y-auto space-y-6 flex-1 bg-slate-50">
          {loading && (
            <div className="flex items-center justify-center py-12 text-slate-500">
              <RefreshCw className="w-6 h-6 animate-spin mr-2 text-indigo-600" />
              <span>Loading lifecycle data...</span>
            </div>
          )}

          {error && (
            <div className="p-4 bg-red-50 border border-red-200 rounded-lg text-red-700 text-sm flex items-center">
              <AlertTriangle className="w-5 h-5 mr-2 flex-shrink-0" />
              <span>{error}</span>
            </div>
          )}

          {lifecycle && (
            <>
              {/* Exception Alert Banner */}
              {lifecycle.exceptions && lifecycle.exceptions.length > 0 && (
                <div className="p-4 bg-red-100 border-l-4 border-red-600 rounded-r-lg text-red-900 shadow-sm">
                  <div className="flex items-center mb-1">
                    <ShieldAlert className="w-5 h-5 text-red-600 mr-2 flex-shrink-0" />
                    <span className="font-bold text-sm uppercase tracking-wide">Exception Flagged</span>
                  </div>
                  {lifecycle.exceptions.map((ex: any, idx: number) => (
                    <div key={idx} className="text-xs ml-7 mt-0.5">
                      • <b>Reason:</b> {ex.reason || 'Handling anomaly'} ({new Date(ex.occurredAt || ex.timestamp || Date.now()).toLocaleString()})
                    </div>
                  ))}
                </div>
              )}

              {/* Status & Key Metrics Grid */}
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                {/* Status */}
                <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                  <div className="text-xs text-slate-500 font-medium">Sample Status</div>
                  <div className="mt-1 flex items-center">
                    <span className={`inline-flex px-2.5 py-1 rounded-full text-xs font-bold uppercase tracking-wider ${
                      lifecycle.status === 'received' ? 'bg-green-100 text-green-800' :
                      lifecycle.status === 'exception' ? 'bg-red-100 text-red-800' :
                      lifecycle.status === 'in_transit' ? 'bg-blue-100 text-blue-800' :
                      'bg-amber-100 text-amber-800'
                    }`}>
                      {lifecycle.status}
                    </span>
                  </div>
                  <div className="text-[11px] text-slate-400 mt-2">Type: <span className="font-semibold text-slate-700">{lifecycle.sampleType}</span></div>
                </div>

                {/* Current Custodian */}
                <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                  <div className="text-xs text-slate-500 font-medium">Current Custodian</div>
                  <div className="mt-1 flex items-center text-sm font-semibold text-slate-800">
                    <UserIcon className="w-4 h-4 mr-1 text-indigo-600" />
                    <span>{lifecycle.currentHolder || 'Unassigned / At Node'}</span>
                  </div>
                  <div className="text-[11px] text-slate-400 mt-2">Sealed: {lifecycle.sealedAt ? new Date(lifecycle.sealedAt).toLocaleTimeString() : 'Not yet'}</div>
                </div>

                {/* Location Freshness */}
                <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                  <div className="text-xs text-slate-500 font-medium">Location Freshness</div>
                  <div className="mt-1 flex items-center">
                    <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-semibold ${
                      lifecycle.isLocationStale ? 'bg-amber-100 text-amber-800' : 'bg-emerald-100 text-emerald-800'
                    }`}>
                      <span className={`w-1.5 h-1.5 rounded-full mr-1.5 ${lifecycle.isLocationStale ? 'bg-amber-500' : 'bg-emerald-500'}`}></span>
                      {lifecycle.isLocationStale ? 'Stale' : 'Fresh'}
                    </span>
                  </div>
                  <div className="text-[11px] text-slate-400 mt-2">
                    Updated: {lifecycle.timestamps?.locationRecordedAt ? new Date(lifecycle.timestamps.locationRecordedAt).toLocaleTimeString() : 'Recent'}
                  </div>
                </div>

                {/* Delivery Deadline */}
                <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                  <div className="text-xs text-slate-500 font-medium">Delivery Deadline</div>
                  <div className="mt-1 text-sm font-semibold text-slate-800 flex items-center">
                    <Clock className="w-4 h-4 mr-1 text-amber-600" />
                    <span>{lifecycle.deliveryDeadline ? new Date(lifecycle.deliveryDeadline).toLocaleTimeString() : 'N/A'}</span>
                  </div>
                  <div className="text-[11px] text-slate-400 mt-2">
                    Date: {lifecycle.deliveryDeadline ? new Date(lifecycle.deliveryDeadline).toLocaleDateString() : ''}
                  </div>
                </div>
              </div>

              {/* Route Progress / Transport Legs */}
              {lifecycle.assignments && lifecycle.assignments.length > 0 && (
                <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                  <h3 className="text-sm font-bold text-slate-800 mb-3 flex items-center">
                    <MapPin className="w-4 h-4 mr-1.5 text-indigo-600" />
                    Route Progress & Assignments
                  </h3>
                  <div className="space-y-2">
                    {lifecycle.assignments.map((as: any, idx: number) => (
                      <div key={idx} className="flex items-center justify-between p-2.5 bg-slate-50 rounded border border-slate-200 text-xs">
                        <div className="flex items-center space-x-2">
                          <span className="w-5 h-5 rounded-full bg-indigo-100 text-indigo-700 font-bold flex items-center justify-center text-[10px]">
                            {idx + 1}
                          </span>
                          <div>
                            <span className="font-semibold text-slate-800 capitalize">{as.assignmentType || as.role || 'Transport Leg'}</span>
                            <span className="text-slate-500 ml-2">Worker: {as.assignedWorkerId || as.workerId || 'Pending'}</span>
                          </div>
                        </div>
                        <div className="flex items-center space-x-3">
                          <span className={`px-2 py-0.5 rounded font-semibold capitalize ${
                            as.status === 'completed' || as.status === 'accepted' ? 'bg-emerald-100 text-emerald-800' :
                            as.status === 'declined' ? 'bg-red-100 text-red-800' :
                            'bg-amber-100 text-amber-800'
                          }`}>
                            {as.status}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Custody Handoffs */}
              {lifecycle.handoffs && lifecycle.handoffs.length > 0 && (
                <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                  <h3 className="text-sm font-bold text-slate-800 mb-3 flex items-center">
                    <CheckCircle className="w-4 h-4 mr-1.5 text-indigo-600" />
                    Custody Handoffs (Dual Confirmation)
                  </h3>
                  <div className="space-y-2">
                    {lifecycle.handoffs.map((h) => (
                      <div key={h.handoffId} className="p-3 bg-slate-50 rounded border border-slate-200 text-xs flex items-center justify-between">
                        <div>
                          <div className="font-semibold text-slate-800">Handoff: {h.handoffId.slice(0, 8)}...</div>
                          <div className="text-slate-500 mt-1 flex space-x-4">
                            <span>Sender Confirmed: <b className={h.senderConfirmed ? 'text-green-600' : 'text-amber-600'}>{h.senderConfirmed ? 'Yes' : 'Pending'}</b></span>
                            <span>Receiver Confirmed: <b className={h.receiverConfirmed ? 'text-green-600' : 'text-amber-600'}>{h.receiverConfirmed ? 'Yes' : 'Pending'}</b></span>
                          </div>
                        </div>
                        <div className="flex items-center space-x-2">
                          {!h.receiverConfirmed && (
                            <button
                              disabled={actionLoading}
                              onClick={() => handleConfirmHandoff(h.handoffId, 'receiver')}
                              className="px-3 py-1 bg-indigo-600 hover:bg-indigo-700 text-white rounded font-medium shadow-sm transition disabled:opacity-50"
                            >
                              Confirm as Receiver
                            </button>
                          )}
                          {!h.senderConfirmed && (
                            <button
                              disabled={actionLoading}
                              onClick={() => handleConfirmHandoff(h.handoffId, 'sender')}
                              className="px-3 py-1 bg-slate-700 hover:bg-slate-800 text-white rounded font-medium shadow-sm transition disabled:opacity-50"
                            >
                              Confirm as Sender
                            </button>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Status Timeline / Ordered Status History */}
              <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                <h3 className="text-sm font-bold text-slate-800 mb-3 flex items-center">
                  <Clock className="w-4 h-4 mr-1.5 text-indigo-600" />
                  Status History & Timeline
                </h3>
                {lifecycle.transitions && lifecycle.transitions.length > 0 ? (
                  <div className="relative border-l-2 border-slate-200 ml-3 space-y-4 pl-4 py-1">
                    {lifecycle.transitions.map((t, idx) => (
                      <div key={idx} className="relative">
                        <span className="absolute -left-[21px] top-1 w-2.5 h-2.5 rounded-full bg-indigo-600 ring-4 ring-white" />
                        <div className="flex items-center justify-between text-xs">
                          <span className="font-bold uppercase text-slate-800 tracking-wide">{t.status}</span>
                          <span className="text-slate-400">{new Date(t.occurredAt).toLocaleString()}</span>
                        </div>
                        <div className="text-xs text-slate-600 mt-0.5">
                          Actor: <span className="font-medium">{t.actorId || 'System'}</span> {t.actorRole ? `(${t.actorRole})` : ''}
                        </div>
                        {t.reason && <div className="text-xs text-red-600 mt-0.5">Note: {t.reason}</div>}
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-xs text-slate-400 italic">No transition history recorded yet.</div>
                )}
              </div>

              {/* Handling Checkpoints / Cold-Chain Monitoring */}
              <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                <h3 className="text-sm font-bold text-slate-800 mb-3 flex items-center">
                  <Thermometer className="w-4 h-4 mr-1.5 text-indigo-600" />
                  Handling Checkpoints & Temperature
                </h3>

                {lifecycle.checkpoints && lifecycle.checkpoints.length > 0 && (
                  <div className="space-y-2 mb-4">
                    {lifecycle.checkpoints.map((cp) => (
                      <div key={cp.checkpointId} className="p-2.5 bg-slate-50 rounded border border-slate-200 flex items-center justify-between text-xs">
                        <div>
                          <span className="font-semibold text-slate-800">{cp.containerType}</span>
                          <span className="text-slate-500 ml-2">Observed: <b>{cp.observedTemperatureC}°C</b></span>
                          <span className="text-slate-400 ml-2">({new Date(cp.recordedAt).toLocaleTimeString()})</span>
                        </div>
                        <span className={`px-2 py-0.5 rounded font-semibold ${cp.compliant ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                          {cp.compliant ? 'Compliant' : 'Out of Spec'}
                        </span>
                      </div>
                    ))}
                  </div>
                )}

                {/* Form to record new checkpoint */}
                <form onSubmit={handleRecordCheckpoint} className="p-3 bg-slate-100 rounded-lg space-y-3">
                  <div className="text-xs font-semibold text-slate-700">Record Handling Checkpoint</div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    <div>
                      <label className="text-[11px] text-slate-500 block mb-1">Container Type</label>
                      <select
                        value={checkpointContainer}
                        onChange={(e) => setCheckpointContainer(e.target.value)}
                        className="w-full text-xs p-1.5 rounded border border-slate-300 bg-white"
                      >
                        <option value="insulated_cooler">Insulated Cooler (Cold-chain)</option>
                        <option value="standard_biohazard_box">Standard Biohazard Box</option>
                        <option value="ambient_pouch">Ambient Pouch</option>
                      </select>
                    </div>
                    <div>
                      <label className="text-[11px] text-slate-500 block mb-1">Observed Temperature (°C)</label>
                      <input
                        type="number"
                        step="0.1"
                        value={checkpointTemp}
                        onChange={(e) => setCheckpointTemp(e.target.value)}
                        className="w-full text-xs p-1.5 rounded border border-slate-300 bg-white"
                        required
                      />
                    </div>
                  </div>
                  {checkpointMsg && (
                    <div className="text-xs p-2 rounded bg-white border border-slate-200 font-medium text-slate-800">
                      {checkpointMsg}
                    </div>
                  )}
                  <button
                    type="submit"
                    disabled={actionLoading}
                    className="px-3 py-1.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded text-xs font-semibold transition shadow-sm disabled:opacity-50"
                  >
                    Record Checkpoint
                  </button>
                </form>
              </div>

              {/* Lab Intake Actions (if laboratory role or admin) */}
              {(currentUser.activeRole === 'laboratory_team' || currentUser.activeRole === 'administrator' || currentUser.activeRole === 'admin') && lifecycle.status !== 'received' && (
                <div className="bg-indigo-50 p-4 rounded-lg border border-indigo-200">
                  <h3 className="text-sm font-bold text-indigo-900 mb-2">Laboratory Intake Actions</h3>
                  <p className="text-xs text-indigo-700 mb-3">Accept incoming sample or log a laboratory acceptance exception.</p>
                  <div className="flex space-x-3">
                    <button
                      onClick={() => handleLabReceipt(true)}
                      disabled={actionLoading}
                      className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-xs font-bold shadow transition disabled:opacity-50"
                    >
                      Accept Sample into Lab
                    </button>
                    <button
                      onClick={() => handleLabReceipt(false)}
                      disabled={actionLoading}
                      className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg text-xs font-bold shadow transition disabled:opacity-50"
                    >
                      Reject with Exception
                    </button>
                  </div>
                </div>
              )}
            </>
          )}
        </div>

        {/* Footer */}
        <div className="px-6 py-3 bg-white border-t border-slate-200 flex justify-end">
          <button
            onClick={onClose}
            className="px-4 py-2 bg-slate-200 hover:bg-slate-300 text-slate-800 rounded-lg text-xs font-semibold transition"
          >
            Close
          </button>
        </div>

      </div>
    </div>
  );
};

