import React, { useState, useEffect } from 'react';
import { api, User, SampleItem } from '../api';
import { MapPin, Calendar, Clock, AlertCircle, CheckCircle2, ShieldCheck, Eye, PlusCircle, RefreshCw } from 'lucide-react';

interface RequesterViewProps {
  user: User;
  onSelectSample: (sampleId: string) => void;
}

export const RequesterView: React.FC<RequesterViewProps> = ({ user, onSelectSample }) => {
  const [currentWork, setCurrentWork] = useState<any[]>([]);
  const [pastWork, setPastWork] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);

  // Form Mode: 'collection' | 'presealed' | 'serviceability'
  const [activeFormTab, setActiveFormTab] = useState<'collection' | 'presealed' | 'serviceability'>('collection');

  // Request Form fields
  const [originAddress, setOriginAddress] = useState('123 Indiranagar 100ft Rd, Bangalore');
  const [originLat, setOriginLat] = useState('12.9716');
  const [originLng, setOriginLng] = useState('77.5946');
  const [sampleType, setSampleType] = useState('Amber');
  const [windowStart, setWindowStart] = useState(() => new Date(Date.now() + 30 * 60000).toISOString().slice(0, 16));
  const [windowEnd, setWindowEnd] = useState(() => new Date(Date.now() + 90 * 60000).toISOString().slice(0, 16));
  const [deadline, setDeadline] = useState(() => new Date(Date.now() + 240 * 60000).toISOString().slice(0, 16));

  // Pre-sealed fields
  const [presealedOriginType, setPresealedOriginType] = useState<'clinic' | 'network_node'>('clinic');
  const [presealedContainer, setPresealedContainer] = useState('insulated_cooler');
  const [presealedTemp, setPresealedTemp] = useState('4.0');

  // Status & Validation states
  const [formError, setFormError] = useState<string | null>(null);
  const [formSuccess, setFormSuccess] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  // Serviceability Dry Run state
  const [dryRunResult, setDryRunResult] = useState<{
    serviceable: boolean;
    reason?: string;
    version?: string;
    lab?: string;
    eta?: string;
  } | null>(null);

  const loadWork = async () => {
    try {
      setLoading(true);
      const res = await api.listRoleWork('requester');
      const pendingAndActive = [...(res.pending || []), ...(res.inProgress || [])];
      setCurrentWork(pendingAndActive);
      setPastWork(res.completed || []);
    } catch (err: any) {
      console.error('Failed to load work:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadWork();
  }, [refreshKey]);

  // Handle Serviceability Dry Run
  const handleCheckServiceability = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormError(null);
    setFormSuccess(null);
    setDryRunResult(null);

    const lat = parseFloat(originLat);
    const lng = parseFloat(originLng);

    if (isNaN(lat) || isNaN(lng)) {
      setFormError('Valid origin latitude and longitude are required');
      return;
    }

    try {
      setSubmitting(true);
      const res = await api.checkServiceability({
        originLatitude: lat,
        originLongitude: lng,
        sampleType,
        collectionWindowStart: new Date(windowStart).toISOString(),
        collectionWindowEnd: new Date(windowEnd).toISOString(),
        deliveryDeadline: new Date(deadline).toISOString(),
      });
      setDryRunResult({
        serviceable: res.serviceable,
        reason: res.reason,
        version: res.serviceabilityVersion,
        lab: res.targetLaboratoryId,
        eta: res.estimatedArrivalAt,
      });
    } catch (err: any) {
      setFormError(err.message || 'Serviceability check failed');
    } finally {
      setSubmitting(false);
    }
  };

