  const [sampleType, setSampleType] = useState('Amber');
  const [windowStart, setWindowStart] = useState(() => new Date(Date.now() + 30 * 60000).toISOString().slice(0, 16));
  const [windowEnd, setWindowEnd] = useState(() => new Date(Date.now() + 90 * 60000).toISOString().slice(0, 16));
  const [deadline, setDeadline] = useState(() => new Date(Date.now() + 240 * 60000).toISOString().slice(0, 16));

  // Pre-sealed fields
  const [presealedOriginType, setPresealedOriginType] = useState<'clinic' | 'network_node'>('clinic');
  const [presealedContainer, setPresealedContainer] = useState('insulated_cooler');
  const [presealedTemp, setPresealedTemp] = useState('4.0');

  // Status & Validation states
  const [formError, setFormError] = useState<string | null>(null);
  const [formSuccess, setFormSuccess] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  // Serviceability Dry Run state
  const [dryRunResult, setDryRunResult] = useState<{
    serviceable: boolean;
    reason?: string;
    version?: string;
    lab?: string;
    eta?: string;
  } | null>(null);

  const loadWork = async () => {
    try {
      setLoading(true);
      const res = await api.listRoleWork('requester');
      const pendingAndActive = [...(res.pending || []), ...(res.inProgress || [])];
      setCurrentWork(pendingAndActive);
      setPastWork(res.completed || []);
    } catch (err: any) {
      console.error('Failed to load work:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadWork();
  }, [refreshKey]);

  // Handle Serviceability Dry Run
  const handleCheckServiceability = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormError(null);
    setFormSuccess(null);
    setDryRunResult(null);

    const lat = parseFloat(originLat);
    const lng = parseFloat(originLng);

    if (isNaN(lat) || isNaN(lng)) {
      setFormError('Valid origin latitude and longitude are required');
      return;
    }

    try {
      setSubmitting(true);
      const res = await api.checkServiceability({
        originLatitude: lat,
        originLongitude: lng,
        sampleType,
        collectionWindowStart: new Date(windowStart).toISOString(),
        collectionWindowEnd: new Date(windowEnd).toISOString(),
        deliveryDeadline: new Date(deadline).toISOString(),
      });
      setDryRunResult({
        serviceable: res.serviceable,
        reason: res.reason,
        version: res.serviceabilityVersion,
        lab: res.targetLaboratoryId,
        eta: res.estimatedArrivalAt,
      });
    } catch (err: any) {
      setFormError(err.message || 'Serviceability check failed');
    } finally {
      setSubmitting(false);
    }
  };

  // Handle Create Collection Request
  const handleCreateRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormError(null);
    setFormSuccess(null);

    const lat = parseFloat(originLat);
    const lng = parseFloat(originLng);

    if (!originAddress.trim()) {
      setFormError('Origin address is required');
      return;
    }
    if (isNaN(lat) || isNaN(lng)) {
      setFormError('Valid origin latitude and longitude are required');
      return;
    }

    const start = new Date(windowStart);
    const end = new Date(windowEnd);
    const dline = new Date(deadline);

    if (start >= end) {
      setFormError('Collection window start must be before end');
      return;
    }
    if (end >= dline) {
      setFormError('Delivery deadline must be strictly after collection window');
      return;
    }

    try {
      setSubmitting(true);
      const res = await api.createCollectionRequest({
        requesterId: user.userId,
        originAddress,
        originLatitude: lat,
        originLongitude: lng,
        sampleType,
        collectionWindowStart: start.toISOString(),
        collectionWindowEnd: end.toISOString(),
        deliveryDeadline: dline.toISOString(),
      });

      setFormSuccess(`Collection Request Created successfully! Sample ID: ${res.sampleId}`);
      setRefreshKey((k) => k + 1);
    } catch (err: any) {
      setFormError(err.message || 'Failed to create collection request');
    } finally {
      setSubmitting(false);
    }
  };

  // Handle Ingest Pre-sealed Sample
  const handleIngestPresealed = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormError(null);
    setFormSuccess(null);

    const lat = parseFloat(originLat);
    const lng = parseFloat(originLng);
    const dline = new Date(deadline);

    try {
      setSubmitting(true);
      const res = await api.ingestPresealedSample({
        requesterId: user.userId,
        originType: presealedOriginType,
        originLatitude: lat,
        originLongitude: lng,
        sampleType,
        containerType: presealedContainer,
        currentTemperatureC: parseFloat(presealedTemp),
        deliveryDeadline: dline.toISOString(),
      });

      setFormSuccess(`Pre-sealed sample registered! Sample ID: ${res.sampleId}`);
      setRefreshKey((k) => k + 1);
    } catch (err: any) {
      setFormError(err.message || 'Failed to ingest pre-sealed sample');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="space-y-8">
      {/* Forms Section */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        {/* Tab Header */}
        <div className="flex border-b border-slate-200 bg-slate-50 px-6 pt-4 space-x-6">
          <button
            onClick={() => { setActiveFormTab('collection'); setFormError(null); setFormSuccess(null); }}
            className={`pb-3 text-sm font-semibold border-b-2 transition ${
              activeFormTab === 'collection'
                ? 'border-indigo-600 text-indigo-600'
                : 'border-transparent text-slate-500 hover:text-slate-800'
            }`}
          >
            Create Collection Request
          </button>
          <button
            onClick={() => { setActiveFormTab('serviceability'); setFormError(null); setFormSuccess(null); }}
            className={`pb-3 text-sm font-semibold border-b-2 transition ${
              activeFormTab === 'serviceability'
                ? 'border-indigo-600 text-indigo-600'
                : 'border-transparent text-slate-500 hover:text-slate-800'
            }`}
          >
            Check Serviceability (Dry Run)
          </button>
          <button
            onClick={() => { setActiveFormTab('presealed'); setFormError(null); setFormSuccess(null); }}
            className={`pb-3 text-sm font-semibold border-b-2 transition ${
              activeFormTab === 'presealed'
                ? 'border-indigo-600 text-indigo-600'
                : 'border-transparent text-slate-500 hover:text-slate-800'
            }`}
          >
            Register Pre-sealed Sample
          </button>
        </div>

        {/* Form Body */}
        <div className="p-6">
          {formError && (
            <div className="mb-4 p-3.5 bg-red-50 border border-red-200 rounded-lg text-red-700 text-sm flex items-center">
              <AlertCircle className="w-5 h-5 mr-2 flex-shrink-0" />
              <span>{formError}</span>
            </div>
          )}

          {formSuccess && (
            <div className="mb-4 p-3.5 bg-emerald-50 border border-emerald-200 rounded-lg text-emerald-800 text-sm flex items-center">
              <CheckCircle2 className="w-5 h-5 mr-2 flex-shrink-0" />
              <span>{formSuccess}</span>
            </div>
          )}

          {/* Form: Check Serviceability Dry Run */}
          {activeFormTab === 'serviceability' && (
            <form onSubmit={handleCheckServiceability} className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Origin Latitude</label>
                  <input
                    type="text"
                    value={originLat}
                    onChange={(e) => setOriginLat(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300 focus:ring-1 focus:ring-indigo-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Origin Longitude</label>
                  <input
                    type="text"
                    value={originLng}
                    onChange={(e) => setOriginLng(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300 focus:ring-1 focus:ring-indigo-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Sample Type</label>
                  <select
                    value={sampleType}
                    onChange={(e) => setSampleType(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300 bg-white focus:ring-1 focus:ring-indigo-500"
                  >
                    <option value="Amber">Amber (Standard)</option>
                    <option value="Indigo">Indigo (Separated)</option>
                    <option value="Frost">Frost (Cold-chain required)</option>
                    <option value="Pulse">Pulse (Time-critical / No batch delay)</option>
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Collection Window Start</label>
                  <input
                    type="datetime-local"
                    value={windowStart}
                    onChange={(e) => setWindowStart(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300 focus:ring-1 focus:ring-indigo-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Collection Window End</label>
                  <input
                    type="datetime-local"
                    value={windowEnd}
                    onChange={(e) => setWindowEnd(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300 focus:ring-1 focus:ring-indigo-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Delivery Deadline</label>
                  <input
                    type="datetime-local"
                    value={deadline}
                    onChange={(e) => setDeadline(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300 focus:ring-1 focus:ring-indigo-500"
                    required
                  />
                </div>
              </div>

              <div className="pt-2 flex items-center justify-between">
                <button
                  type="submit"
                  disabled={submitting}
                  className="px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg text-xs font-bold transition shadow disabled:opacity-50 flex items-center"
                >
                  <ShieldCheck className="w-4 h-4 mr-2" />
                  Run Serviceability Dry Run
                </button>
                <span className="text-xs text-slate-400">Dry run does NOT create samples or reserve capacity.</span>
              </div>

              {dryRunResult && (
                <div className={`mt-4 p-4 rounded-lg border ${dryRunResult.serviceable ? 'bg-emerald-50 border-emerald-200 text-emerald-900' : 'bg-red-50 border-red-200 text-red-900'}`}>
                  <div className="flex items-center font-bold text-sm">
                    {dryRunResult.serviceable ? <CheckCircle2 className="w-5 h-5 text-emerald-600 mr-2" /> : <AlertCircle className="w-5 h-5 text-red-600 mr-2" />}
                    <span>{dryRunResult.serviceable ? 'Location & Sample are SERVICEABLE' : 'UNSERVICEABLE'}</span>
                  </div>
                  <div className="text-xs mt-2 space-y-1">
                    {dryRunResult.reason && <div><b>Reason:</b> {dryRunResult.reason}</div>}
                    {dryRunResult.version && <div><b>Calculation Version:</b> {dryRunResult.version}</div>}
                    {dryRunResult.lab && <div><b>Accepting Lab:</b> {dryRunResult.lab}</div>}
                    {dryRunResult.eta && <div><b>Estimated Delivery:</b> {new Date(dryRunResult.eta).toLocaleString()}</div>}
                  </div>
                </div>
              )}
            </form>
          )}

          {/* Form: Create Collection Request */}
          {activeFormTab === 'collection' && (
            <form onSubmit={handleCreateRequest} className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Origin Address (Patient Home or Clinic)</label>
                <input
                  type="text"
                  value={originAddress}
                  onChange={(e) => setOriginAddress(e.target.value)}
                  placeholder="e.g. 123 Indiranagar 100ft Rd, Bangalore"
                  className="w-full text-xs p-2 rounded border border-slate-300 focus:ring-1 focus:ring-indigo-500"
                  required
                />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Origin Latitude</label>
                  <input
                    type="text"
                    value={originLat}
                    onChange={(e) => setOriginLat(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300 focus:ring-1 focus:ring-indigo-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Origin Longitude</label>
                  <input
                    type="text"
                    value={originLng}
                    onChange={(e) => setOriginLng(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300 focus:ring-1 focus:ring-indigo-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Sample Type</label>
                  <select
                    value={sampleType}
                    onChange={(e) => setSampleType(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300 bg-white focus:ring-1 focus:ring-indigo-500"
                  >
                    <option value="Amber">Amber (Standard)</option>
                    <option value="Indigo">Indigo (Separated)</option>
                    <option value="Frost">Frost (Cooled Storage Required)</option>
                    <option value="Pulse">Pulse (Time-critical)</option>
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Collection Window Start</label>
                  <input
                    type="datetime-local"
                    value={windowStart}
                    onChange={(e) => setWindowStart(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300 focus:ring-1 focus:ring-indigo-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Collection Window End</label>
                  <input
                    type="datetime-local"
                    value={windowEnd}
                    onChange={(e) => setWindowEnd(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300 focus:ring-1 focus:ring-indigo-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Delivery Deadline</label>
                  <input
                    type="datetime-local"
                    value={deadline}
                    onChange={(e) => setDeadline(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300 focus:ring-1 focus:ring-indigo-500"
                    required
                  />
                </div>
              </div>

              <div className="pt-2">
                <button
                  type="submit"
                  disabled={submitting}
                  className="px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg text-xs font-bold transition shadow disabled:opacity-50 flex items-center"
                >
                  <PlusCircle className="w-4 h-4 mr-2" />
                  Submit Collection Request
                </button>
              </div>
            </form>
          )}

          {/* Form: Pre-sealed Sample */}
          {activeFormTab === 'presealed' && (
            <form onSubmit={handleIngestPresealed} className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Origin Facility Type</label>
                  <select
                    value={presealedOriginType}
                    onChange={(e) => setPresealedOriginType(e.target.value as any)}
                    className="w-full text-xs p-2 rounded border border-slate-300 bg-white focus:ring-1 focus:ring-indigo-500"
                  >
                    <option value="clinic">Clinic (Non-home)</option>
                    <option value="network_node">Network Node / Hub</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Origin Latitude</label>
                  <input
                    type="text"
                    value={originLat}
                    onChange={(e) => setOriginLat(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Origin Longitude</label>
                  <input
                    type="text"
                    value={originLng}
                    onChange={(e) => setOriginLng(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300"
                    required
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Sample Type</label>
                  <select
                    value={sampleType}
                    onChange={(e) => setSampleType(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300 bg-white"
                  >
                    <option value="Amber">Amber</option>
                    <option value="Indigo">Indigo</option>
                    <option value="Frost">Frost</option>
                    <option value="Pulse">Pulse</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Container Type</label>
                  <select
                    value={presealedContainer}
                    onChange={(e) => setPresealedContainer(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300 bg-white"
                  >
                    <option value="insulated_cooler">Insulated Cooler</option>
                    <option value="standard_biohazard_box">Standard Biohazard Box</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-700 mb-1">Observed Temp (°C)</label>
                  <input
                    type="number"
                    step="0.1"
                    value={presealedTemp}
                    onChange={(e) => setPresealedTemp(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300"
                    required
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Delivery Deadline</label>
                <input
                  type="datetime-local"
                  value={deadline}
                  onChange={(e) => setDeadline(e.target.value)}
                  className="w-full md:w-1/3 text-xs p-2 rounded border border-slate-300"
                  required
                />
              </div>

              <div className="pt-2">
                <button
                  type="submit"
                  disabled={submitting}
                  className="px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg text-xs font-bold transition shadow disabled:opacity-50"
                >
                  Register Pre-sealed Sample
                </button>
              </div>
            </form>
          )}
        </div>
      </div>

      {/* Work Sections: Current Work & Past Work */}
      <div className="grid grid-cols-1 gap-6">

        {/* Current Work */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h2 className="text-base font-bold text-slate-900">Current Work</h2>
              <p className="text-xs text-slate-500">Active and pending collection requests</p>
            </div>
            <button
              onClick={() => setRefreshKey((k) => k + 1)}
              className="p-1.5 text-slate-500 hover:text-slate-800 rounded hover:bg-slate-100"
              title="Refresh"
            >
              <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin text-indigo-600' : ''}`} />
            </button>
          </div>

          {currentWork.length === 0 ? (
            <div className="text-xs text-slate-400 py-6 text-center italic border border-dashed rounded-lg">
              No active or pending requests found.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs text-slate-700">
                <thead className="bg-slate-50 text-slate-600 uppercase font-semibold border-b border-slate-200">
                  <tr>
                    <th className="px-4 py-2.5">Sample ID</th>
                    <th className="px-4 py-2.5">Type</th>
                    <th className="px-4 py-2.5">Status</th>
                    <th className="px-4 py-2.5">Current Custodian</th>
                    <th className="px-4 py-2.5">Location Freshness</th>
                    <th className="px-4 py-2.5">Deadline</th>
                    <th className="px-4 py-2.5 text-right">Action</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {currentWork.map((item: any) => (
                    <tr key={item.sampleId || item.assignmentId} className="hover:bg-slate-50 transition">
                      <td className="px-4 py-3 font-mono font-semibold text-slate-900">
                        {item.sampleId ? item.sampleId.slice(0, 8) : item.assignmentId?.slice(0, 8)}...
                      </td>
                      <td className="px-4 py-3">
                        <span className="font-semibold text-indigo-700">{item.sampleType || 'Standard'}</span>
                      </td>
                      <td className="px-4 py-3">
                        <span className={`px-2 py-0.5 rounded-full font-bold uppercase tracking-wider text-[10px] ${
                          item.status === 'received' ? 'bg-green-100 text-green-800' :
                          item.status === 'exception' ? 'bg-red-100 text-red-800' :
                          item.status === 'in_transit' ? 'bg-blue-100 text-blue-800' :
                          'bg-amber-100 text-amber-800'
                        }`}>
                          {item.status}
                        </span>
                        {item.isException && <span className="ml-1 text-[10px] text-red-600 font-bold">(Exception)</span>}
                      </td>
                      <td className="px-4 py-3 text-slate-600">
                        {item.currentHolderId || item.currentHolderName || 'Assigned Collector'}
                      </td>
                      <td className="px-4 py-3">
                        <span className={`inline-flex items-center px-2 py-0.5 rounded text-[11px] font-medium ${
                          item.isLocationStale ? 'bg-amber-100 text-amber-800' : 'bg-emerald-100 text-emerald-800'
                        }`}>
                          <span className={`w-1.5 h-1.5 rounded-full mr-1.5 ${item.isLocationStale ? 'bg-amber-500' : 'bg-emerald-500'}`}></span>
                          {item.isLocationStale ? 'Stale' : 'Fresh'}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-slate-600">
                        {item.deliveryDeadline ? new Date(item.deliveryDeadline).toLocaleTimeString() : 'N/A'}
                      </td>
                      <td className="px-4 py-3 text-right">
                        <button
                          onClick={() => onSelectSample(item.sampleId)}
                          className="px-3 py-1 bg-slate-100 hover:bg-indigo-50 text-indigo-600 rounded font-semibold text-xs transition border border-slate-200"
                        >
                          View Details
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* Past Work */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h2 className="text-base font-bold text-slate-900">Past Work</h2>
              <p className="text-xs text-slate-500">Delivered and completed sample requests</p>
            </div>
          </div>

          {pastWork.length === 0 ? (
            <div className="text-xs text-slate-400 py-6 text-center italic border border-dashed rounded-lg">
              No completed requests in history.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs text-slate-700">
                <thead className="bg-slate-50 text-slate-600 uppercase font-semibold border-b border-slate-200">
                  <tr>
                    <th className="px-4 py-2.5">Sample ID</th>
                    <th className="px-4 py-2.5">Type</th>
                    <th className="px-4 py-2.5">Status</th>
                    <th className="px-4 py-2.5">Completed At</th>
                    <th className="px-4 py-2.5 text-right">Action</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {pastWork.map((item: any) => (
                    <tr key={item.sampleId || item.assignmentId} className="hover:bg-slate-50 transition">
                      <td className="px-4 py-3 font-mono font-semibold text-slate-900">
                        {item.sampleId ? item.sampleId.slice(0, 8) : item.assignmentId?.slice(0, 8)}...
                      </td>
                      <td className="px-4 py-3">{item.sampleType || 'Standard'}</td>
                      <td className="px-4 py-3">
                        <span className="px-2 py-0.5 rounded-full font-bold uppercase tracking-wider text-[10px] bg-green-100 text-green-800">
                          {item.status}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-slate-500">
                        {item.updatedAt ? new Date(item.updatedAt).toLocaleString() : 'Completed'}
                      </td>
                      <td className="px-4 py-3 text-right">
                        <button
                          onClick={() => onSelectSample(item.sampleId)}
                          className="px-3 py-1 bg-slate-100 hover:bg-indigo-50 text-indigo-600 rounded font-semibold text-xs transition border border-slate-200"
                        >
                          View History
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

      </div>
    </div>
  );
};
"}

