import React, { useState, useEffect } from 'react';
import { api, User, LocationItem } from '../api';
import { Check, X, MapPin, Package, Thermometer, ShieldCheck, RefreshCw, AlertTriangle, Layers, Truck } from 'lucide-react';

interface WorkerViewProps {
  user: User;
  onSelectSample: (sampleId: string) => void;
}

export const WorkerView: React.FC<WorkerViewProps> = ({ user, onSelectSample }) => {
  const [currentWork, setCurrentWork] = useState<any[]>([]);
  const [pastWork, setPastWork] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);

  // Worker Location Update Form state
  const [workerLat, setWorkerLat] = useState('12.9716');
  const [workerLng, setWorkerLng] = useState('77.5946');
  const [locSuccess, setLocSuccess] = useState<string | null>(null);
  const [locLoading, setLocLoading] = useState(false);

  // Capacity state (for Node Handler or Lab Operator)
  const [assignedLocation, setAssignedLocation] = useState<LocationItem | null>(null);
  const [regCap, setRegCap] = useState<number>(100);
  const [coolCap, setCoolCap] = useState<number>(50);
  const [capMsg, setCapMsg] = useState<string | null>(null);

  // Collect & Seal Modal / Inline form
  const [activeCollectSampleId, setActiveCollectSampleId] = useState<string | null>(null);
  const [activeCollectAssignId, setActiveCollectAssignId] = useState<string | null>(null);
  const [collectContainer, setCollectContainer] = useState('insulated_cooler');
  const [collectTemp, setCollectTemp] = useState('4.0');

  // Initiate Handoff form
  const [handoffSampleId, setHandoffSampleId] = useState<string | null>(null);
  const [handoffFromAssignId, setHandoffFromAssignId] = useState<string | null>(null);
  const [handoffToAssignId, setHandoffToAssignId] = useState<string>('');
  const [handoffReceiverId, setHandoffReceiverId] = useState<string>('');

  const loadWork = async () => {
    try {
      setLoading(true);
      const res = await api.listRoleWork(user.activeRole);
      const active = [...(res.pending || []), ...(res.inProgress || [])];
      setCurrentWork(active);
      setPastWork(res.completed || []);
    } catch (err: any) {
      console.error('Failed to load role work:', err);
    } finally {
      setLoading(false);
    }
  };

  const loadCapacity = async () => {
    if (user.activeRole === 'node_handler' || user.activeRole === 'laboratory_team' || user.activeRole === 'lab_intake') {
      try {
        const ops = await api.readOperationsState();
        const allLocs = [...(ops.collectionNodes || []), ...(ops.laboratories || [])];
        if (allLocs.length > 0) {
          const loc = allLocs[0];
          setAssignedLocation(loc);
          setRegCap(loc.regularCapacity);
          setCoolCap(loc.cooledCapacity);
        }
      } catch (err) {
        console.error('Failed to load assigned node capacity:', err);
      }
    }
  };

  useEffect(() => {
    loadWork();
    loadCapacity();
  }, [user.activeRole, refreshKey]);

  // Accept Assignment
  const handleAccept = async (assignmentId: string) => {
    try {
      await api.acceptAssignment(assignmentId);
      setRefreshKey((k) => k + 1);
    } catch (err: any) {
      alert(`Failed to accept assignment: ${err.message}`);
    }
  };

  // Decline Assignment
  const handleDecline = async (assignmentId: string) => {
    const reason = prompt('Reason for declining:');
    if (reason === null) return;
    try {
      await api.declineAssignment(assignmentId, reason);
      setRefreshKey((k) => k + 1);
    } catch (err: any) {
      alert(`Failed to decline assignment: ${err.message}`);
    }
  };

  // Record Location
  const handleRecordLocation = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLocLoading(true);
      setLocSuccess(null);
      await api.recordWorkerLocation({
        coordinate: {
          latitude: parseFloat(workerLat),
          longitude: parseFloat(workerLng),
        },
      });
      setLocSuccess('Location recorded successfully!');
    } catch (err: any) {
      alert(`Failed to record location: ${err.message}`);
    } finally {
      setLocLoading(false);
    }
  };

  // Collect & Seal
  const handleCollectAndSealSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeCollectSampleId || !activeCollectAssignId) return;
    try {
      await api.collectAndSealSample({
        sampleId: activeCollectSampleId,
        assignmentId: activeCollectAssignId,
        containerType: collectContainer,
        observedTemperatureC: parseFloat(collectTemp),
      });
      setActiveCollectSampleId(null);
      setActiveCollectAssignId(null);
      setRefreshKey((k) => k + 1);
    } catch (err: any) {
      alert(`Collect & Seal error: ${err.message}`);
    }
  };

  // Initiate Handoff Submit
  const handleInitiateHandoffSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!handoffSampleId || !handoffFromAssignId) return;
    try {
      await api.initiateHandoff({
        sampleId: handoffSampleId,
        fromAssignmentId: handoffFromAssignId,
        toAssignmentId: handoffToAssignId || 'assign_next',
        receiverId: handoffReceiverId || 'worker_next',
      });
      setHandoffSampleId(null);
      setRefreshKey((k) => k + 1);
    } catch (err: any) {
      alert(`Initiate handoff error: ${err.message}`);
    }
  };

  // Update Capacity
  const handleUpdateCapacity = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!assignedLocation) return;
    try {
      setCapMsg(null);
      await api.configureCapacity({
        locationId: assignedLocation.locationId,
        regularCapacity: Number(regCap),
        cooledCapacity: Number(coolCap),
      });
      setCapMsg('Capacity updated successfully!');
      loadCapacity();
    } catch (err: any) {
      setCapMsg(`Error: ${err.message}`);
    }
  };

  const isCollector = user.activeRole.includes('collection');
  const isCourier = user.activeRole.includes('courier') || user.activeRole.includes('delivery');
  const isNodeHandler = user.activeRole.includes('node');
  const isLabWorker = user.activeRole.includes('lab');

  return (
    <div className="space-y-8">
      {/* Top Banner: Location Recorder & Node Capacity (if applicable) */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

        {/* Record Worker Location Card */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-5">
          <div className="flex items-center space-x-2 text-slate-800 font-bold text-sm mb-3">
            <MapPin className="w-4 h-4 text-indigo-600" />
            <span>Record Current Location</span>
          </div>
          <form onSubmit={handleRecordLocation} className="space-y-3">
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-[11px] text-slate-500 font-medium mb-1">Latitude</label>
                <input
                  type="text"
                  value={workerLat}
                  onChange={(e) => setWorkerLat(e.target.value)}
                  className="w-full text-xs p-1.5 rounded border border-slate-300"
                  required
                />
              </div>
              <div>
                <label className="block text-[11px] text-slate-500 font-medium mb-1">Longitude</label>
                <input
                  type="text"
                  value={workerLng}
                  onChange={(e) => setWorkerLng(e.target.value)}
                  className="w-full text-xs p-1.5 rounded border border-slate-300"
                  required
                />
              </div>
            </div>
            {locSuccess && <div className="text-xs text-emerald-700 font-medium">{locSuccess}</div>}
            <button
              type="submit"
              disabled={locLoading}
              className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded text-xs font-semibold shadow-sm transition disabled:opacity-50"
            >
              Update Location
            </button>
          </form>
        </div>

        {/* Capacity Management Card (for Node Handlers & Lab Workers) */}
        {(isNodeHandler || isLabWorker) && assignedLocation && (
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-5">
            <div className="flex items-center space-x-2 text-slate-800 font-bold text-sm mb-3">
              <Layers className="w-4 h-4 text-indigo-600" />
              <span>{isLabWorker ? 'Laboratory Capacity' : 'Node Capacity'}: {assignedLocation.name}</span>
            </div>
            <div className="grid grid-cols-2 gap-2 text-xs mb-3 bg-slate-50 p-2.5 rounded border">
              <div>
                <span className="text-slate-500">Regular: </span>
                <b>{assignedLocation.regularCapacity - (assignedLocation.regularReserved || 0)} / {assignedLocation.regularCapacity} avail</b>
              </div>
              <div>
                <span className="text-slate-500">Cooled: </span>
                <b>{assignedLocation.cooledCapacity - (assignedLocation.cooledReserved || 0)} / {assignedLocation.cooledCapacity} avail</b>
              </div>
            </div>
            <form onSubmit={handleUpdateCapacity} className="space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[11px] text-slate-500 font-medium mb-1">Configured Regular</label>
                  <input
                    type="number"
                    value={regCap}
                    onChange={(e) => setRegCap(Number(e.target.value))}
                    className="w-full text-xs p-1.5 rounded border border-slate-300"
                  />
                </div>
                <div>
                  <label className="block text-[11px] text-slate-500 font-medium mb-1">Configured Cooled</label>
                  <input
                    type="number"
                    value={coolCap}
                    onChange={(e) => setCoolCap(Number(e.target.value))}
                    className="w-full text-xs p-1.5 rounded border border-slate-300"
                  />
                </div>
              </div>
              {capMsg && <div className="text-xs font-medium text-indigo-700">{capMsg}</div>}
              <button
                type="submit"
                className="px-4 py-2 bg-slate-800 hover:bg-slate-900 text-white rounded text-xs font-semibold shadow-sm transition"
              >
                Update Capacity
              </button>
            </form>
          </div>
        )}
      </div>

      {/* Work Lists: Current Work & Past Work */}
      <div className="grid grid-cols-1 gap-6">

        {/* Current Work */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h2 className="text-base font-bold text-slate-900">Current Work</h2>
              <p className="text-xs text-slate-500">Offered, accepted, and active transport & collection tasks</p>
            </div>
            <button
              onClick={() => setRefreshKey((k) => k + 1)}
              className="p-1.5 text-slate-500 hover:text-slate-800 rounded hover:bg-slate-100"
              title="Refresh"
            >
              <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin text-indigo-600' : ''}`} />
            </button>
          </div>

          {currentWork.length === 0 ? (
            <div className="text-xs text-slate-400 py-6 text-center italic border border-dashed rounded-lg">
              No active or pending assignments.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs text-slate-700">
                <thead className="bg-slate-50 text-slate-600 uppercase font-semibold border-b border-slate-200">
                  <tr>
                    <th className="px-4 py-2.5">Assignment ID</th>
                    <th className="px-4 py-2.5">Type</th>
                    <th className="px-4 py-2.5">Status</th>
                    <th className="px-4 py-2.5">Sample ID</th>
                    <th className="px-4 py-2.5 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {currentWork.map((item: any) => {
                    const assignId = item.assignmentId || item.id;
                    const sampleId = item.sampleId || item.sample_id;
                    const isOffered = item.status === 'offered' || item.status === 'pending';
                    const isAccepted = item.status === 'accepted' || item.status === 'in_progress';

                    return (
                      <tr key={assignId} className="hover:bg-slate-50 transition">
                        <td className="px-4 py-3 font-mono font-semibold text-slate-900">
                          {assignId ? assignId.slice(0, 8) : 'N/A'}...
                        </td>
                        <td className="px-4 py-3 capitalize font-medium">
                          {item.assignmentType || item.legType || user.activeRole}
                        </td>
                        <td className="px-4 py-3">
                          <span className={`px-2 py-0.5 rounded-full font-bold uppercase tracking-wider text-[10px] ${
                            isAccepted ? 'bg-emerald-100 text-emerald-800' :
                            isOffered ? 'bg-amber-100 text-amber-800' :
                            'bg-slate-100 text-slate-800'
                          }`}>
                            {item.status}
                          </span>
                        </td>
                        <td className="px-4 py-3 font-mono">
                          {sampleId ? (
                            <button
                              onClick={() => onSelectSample(sampleId)}
                              className="text-indigo-600 hover:underline font-semibold"
                            >
                              {sampleId.slice(0, 8)}...
                            </button>
                          ) : 'N/A'}
                        </td>
                        <td className="px-4 py-3 text-right space-x-2">
                          {isOffered && (
                            <>
                              <button
                                onClick={() => handleAccept(assignId)}
                                className="px-2.5 py-1 bg-emerald-600 hover:bg-emerald-700 text-white rounded font-bold text-xs shadow-sm transition"
                              >
                                Accept
                              </button>
                              <button
                                onClick={() => handleDecline(assignId)}
                                className="px-2.5 py-1 bg-red-600 hover:bg-red-700 text-white rounded font-bold text-xs shadow-sm transition"
                              >
                                Decline
                              </button>
                            </>
                          )}

                          {isAccepted && isCollector && (
                            <button
                              onClick={() => {
                                setActiveCollectSampleId(sampleId);
                                setActiveCollectAssignId(assignId);
                              }}
                              className="px-2.5 py-1 bg-indigo-600 hover:bg-indigo-700 text-white rounded font-semibold text-xs transition"
                            >
                              Collect & Seal
                            </button>
                          )}

                          {isAccepted && (isCourier || isNodeHandler) && (
                            <button
                              onClick={() => {
                                setHandoffSampleId(sampleId);
                                setHandoffFromAssignId(assignId);
                              }}
                              className="px-2.5 py-1 bg-slate-700 hover:bg-slate-800 text-white rounded font-semibold text-xs transition"
                            >
                              Initiate Handoff
                            </button>
                          )}

                          {sampleId && (
                            <button
                              onClick={() => onSelectSample(sampleId)}
                              className="px-2.5 py-1 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded font-medium text-xs transition border border-slate-200"
                            >
                              Details
                            </button>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* Past Work */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h2 className="text-base font-bold text-slate-900">Past Work</h2>
              <p className="text-xs text-slate-500">Completed and declined assignments history</p>
            </div>
          </div>

          {pastWork.length === 0 ? (
            <div className="text-xs text-slate-400 py-6 text-center italic border border-dashed rounded-lg">
              No completed work records found.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs text-slate-700">
                <thead className="bg-slate-50 text-slate-600 uppercase font-semibold border-b border-slate-200">
                  <tr>
                    <th className="px-4 py-2.5">Assignment ID</th>
                    <th className="px-4 py-2.5">Type</th>
                    <th className="px-4 py-2.5">Status</th>
                    <th className="px-4 py-2.5">Sample ID</th>
                    <th className="px-4 py-2.5 text-right">Action</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {pastWork.map((item: any) => {
                    const assignId = item.assignmentId || item.id;
                    const sampleId = item.sampleId || item.sample_id;
                    return (
                      <tr key={assignId} className="hover:bg-slate-50 transition">
                        <td className="px-4 py-3 font-mono">{assignId ? assignId.slice(0, 8) : 'N/A'}...</td>
                        <td className="px-4 py-3 capitalize">{item.assignmentType || user.activeRole}</td>
                        <td className="px-4 py-3">
                          <span className={`px-2 py-0.5 rounded-full font-bold uppercase text-[10px] ${
                            item.status === 'completed' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                          }`}>
                            {item.status}
                          </span>
                        </td>
                        <td className="px-4 py-3 font-mono">{sampleId ? sampleId.slice(0, 8) : 'N/A'}</td>
                        <td className="px-4 py-3 text-right">
                          {sampleId && (
                            <button
                              onClick={() => onSelectSample(sampleId)}
                              className="px-2.5 py-1 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded text-xs"
                            >
                              View History
                            </button>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>

      </div>

      {/* Collect & Seal Modal Form */}
      {activeCollectSampleId && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 space-y-4">
            <h3 className="text-base font-bold text-slate-900">Collect & Seal Sample</h3>
            <p className="text-xs text-slate-500">Record sealing details for sample {activeCollectSampleId}</p>
            <form onSubmit={handleCollectAndSealSubmit} className="space-y-3">
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Container Type</label>
                <select
                  value={collectContainer}
                  onChange={(e) => setCollectContainer(e.target.value)}
                  className="w-full text-xs p-2 rounded border border-slate-300"
                >
                  <option value="insulated_cooler">Insulated Cooler</option>
                  <option value="standard_biohazard_box">Standard Biohazard Box</option>
                  <option value="ambient_pouch">Ambient Pouch</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Observed Temperature (°C)</label>
                <input
                  type="number"
                  step="0.1"
                  value={collectTemp}
                  onChange={(e) => setCollectTemp(e.target.value)}
                  className="w-full text-xs p-2 rounded border border-slate-300"
                  required
                />
              </div>
              <div className="flex justify-end space-x-2 pt-2">
                <button
                  type="button"
                  onClick={() => setActiveCollectSampleId(null)}
                  className="px-3 py-1.5 rounded text-xs font-semibold bg-slate-200 text-slate-700"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-1.5 rounded text-xs font-bold bg-indigo-600 hover:bg-indigo-700 text-white shadow"
                >
                  Confirm Sealing
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Initiate Handoff Modal */}
      {handoffSampleId && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 space-y-4">
            <h3 className="text-base font-bold text-slate-900">Initiate Custody Handoff</h3>
            <p className="text-xs text-slate-500">Transfer custody of sample {handoffSampleId}</p>
            <form onSubmit={handleInitiateHandoffSubmit} className="space-y-3">
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Next Assignment ID (or leg)</label>
                <input
                  type="text"
                  value={handoffToAssignId}
                  onChange={(e) => setHandoffToAssignId(e.target.value)}
                  placeholder="e.g. leg_2_assign"
                  className="w-full text-xs p-2 rounded border border-slate-300"
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1">Receiver Worker ID (or node)</label>
                <input
                  type="text"
                  value={handoffReceiverId}
                  onChange={(e) => setHandoffReceiverId(e.target.value)}
                  placeholder="e.g. courier_bob"
                  className="w-full text-xs p-2 rounded border border-slate-300"
                />
              </div>
              <div className="flex justify-end space-x-2 pt-2">
                <button
                  type="button"
                  onClick={() => setHandoffSampleId(null)}
                  className="px-3 py-1.5 rounded text-xs font-semibold bg-slate-200 text-slate-700"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-1.5 rounded text-xs font-bold bg-indigo-600 hover:bg-indigo-700 text-white shadow"
                >
                  Initiate Dual Handoff
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

    </div>
  );
};

