              <div className="text-xs p-2 rounded bg-amber-50 border border-amber-200 text-amber-900 font-medium">
                {disruptMsg}
              </div>
            )}

            <button
              type="submit"
              className="w-full py-2 bg-amber-600 hover:bg-amber-700 text-white rounded text-xs font-bold transition shadow"
            >
              Report Disruption & Trigger Replan
            </button>
          </form>
        </div>

      </div>

      {/* Monitor Categories Navigation & Tables */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">

        {/* Category Tabs */}
        <div className="flex border-b border-slate-200 bg-slate-50 px-6 pt-3 space-x-2 sm:space-x-4 overflow-x-auto">
          <button
            onClick={() => setActiveCategory('samples')}
            className={`pb-3 text-xs font-bold border-b-2 flex items-center space-x-1.5 transition ${
              activeCategory === 'samples' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-800'
            }`}
          >
            <Truck className="w-3.5 h-3.5" />
            <span>Samples ({samples.length})</span>
          </button>

          <button
            onClick={() => setActiveCategory('workers')}
            className={`pb-3 text-xs font-bold border-b-2 flex items-center space-x-1.5 transition ${
              activeCategory === 'workers' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-800'
            }`}
          >
            <span>Workers ({workers.length})</span>
          </button>

          <button
            onClick={() => setActiveCategory('collection_nodes')}
            className={`pb-3 text-xs font-bold border-b-2 flex items-center space-x-1.5 transition ${
              activeCategory === 'collection_nodes' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-800'
            }`}
          >
            <Building2 className="w-3.5 h-3.5" />
            <span>Collection Nodes ({nodes.length})</span>
          </button>

          <button
            onClick={() => setActiveCategory('laboratories')}
            className={`pb-3 text-xs font-bold border-b-2 flex items-center space-x-1.5 transition ${
              activeCategory === 'laboratories' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-800'
            }`}
          >
            <Beaker className="w-3.5 h-3.5" />
            <span>Laboratories ({laboratories.length})</span>
          </button>

          <button
            onClick={() => setActiveCategory('routes')}
            className={`pb-3 text-xs font-bold border-b-2 flex items-center space-x-1.5 transition ${
              activeCategory === 'routes' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-800'
            }`}
          >
            <GitFork className="w-3.5 h-3.5" />
            <span>Routes ({routes.length})</span>
          </button>

          <button
            onClick={() => setActiveCategory('exceptions')}
            className={`pb-3 text-xs font-bold border-b-2 flex items-center space-x-1.5 transition ${
              activeCategory === 'exceptions' ? 'border-red-600 text-red-600' : 'border-transparent text-slate-500 hover:text-slate-800'
            }`}
          >
            <ShieldAlert className="w-3.5 h-3.5 text-red-500" />
            <span>Exceptions ({exceptions.length})</span>
          </button>
        </div>

        {/* Category Table Content */}
        <div className="p-6">

          {/* SAMPLES TABLE */}
          {activeCategory === 'samples' && (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs text-slate-700">
                <thead className="bg-slate-50 text-slate-600 uppercase font-semibold border-b border-slate-200">
                  <tr>
                    <th className="px-4 py-2.5">Sample ID</th>
                    <th className="px-4 py-2.5">Type</th>
                    <th className="px-4 py-2.5">Status</th>
                    <th className="px-4 py-2.5">Current Holder</th>
                    <th className="px-4 py-2.5">Freshness</th>
                    <th className="px-4 py-2.5">Deadline</th>
                    <th className="px-4 py-2.5 text-right">Dispatcher Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {samples.map((s) => (
                    <tr key={s.sampleId} className="hover:bg-slate-50 transition">
                      <td className="px-4 py-3 font-mono font-semibold text-slate-900">
                        {s.sampleId.slice(0, 8)}...
                      </td>
                      <td className="px-4 py-3 font-medium text-indigo-700">{s.sampleType}</td>
                      <td className="px-4 py-3">
                        <span className={`px-2 py-0.5 rounded-full font-bold uppercase text-[10px] ${
                          s.status === 'received' ? 'bg-green-100 text-green-800' :
                          s.isException ? 'bg-red-100 text-red-800' :
                          'bg-amber-100 text-amber-800'
                        }`}>
                          {s.status}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-slate-600">{s.currentHolderId || 'Unassigned'}</td>
                      <td className="px-4 py-3">
                        <span className={`inline-flex items-center px-2 py-0.5 rounded text-[11px] font-medium ${
                          s.isLocationStale ? 'bg-amber-100 text-amber-800' : 'bg-emerald-100 text-emerald-800'
                        }`}>
                          <span className={`w-1.5 h-1.5 rounded-full mr-1.5 ${s.isLocationStale ? 'bg-amber-500' : 'bg-emerald-500'}`}></span>
                          {s.isLocationStale ? 'Stale' : 'Fresh'}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-slate-600">{new Date(s.deliveryDeadline).toLocaleTimeString()}</td>
                      <td className="px-4 py-3 text-right space-x-1.5">
                        <button
                          onClick={() => onSelectSample(s.sampleId)}
                          className="px-2.5 py-1 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded text-xs font-semibold"
                        >
                          Lifecycle
                        </button>
                        {s.journeyId && s.status !== 'received' && (
                          <>
                            <button
                              onClick={() => handleReroute(s.journeyId!)}
                              className="px-2 py-1 bg-indigo-50 hover:bg-indigo-100 text-indigo-700 rounded text-xs font-semibold"
                            >
                              Reroute
                            </button>
                            <button
                              onClick={() => handleCancelJourney(s.journeyId!)}
                              className="px-2 py-1 bg-red-50 hover:bg-red-100 text-red-700 rounded text-xs font-semibold"
                            >
                              Cancel
                            </button>
                          </>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* WORKERS TABLE */}
          {activeCategory === 'workers' && (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs text-slate-700">
                <thead className="bg-slate-50 text-slate-600 uppercase font-semibold border-b border-slate-200">
                  <tr>
                    <th className="px-4 py-2.5">User</th>
                    <th className="px-4 py-2.5">Full Name</th>
                    <th className="px-4 py-2.5">Roles</th>
                    <th className="px-4 py-2.5">Certifications</th>
                    <th className="px-4 py-2.5">Workload</th>
                    <th className="px-4 py-2.5">Availability</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {workers.map((w) => (
                    <tr key={w.userId} className="hover:bg-slate-50 transition">
                      <td className="px-4 py-3 font-semibold text-slate-900">@{w.username}</td>
                      <td className="px-4 py-3">{w.fullName}</td>
                      <td className="px-4 py-3">{(w.roles || []).join(', ')}</td>
                      <td className="px-4 py-3">{(w.certifications || []).join(', ') || 'Standard'}</td>
                      <td className="px-4 py-3 font-semibold">{w.workload || 0} active</td>
                      <td className="px-4 py-3">
                        <span className="px-2 py-0.5 rounded-full font-bold uppercase text-[10px] bg-emerald-100 text-emerald-800">
                          Available
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* COLLECTION NODES TABLE */}
          {activeCategory === 'collection_nodes' && (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs text-slate-700">
                <thead className="bg-slate-50 text-slate-600 uppercase font-semibold border-b border-slate-200">
                  <tr>
                    <th className="px-4 py-2.5">Name</th>
                    <th className="px-4 py-2.5">Code</th>
                    <th className="px-4 py-2.5">Coordinates</th>
                    <th className="px-4 py-2.5">Regular Capacity</th>
                    <th className="px-4 py-2.5">Cooled Capacity</th>
                    <th className="px-4 py-2.5">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {nodes.map((n) => (
                    <tr key={n.locationId} className="hover:bg-slate-50 transition">
                      <td className="px-4 py-3 font-semibold text-slate-900">{n.name}</td>
                      <td className="px-4 py-3 font-mono">{n.code}</td>
                      <td className="px-4 py-3">{n.coordinate?.latitude.toFixed(4)}, {n.coordinate?.longitude.toFixed(4)}</td>
                      <td className="px-4 py-3">
                        <b>{n.regularCapacity - (n.regularReserved || 0)}</b> / {n.regularCapacity} avail
                      </td>
                      <td className="px-4 py-3">
                        <b>{n.cooledCapacity - (n.cooledReserved || 0)}</b> / {n.cooledCapacity} avail
                      </td>
                      <td className="px-4 py-3">
                        <span className={`px-2 py-0.5 rounded-full font-bold uppercase text-[10px] ${
                          n.status === 'active' ? 'bg-emerald-100 text-emerald-800' : 'bg-red-100 text-red-800'
                        }`}>
                          {n.status}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* LABORATORIES TABLE */}
          {activeCategory === 'laboratories' && (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs text-slate-700">
                <thead className="bg-slate-50 text-slate-600 uppercase font-semibold border-b border-slate-200">
                  <tr>
                    <th className="px-4 py-2.5">Laboratory</th>
                    <th className="px-4 py-2.5">Code</th>
                    <th className="px-4 py-2.5">Accepted Types</th>
                    <th className="px-4 py-2.5">Regular Capacity</th>
                    <th className="px-4 py-2.5">Cooled Capacity</th>
                    <th className="px-4 py-2.5">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {laboratories.map((lab) => (
                    <tr key={lab.locationId} className="hover:bg-slate-50 transition">
                      <td className="px-4 py-3 font-semibold text-slate-900">{lab.name}</td>
                      <td className="px-4 py-3 font-mono">{lab.code}</td>
                      <td className="px-4 py-3">{(lab.acceptedSampleTypes || []).join(', ') || 'All'}</td>
                      <td className="px-4 py-3">
                        <b>{lab.regularCapacity - (lab.regularReserved || 0)}</b> / {lab.regularCapacity} avail
                      </td>
                      <td className="px-4 py-3">
                        <b>{lab.cooledCapacity - (lab.cooledReserved || 0)}</b> / {lab.cooledCapacity} avail
                      </td>
                      <td className="px-4 py-3">
                        <span className={`px-2 py-0.5 rounded-full font-bold uppercase text-[10px] ${
                          lab.status === 'active' ? 'bg-emerald-100 text-emerald-800' : 'bg-red-100 text-red-800'
                        }`}>
                          {lab.status}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* ROUTES TABLE */}
          {activeCategory === 'routes' && (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs text-slate-700">
                <thead className="bg-slate-50 text-slate-600 uppercase font-semibold border-b border-slate-200">
                  <tr>
                    <th className="px-4 py-2.5">Connection</th>
                    <th className="px-4 py-2.5">Travel Time</th>
                    <th className="px-4 py-2.5">Regular Capacity</th>
                    <th className="px-4 py-2.5">Cooled Capacity</th>
                    <th className="px-4 py-2.5">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {routes.map((r) => (
                    <tr key={r.connectionId} className="hover:bg-slate-50 transition">
                      <td className="px-4 py-3 font-medium text-slate-900">{r.fromNodeId} ➔ {r.toNodeId}</td>
                      <td className="px-4 py-3">{r.travelTimeMinutes} mins</td>
                      <td className="px-4 py-3">{r.regularCapacity - (r.regularReserved || 0)} / {r.regularCapacity}</td>
                      <td className="px-4 py-3">{r.cooledCapacity - (r.cooledReserved || 0)} / {r.cooledCapacity}</td>
                      <td className="px-4 py-3">
                        <span className={`px-2 py-0.5 rounded-full font-bold uppercase text-[10px] ${
                          r.status === 'active' ? 'bg-emerald-100 text-emerald-800' : 'bg-red-100 text-red-800'
                        }`}>
                          {r.status}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* EXCEPTIONS TABLE */}
          {activeCategory === 'exceptions' && (
            <div className="overflow-x-auto">
              {exceptions.length === 0 ? (
                <div className="text-xs text-slate-400 py-6 text-center italic">
                  No active exceptions in the transport network.
                </div>
              ) : (
                <table className="w-full text-left text-xs text-slate-700">
                  <thead className="bg-red-50 text-red-900 uppercase font-semibold border-b border-red-200">
                    <tr>
                      <th className="px-4 py-2.5">Sample ID</th>
                      <th className="px-4 py-2.5">Type</th>
                      <th className="px-4 py-2.5">Exception Reason</th>
                      <th className="px-4 py-2.5">Current Holder</th>
                      <th className="px-4 py-2.5">Deadline</th>
                      <th className="px-4 py-2.5 text-right">Action</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {exceptions.map((ex) => (
                      <tr key={ex.sampleId} className="hover:bg-red-50/40 transition">
                        <td className="px-4 py-3 font-mono font-semibold text-red-900">{ex.sampleId.slice(0, 8)}...</td>
                        <td className="px-4 py-3 font-semibold">{ex.sampleType}</td>
                        <td className="px-4 py-3 font-bold text-red-700">{ex.exceptionReason || 'Handling violation'}</td>
                        <td className="px-4 py-3">{ex.currentHolderId || 'N/A'}</td>
                        <td className="px-4 py-3">{new Date(ex.deliveryDeadline).toLocaleTimeString()}</td>
                        <td className="px-4 py-3 text-right">
                          <button
                            onClick={() => onSelectSample(ex.sampleId)}
                            className="px-3 py-1 bg-red-600 hover:bg-red-700 text-white rounded font-bold text-xs shadow-sm"
                          >
                            Inspect & Replan
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          )}

        </div>

      </div>

    </div>
  );
};
"}

