import React, { useState, useEffect } from 'react';
import { api, OperationsState, SampleItem, WorkerItem, LocationItem, RouteItem } from '../api';
import { MapComponent } from './MapComponent';
import { AlertTriangle, RefreshCw, Navigation, Zap, Ban, RotateCcw, MapPin, Truck, Building2, Beaker, GitFork, ShieldAlert } from 'lucide-react';

interface MonitorDashboardProps {
  onSelectSample: (sampleId: string) => void;
}

export const MonitorDashboard: React.FC<MonitorDashboardProps> = ({ onSelectSample }) => {
  const [opsState, setOpsState] = useState<OperationsState | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [activeCategory, setActiveCategory] = useState<'samples' | 'workers' | 'collection_nodes' | 'laboratories' | 'routes' | 'exceptions'>('samples');
  const [selectedSample, setSelectedSample] = useState<SampleItem | null>(null);
  const [refreshKey, setRefreshKey] = useState<number>(0);

  // Disruption report form state
  const [disruptType, setDisruptType] = useState('node');
  const [disruptId, setDisruptId] = useState('');
  const [disruptReason, setDisruptReason] = useState('Road closure / Node technical failure');
  const [disruptMsg, setDisruptMsg] = useState<string | null>(null);

  const loadOperations = async () => {
    try {
      setLoading(true);
      const data = await api.readOperationsState();
      setOpsState(data);
    } catch (err: any) {
      console.error('Failed to load operations state:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadOperations();
  }, [refreshKey]);

  const handleReportDisruption = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!disruptId.trim()) return;
    try {
      setDisruptMsg(null);
      const res = await api.reportDisruption({
        resourceType: disruptType,
        resourceId: disruptId,
        reason: disruptReason,
      });
      setDisruptMsg(`Disruption reported! Replacement plans computed: ${res.replacementPlanIds?.length || 0} journeys replanned.`);
      setRefreshKey((k) => k + 1);
    } catch (err: any) {
      setDisruptMsg(`Disruption error: ${err.message}`);
    }
  };

  const handleCancelJourney = async (journeyId: string) => {
    const reason = prompt('Reason for cancelling journey:');
    if (!reason) return;
    try {
      await api.cancelJourney({ journeyId, reason });
      setRefreshKey((k) => k + 1);
    } catch (err: any) {
      alert(`Failed to cancel journey: ${err.message}`);
    }
  };

  const handleReroute = async (journeyId: string) => {
    const targetLab = prompt('Enter new destination laboratory ID (e.g. lab_central or lab_south):');
    if (!targetLab) return;
    try {
      await api.rerouteJourney({ journeyId, targetLaboratoryId: targetLab });
      setRefreshKey((k) => k + 1);
    } catch (err: any) {
      alert(`Reroute error: ${err.message}`);
    }
  };

  const samples = opsState?.samples || [];
  const workers = opsState?.workers || [];
  const nodes = opsState?.collectionNodes || [];
  const laboratories = opsState?.laboratories || [];
  const routes = opsState?.routes || [];
  const exceptions = opsState?.exceptions || [];

  return (
    <div className="space-y-6">

      {/* Top Map + Disruption Action Bar */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Map Container */}
        <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-slate-200 p-4 h-[420px] flex flex-col">
          <div className="flex items-center justify-between mb-2">
            <div className="flex items-center space-x-2">
              <Navigation className="w-4 h-4 text-indigo-600" />
              <h2 className="text-sm font-bold text-slate-800">Live Network Map</h2>
              {opsState?.serviceabilityVersion && (
                <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-600 font-mono">
                  Version: {opsState.serviceabilityVersion}
                </span>
              )}
            </div>
            <button
              onClick={() => setRefreshKey((k) => k + 1)}
              className="p-1 text-slate-500 hover:text-slate-800 rounded hover:bg-slate-100"
              title="Refresh"
            >
              <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin text-indigo-600' : ''}`} />
            </button>
          </div>
          <div className="flex-1 rounded-lg overflow-hidden">
            <MapComponent
              locations={[...nodes, ...laboratories]}
              workers={workers}
              samples={samples}
              selectedSample={selectedSample}
              onSelectSample={(s) => {
                setSelectedSample(s);
                onSelectSample(s.sampleId);
              }}
            />
          </div>
        </div>

        {/* Dispatcher Actions & Disruption Control */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-5 space-y-4">
          <div>
            <h3 className="text-sm font-bold text-slate-900 flex items-center">
              <Zap className="w-4 h-4 mr-1.5 text-amber-500" />
              Report Disruption & Replan
            </h3>
            <p className="text-xs text-slate-500 mt-0.5">Trigger real-time automatic replanning when resources fail.</p>
          </div>

          <form onSubmit={handleReportDisruption} className="space-y-3">
            <div>
              <label className="block text-[11px] text-slate-600 font-semibold mb-1">Resource Type</label>
              <select
                value={disruptType}
                onChange={(e) => setDisruptType(e.target.value)}
                className="w-full text-xs p-1.5 rounded border border-slate-300 bg-white"
              >
                <option value="node">Collection Node / Hub</option>
                <option value="laboratory">Laboratory</option>
                <option value="worker">Worker</option>
                <option value="connection">Route Connection</option>
              </select>
            </div>

            <div>
              <label className="block text-[11px] text-slate-600 font-semibold mb-1">Resource ID</label>
              <input
                type="text"
                value={disruptId}
                onChange={(e) => setDisruptId(e.target.value)}
                placeholder="e.g. node_indiranagar or worker_1"
                className="w-full text-xs p-1.5 rounded border border-slate-300"
                required
              />
            </div>

            <div>
              <label className="block text-[11px] text-slate-600 font-semibold mb-1">Disruption Reason</label>
              <input
                type="text"
                value={disruptReason}
                onChange={(e) => setDisruptReason(e.target.value)}
                className="w-full text-xs p-1.5 rounded border border-slate-300"
                required
              />
            </div>

            {disruptMsg && (
              <div className="text-xs p-2 rounded bg-amber-50 border border-amber-200 text-amber-900 font-medium">
                {disruptMsg}
              </div>
            )}

            <button
              type="submit"
              className="w-full py-2 bg-amber-600 hover:bg-amber-700 text-white rounded text-xs font-bold transition shadow"
            >
              Report Disruption & Trigger Replan
            </button>
          </form>
        </div>

      </div>

      {/* Monitor Categories Navigation & Tables */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">

        {/* Category Tabs */}
        <div className="flex border-b border-slate-200 bg-slate-50 px-6 pt-3 space-x-2 sm:space-x-4 overflow-x-auto">
          <button
            onClick={() => setActiveCategory('samples')}
            className={`pb-3 text-xs font-bold border-b-2 flex items-center space-x-1.5 transition ${
              activeCategory === 'samples' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-800'
            }`}
          >
            <Truck className="w-3.5 h-3.5" />
            <span>Samples ({samples.length})</span>
          </button>

          <button
            onClick={() => setActiveCategory('workers')}
            className={`pb-3 text-xs font-bold border-b-2 flex items-center space-x-1.5 transition ${
              activeCategory === 'workers' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-800'
            }`}
          >
            <span>Workers ({workers.length})</span>
          </button>

          <button
            onClick={() => setActiveCategory('collection_nodes')}
            className={`pb-3 text-xs font-bold border-b-2 flex items-center space-x-1.5 transition ${
              activeCategory === 'collection_nodes' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-800'
