            }`}
          >
            <Beaker className="w-3.5 h-3.5" />
            <span>Laboratories ({laboratories.length})</span>
          </button>

          <button
            onClick={() => setActiveCategory('routes')}
            className={`pb-3 text-xs font-bold border-b-2 flex items-center space-x-1.5 transition ${
              activeCategory === 'routes' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-800'
            }`}
