                    <tr key={lab.locationId} className="hover:bg-slate-50 transition">
                      <td className="px-4 py-3 font-semibold text-slate-900">{lab.name}</td>
                      <td className="px-4 py-3 font-mono">{lab.code}</td>
                      <td className="px-4 py-3">{(lab.acceptedSampleTypes || []).join(', ') || 'All'}</td>
                      <td className="px-4 py-3">
                        <b>{lab.regularCapacity - (lab.regularReserved || 0)}</b> / {lab.regularCapacity} avail
