import React, { useState, useEffect } from 'react';
import { api, AuditRecord } from '../api';
import { Search, History, RefreshCw, CheckCircle, XCircle, AlertCircle } from 'lucide-react';

export const AuditView: React.FC = () => {
  const [records, setRecords] = useState<AuditRecord[]>([]);
  const [total, setTotal] = useState<number>(0);
  const [loading, setLoading] = useState<boolean>(true);
  const [query, setQuery] = useState<string>('');
  const [entityType, setEntityType] = useState<string>('');
  const [action, setAction] = useState<string>('');
  const [selectedRecord, setSelectedRecord] = useState<AuditRecord | null>(null);

  const searchLogs = async () => {
    try {
      setLoading(true);
      const res = await api.searchAuditTrail({
        query: query.trim(),
        entityType: entityType.trim(),
        action: action.trim(),
        limit: 100,
      });
      setRecords(res.records || []);
      setTotal(res.total || 0);
    } catch (err: any) {
      console.error('Failed to search audit trail:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    searchLogs();
  }, []);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    searchLogs();
  };

  return (
    <div className="space-y-6">
      {/* Header & Search Bar */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
        <div className="flex items-center space-x-2 text-slate-900 font-bold text-base mb-1">
          <History className="w-5 h-5 text-indigo-600" />
          <h2>Audit History & System Log</h2>
        </div>
        <p className="text-xs text-slate-500 mb-4">Searchable tamper-evident log of all network events, handoffs, and actions.</p>

        <form onSubmit={handleSearchSubmit} className="grid grid-cols-1 sm:grid-cols-4 gap-3">
          <div className="sm:col-span-2">
            <label htmlFor="audit-search" className="block text-[11px] font-semibold text-slate-700 mb-1">Search audit history</label>
            <div className="relative">
              <input
                id="audit-search"
                type="text"
                placeholder="Search audit history by user, entity ID, or keyword..."
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                className="w-full text-xs pl-8 pr-3 py-2 rounded-lg border border-slate-300 focus:ring-1 focus:ring-indigo-500"
              />
              <Search className="w-4 h-4 text-slate-400 absolute left-2.5 top-2.5" />
            </div>
          </div>

          <div>
            <label htmlFor="audit-entity-type" className="block text-[11px] font-semibold text-slate-700 mb-1">Entity Type</label>
            <select
              id="audit-entity-type"
              value={entityType}
              onChange={(e) => setEntityType(e.target.value)}
              className="w-full text-xs py-2 px-2.5 rounded-lg border border-slate-300 bg-white"
            >
              <option value="">All Entities</option>
              <option value="sample">Sample</option>
              <option value="assignment">Assignment</option>
              <option value="handoff">Handoff</option>
              <option value="journey">Journey</option>
              <option value="user">User</option>
              <option value="location">Location</option>
              <option value="disruption">Disruption</option>
            </select>
          </div>

          <div className="flex items-end space-x-2">
            <button
              type="submit"
              disabled={loading}
              className="flex-1 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg text-xs font-bold transition shadow disabled:opacity-50"
            >
              Search
            </button>
            <button
              type="button"
              onClick={() => { setQuery(''); setEntityType(''); setAction(''); searchLogs(); }}
              className="px-3 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-xs font-semibold"
              title="Reset Filters"
            >
              Reset
            </button>
          </div>
        </form>
      </div>

      {/* Audit Records Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden p-6">
        <div className="flex items-center justify-between mb-4">
          <div className="text-xs text-slate-500">
            Showing <b className="text-slate-800">{records.length}</b> of {total} records
          </div>
          <button
            onClick={searchLogs}
            className="p-1.5 text-slate-500 hover:text-slate-800 rounded hover:bg-slate-100"
            title="Refresh"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin text-indigo-600' : ''}`} />
          </button>
        </div>

        {records.length === 0 ? (
          <div className="text-xs text-slate-400 py-10 text-center italic border border-dashed rounded-lg">
            No audit records matching criteria.
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs text-slate-700">
              <thead className="bg-slate-50 text-slate-600 uppercase font-semibold border-b border-slate-200">
                <tr>
                  <th className="px-4 py-2.5">Timestamp</th>
                  <th className="px-4 py-2.5">User / Actor</th>
                  <th className="px-4 py-2.5">Role</th>
                  <th className="px-4 py-2.5">Action</th>
                  <th className="px-4 py-2.5">Entity</th>
                  <th className="px-4 py-2.5">Outcome</th>
                  <th className="px-4 py-2.5 text-right">Details</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {records.map((rec) => (
                  <tr key={rec.auditId} className="hover:bg-slate-50 transition">
                    <td className="px-4 py-3 text-slate-500 font-mono text-[11px]">
                      {new Date(rec.occurredAt).toLocaleString()}
                    </td>
                    <td className="px-4 py-3 font-semibold text-slate-900">
                      {rec.actorId || 'System'}
                    </td>
                    <td className="px-4 py-3 capitalize text-slate-600">{rec.actorRole || 'System'}</td>
                    <td className="px-4 py-3 font-bold text-indigo-700">{rec.action}</td>
                    <td className="px-4 py-3">
                      <span className="font-mono text-slate-800">
                        {rec.entityType}:{rec.entityId ? rec.entityId.slice(0, 10) : ''}
                      </span>
                    </td>
                    <td className="px-4 py-3">
                      <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase ${
                        rec.success ? 'bg-emerald-100 text-emerald-800' : 'bg-red-100 text-red-800'
                      }`}>
                        {rec.success ? (
                          <>
                            <CheckCircle className="w-3 h-3 mr-1 text-emerald-600" />
                            Success
                          </>
                        ) : (
                          <>
                            <XCircle className="w-3 h-3 mr-1 text-red-600" />
                            Failure
                          </>
                        )}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-right">
                      {rec.details && (
                        <button
                          onClick={() => setSelectedRecord(rec)}
                          className="px-2.5 py-1 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded text-xs"
                        >
                          View Payload
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Record Payload Detail Modal */}
      {selectedRecord && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-lg w-full p-6 space-y-4">
            <h3 className="text-sm font-bold text-slate-900">Audit Record Payload</h3>
            <div className="text-xs space-y-1 text-slate-600">
              <div><b>Action:</b> {selectedRecord.action}</div>
              <div><b>Actor:</b> {selectedRecord.actorId} ({selectedRecord.actorRole})</div>
              <div><b>Entity:</b> {selectedRecord.entityType}:{selectedRecord.entityId}</div>
              <div><b>Timestamp:</b> {new Date(selectedRecord.occurredAt).toLocaleString()}</div>
            </div>
            <pre className="bg-slate-900 text-slate-100 p-3 rounded-lg text-xs font-mono max-h-60 overflow-y-auto">
              {JSON.stringify(selectedRecord.details, null, 2)}
            </pre>
            <div className="flex justify-end">
              <button
                onClick={() => setSelectedRecord(null)}
                className="px-4 py-1.5 bg-slate-200 hover:bg-slate-300 text-slate-800 rounded text-xs font-semibold"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

