    sequence?: number;
    recordedAt?: string;
  }): Promise<any> {
    const res = await fetch(`${API_BASE}/record-worker-location`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        assignmentId: params.assignmentId || '',
        coordinate: params.coordinate,
        sequence: params.sequence || 1,
        recordedAt: params.recordedAt || new Date().toISOString(),
      }),
    });
    return handleResponse(res);
  },

  async updateAssignmentProgress(params: {
    assignmentId: string;
    status: string;
  }): Promise<any> {
    const res = await fetch(`${API_BASE}/update-assignment-progress`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        assignmentId: params.assignmentId,
        status: params.status,
        occurredAt: new Date().toISOString(),
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  // Operations, Sample Lifecycle & Audit
  async readOperationsState(filters?: any): Promise<OperationsState> {
    const res = await fetch(`${API_BASE}/read-operations-state`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({ filters: filters || {} }),
    });
    return handleResponse<OperationsState>(res);
  },

  async readSampleLifecycle(sampleId: string): Promise<SampleLifecycle> {
    const res = await fetch(`${API_BASE}/read-sample-lifecycle`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({ sampleId }),
    });
    return handleResponse<SampleLifecycle>(res);
  },

  async readSampleState(sampleId: string): Promise<SampleItem> {
    const res = await fetch(`${API_BASE}/read-sample-state/${sampleId}`, {
      headers: getAuthHeader(),
    });
    return handleResponse<SampleItem>(res);
  },

  async readJourneyPlan(journeyId: string): Promise<any> {
    const res = await fetch(`${API_BASE}/read-journey-plan`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({ journeyId }),
    });
    return handleResponse(res);
  },

  async searchAuditTrail(params?: {
    query?: string;
    actorId?: string;
    entityType?: string;
    entityId?: string;
    action?: string;
    role?: string;
    limit?: number;
  }): Promise<{ total: number; records: AuditRecord[] }> {
    const res = await fetch(`${API_BASE}/search-audit-trail`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        query: params?.query || '',
        actorId: params?.actorId || '',
        entityType: params?.entityType || '',
        entityId: params?.entityId || '',
        action: params?.action || '',
        role: params?.role || '',
        limit: params?.limit || 50,
      }),
    });
    return handleResponse<{ total: number; records: AuditRecord[] }>(res);
  },

  // Journeys & Disruptions
  async rerouteJourney(params: { journeyId: string; targetLaboratoryId: string; reason?: string }): Promise<any> {
    const res = await fetch(`${API_BASE}/reroute-journey`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        reason: params.reason || 'Rerouted by dispatcher',
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async cancelJourney(params: { journeyId: string; reason?: string }): Promise<any> {
    const res = await fetch(`${API_BASE}/cancel-journey`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        reason: params.reason || 'Cancelled by dispatcher',
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async reportDisruption(params: { resourceType: string; resourceId: string; reason?: string }): Promise<any> {
    const res = await fetch(`${API_BASE}/report-disruption`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        reason: params.reason || 'Resource unavailable disruption',
        occurredAt: new Date().toISOString(),
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  // Capacity & Network Configuration
  async configureCapacity(params: {
    locationId?: string;
    connectionId?: string;
    regularCapacity: number;
    cooledCapacity: number;
  }): Promise<any> {
    const res = await fetch(`${API_BASE}/configure-capacity`, {
      method: 'POST',
      headers: getAuthHeader(),
      body: JSON.stringify({
        ...params,
        idempotencyKey: uuidv4(),
      }),
    });
    return handleResponse(res);
  },

  async configureLaboratoryAcceptance(params: {
    laboratoryId: string;
    acceptedSampleTypes: string[];
  }): Promise<any> {
