      setMsg(`User ${uUsername} created!`);
      setUUsername('');
      setUFullName('');
      setUPassword('');
    } catch (err: any) {
      setMsg(`Error: ${err.message}`);
    }
  };

  const handleUpdateCapacity = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setMsg(null);
      await api.configureCapacity({
        locationId: capLocId,
        regularCapacity: Number(capReg),
        cooledCapacity: Number(capCool),
      });
      setMsg('Capacity updated successfully!');
      loadData();
    } catch (err: any) {
      setMsg(`Error: ${err.message}`);
    }
  };

  return (
    <div className="space-y-6">
