import React, { useState, useEffect } from 'react';
import { api, LocationItem } from '../api';
import { Settings, Users, Building, Plus, ToggleLeft, ToggleRight, Check, AlertCircle } from 'lucide-react';

export const AdminConfigView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'users' | 'locations' | 'sample_types' | 'capacity'>('locations');
  const [locations, setLocations] = useState<LocationItem[]>([]);
  const [sampleTypes, setSampleTypes] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);

  // New Location Form
  const [locName, setLocName] = useState('');
  const [locCode, setLocCode] = useState('');
  const [locType, setLocType] = useState('hub');
  const [locLat, setLocLat] = useState('12.9716');
  const [locLng, setLocLng] = useState('77.5946');
  const [locRegCap, setLocRegCap] = useState(100);
  const [locCoolCap, setLocCoolCap] = useState(50);

  // New Sample Type Form
  const [stName, setStName] = useState('');
  const [stContainer, setStContainer] = useState('insulated_cooler');
  const [stMinTemp, setStMinTemp] = useState('2.0');
  const [stMaxTemp, setStMaxTemp] = useState('8.0');
  const [stQualifiedReq, setStQualifiedReq] = useState(true);
  const [stCooledReq, setStCooledReq] = useState(true);
  const [stTimeCritical, setStTimeCritical] = useState(false);

  // New User Form
  const [uUsername, setUUsername] = useState('');
  const [uFullName, setUFullName] = useState('');
  const [uPassword, setUPassword] = useState('');
  const [uRoles, setURoles] = useState('collection_professional');

  // Capacity Form
  const [capLocId, setCapLocId] = useState('');
  const [capReg, setCapReg] = useState(100);
  const [capCool, setCapCool] = useState(50);

  const loadData = async () => {
    try {
      setLoading(true);
      const ops = await api.readOperationsState();
      setLocations([...(ops.collectionNodes || []), ...(ops.laboratories || [])]);
    } catch (err: any) {
      console.error('Failed to load admin data:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleCreateLocation = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setMsg(null);
      await api.createLocation({
        name: locName,
        code: locCode,
        type: locType,
        latitude: parseFloat(locLat),
        longitude: parseFloat(locLng),
        regularCapacity: Number(locRegCap),
        cooledCapacity: Number(locCoolCap),
      });
      setMsg(`Location ${locName} created successfully!`);
      setLocName('');
      setLocCode('');
      loadData();
    } catch (err: any) {
      setMsg(`Error: ${err.message}`);
    }
  };

  const handleToggleLocation = async (loc: LocationItem) => {
    const newStatus = loc.status === 'active' ? 'inactive' : 'active';
    try {
      await api.setLocationStatus({ locationId: loc.locationId, status: newStatus });
      loadData();
    } catch (err: any) {
      alert(`Failed to update location status: ${err.message}`);
    }
  };

  const handleCreateSampleType = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setMsg(null);
      await api.createSampleType({
        name: stName,
        containerType: stContainer,
        minTemperatureC: parseFloat(stMinTemp),
        maxTemperatureC: parseFloat(stMaxTemp),
        requiresQualifiedCollector: stQualifiedReq,
        requiresCooledStorage: stCooledReq,
        timeCritical: stTimeCritical,
      });
      setMsg(`Sample type ${stName} created!`);
      setStName('');
    } catch (err: any) {
      setMsg(`Error: ${err.message}`);
    }
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setMsg(null);
      await api.createUser({
        username: uUsername,
        fullName: uFullName,
        password: uPassword,
        roles: uRoles.split(',').map((r) => r.trim()),
      });
      setMsg(`User ${uUsername} created!`);
      setUUsername('');
      setUFullName('');
      setUPassword('');
    } catch (err: any) {
      setMsg(`Error: ${err.message}`);
    }
  };

  const handleUpdateCapacity = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setMsg(null);
      await api.configureCapacity({
        locationId: capLocId,
        regularCapacity: Number(capReg),
        cooledCapacity: Number(capCool),
      });
      setMsg('Capacity updated successfully!');
      loadData();
    } catch (err: any) {
      setMsg(`Error: ${err.message}`);
    }
  };

  return (
    <div className="space-y-6">
      {/* Header & Tabs */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="p-6 border-b border-slate-200">
          <div className="flex items-center space-x-2 text-slate-900 font-bold text-base">
            <Settings className="w-5 h-5 text-indigo-600" />
            <h2>System Administration & Configuration</h2>
          </div>
          <p className="text-xs text-slate-500 mt-1">Manage users, network nodes, sample types, and capacity pools.</p>
        </div>

        {/* Tab Buttons */}
        <div className="flex border-b border-slate-200 bg-slate-50 px-6 pt-3 space-x-6">
          <button
            onClick={() => { setActiveTab('locations'); setMsg(null); }}
            className={`pb-3 text-xs font-bold border-b-2 transition ${
              activeTab === 'locations' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-800'
            }`}
          >
            Network Locations
          </button>
          <button
            onClick={() => { setActiveTab('capacity'); setMsg(null); }}
            className={`pb-3 text-xs font-bold border-b-2 transition ${
              activeTab === 'capacity' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-800'
            }`}
          >
            Configure Capacity
          </button>
          <button
            onClick={() => { setActiveTab('sample_types'); setMsg(null); }}
            className={`pb-3 text-xs font-bold border-b-2 transition ${
              activeTab === 'sample_types' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-800'
            }`}
          >
            Sample Types
          </button>
          <button
            onClick={() => { setActiveTab('users'); setMsg(null); }}
            className={`pb-3 text-xs font-bold border-b-2 transition ${
              activeTab === 'users' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-500 hover:text-slate-800'
            }`}
          >
            User Management
          </button>
        </div>

        <div className="p-6">
          {msg && (
            <div className="mb-4 p-3 bg-indigo-50 border border-indigo-200 text-indigo-900 rounded text-xs font-medium">
              {msg}
            </div>
          )}

          {/* LOCATIONS TAB */}
          {activeTab === 'locations' && (
            <div className="space-y-6">
              {/* Create Location Form */}
              <form onSubmit={handleCreateLocation} className="bg-slate-50 p-4 rounded-lg border border-slate-200 space-y-3">
                <div className="text-xs font-bold text-slate-800">Add New Network Location</div>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                  <div>
                    <label className="block text-[11px] text-slate-600 mb-1">Name</label>
                    <input
                      type="text"
                      value={locName}
                      onChange={(e) => setLocName(e.target.value)}
                      placeholder="e.g. Indiranagar Collection Hub"
                      className="w-full text-xs p-1.5 rounded border border-slate-300"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-[11px] text-slate-600 mb-1">Code</label>
                    <input
                      type="text"
                      value={locCode}
                      onChange={(e) => setLocCode(e.target.value)}
                      placeholder="e.g. NODE_INDIRA"
                      className="w-full text-xs p-1.5 rounded border border-slate-300"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-[11px] text-slate-600 mb-1">Type</label>
                    <select
                      value={locType}
                      onChange={(e) => setLocType(e.target.value)}
                      className="w-full text-xs p-1.5 rounded border border-slate-300 bg-white"
                    >
                      <option value="collection_point">Collection Point</option>
                      <option value="transfer_hub">Transfer Hub</option>
                      <option value="laboratory">Laboratory</option>
                      <option value="hub">Combined Hub & Lab</option>
                    </select>
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-4 gap-3">
                  <div>
                    <label className="block text-[11px] text-slate-600 mb-1">Latitude</label>
                    <input
                      type="text"
                      value={locLat}
                      onChange={(e) => setLocLat(e.target.value)}
                      className="w-full text-xs p-1.5 rounded border border-slate-300"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-[11px] text-slate-600 mb-1">Longitude</label>
                    <input
                      type="text"
                      value={locLng}
                      onChange={(e) => setLocLng(e.target.value)}
                      className="w-full text-xs p-1.5 rounded border border-slate-300"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-[11px] text-slate-600 mb-1">Regular Capacity</label>
                    <input
                      type="number"
                      value={locRegCap}
                      onChange={(e) => setLocRegCap(Number(e.target.value))}
                      className="w-full text-xs p-1.5 rounded border border-slate-300"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-[11px] text-slate-600 mb-1">Cooled Capacity</label>
                    <input
                      type="number"
                      value={locCoolCap}
                      onChange={(e) => setLocCoolCap(Number(e.target.value))}
                      className="w-full text-xs p-1.5 rounded border border-slate-300"
                      required
                    />
                  </div>
                </div>

                <button
                  type="submit"
                  className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded text-xs font-bold shadow"
                >
                  Create Location
                </button>
              </form>

              {/* Locations List */}
              <div className="overflow-x-auto">
                <table className="w-full text-left text-xs text-slate-700">
                  <thead className="bg-slate-50 text-slate-600 uppercase font-semibold border-b">
                    <tr>
                      <th className="px-4 py-2.5">Name</th>
                      <th className="px-4 py-2.5">Code</th>
                      <th className="px-4 py-2.5">Type</th>
                      <th className="px-4 py-2.5">Capacity (Reg / Cool)</th>
                      <th className="px-4 py-2.5">Status</th>
                      <th className="px-4 py-2.5 text-right">Toggle Active</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {locations.map((loc) => (
                      <tr key={loc.locationId} className="hover:bg-slate-50">
                        <td className="px-4 py-3 font-semibold text-slate-900">{loc.name}</td>
                        <td className="px-4 py-3 font-mono">{loc.code}</td>
                        <td className="px-4 py-3 capitalize">{loc.type}</td>
                        <td className="px-4 py-3">{loc.regularCapacity} / {loc.cooledCapacity}</td>
                        <td className="px-4 py-3">
                          <span className={`px-2 py-0.5 rounded-full font-bold uppercase text-[10px] ${
                            loc.status === 'active' ? 'bg-emerald-100 text-emerald-800' : 'bg-red-100 text-red-800'
                          }`}>
                            {loc.status}
                          </span>
                        </td>
                        <td className="px-4 py-3 text-right">
                          <button
                            onClick={() => handleToggleLocation(loc)}
                            className={`px-3 py-1 rounded text-xs font-semibold ${
                              loc.status === 'active' ? 'bg-red-50 text-red-700 hover:bg-red-100' : 'bg-emerald-50 text-emerald-700 hover:bg-emerald-100'
                            }`}
                          >
                            {loc.status === 'active' ? 'Deactivate' : 'Activate'}
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* CAPACITY CONFIG TAB */}
          {activeTab === 'capacity' && (
            <form onSubmit={handleUpdateCapacity} className="max-w-md space-y-4 bg-slate-50 p-4 rounded-lg border border-slate-200">
              <div className="text-xs font-bold text-slate-800">Configure Node / Connection Capacity</div>
              <div>
                <label className="block text-[11px] text-slate-600 mb-1">Select Location</label>
                <select
                  value={capLocId}
                  onChange={(e) => {
                    setCapLocId(e.target.value);
                    const l = locations.find((x) => x.locationId === e.target.value);
                    if (l) {
                      setCapReg(l.regularCapacity);
                      setCapCool(l.cooledCapacity);
                    }
                  }}
                  className="w-full text-xs p-2 rounded border border-slate-300 bg-white"
                  required
                >
                  <option value="">-- Choose Location --</option>
                  {locations.map((l) => (
                    <option key={l.locationId} value={l.locationId}>
                      {l.name} ({l.code})
                    </option>
                  ))}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[11px] text-slate-600 mb-1">Regular Capacity Units</label>
                  <input
                    type="number"
                    value={capReg}
                    onChange={(e) => setCapReg(Number(e.target.value))}
                    className="w-full text-xs p-2 rounded border border-slate-300"
                    required
                  />
                </div>
                <div>
                  <label className="block text-[11px] text-slate-600 mb-1">Cooled Capacity Units</label>
                  <input
                    type="number"
                    value={capCool}
                    onChange={(e) => setCapCool(Number(e.target.value))}
                    className="w-full text-xs p-2 rounded border border-slate-300"
                    required
                  />
                </div>
              </div>
              <button
                type="submit"
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded text-xs font-bold shadow"
              >
                Save Capacity Pool
              </button>
            </form>
          )}

          {/* SAMPLE TYPES TAB */}
          {activeTab === 'sample_types' && (
            <form onSubmit={handleCreateSampleType} className="max-w-lg space-y-4 bg-slate-50 p-4 rounded-lg border border-slate-200">
              <div className="text-xs font-bold text-slate-800">Add New Sample Type</div>
              <div>
                <label className="block text-[11px] text-slate-600 mb-1">Type Name</label>
                <input
                  type="text"
                  value={stName}
                  onChange={(e) => setStName(e.target.value)}
                  placeholder="e.g. Plasma_Frozen"
                  className="w-full text-xs p-2 rounded border border-slate-300"
                  required
                />
              </div>
              <div>
                <label className="block text-[11px] text-slate-600 mb-1">Container Type</label>
                <select
                  value={stContainer}
                  onChange={(e) => setStContainer(e.target.value)}
                  className="w-full text-xs p-2 rounded border border-slate-300 bg-white"
                >
                  <option value="insulated_cooler">Insulated Cooler</option>
                  <option value="standard_biohazard_box">Standard Biohazard Box</option>
                  <option value="ambient_pouch">Ambient Pouch</option>
                </select>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[11px] text-slate-600 mb-1">Min Temp (°C)</label>
                  <input
                    type="number"
                    step="0.1"
                    value={stMinTemp}
                    onChange={(e) => setStMinTemp(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300"
                  />
                </div>
                <div>
                  <label className="block text-[11px] text-slate-600 mb-1">Max Temp (°C)</label>
                  <input
                    type="number"
                    step="0.1"
                    value={stMaxTemp}
                    onChange={(e) => setStMaxTemp(e.target.value)}
                    className="w-full text-xs p-2 rounded border border-slate-300"
                  />
                </div>
              </div>
              <div className="space-y-2 pt-2">
                <label className="flex items-center text-xs text-slate-700">
                  <input
                    type="checkbox"
                    checked={stQualifiedReq}
                    onChange={(e) => setStQualifiedReq(e.target.checked)}
                    className="mr-2"
                  />
                  Requires Qualified Collector
                </label>
                <label className="flex items-center text-xs text-slate-700">
                  <input
                    type="checkbox"
                    checked={stCooledReq}
                    onChange={(e) => setStCooledReq(e.target.checked)}
                    className="mr-2"
                  />
                  Requires Cooled Storage & Transport
                </label>
                <label className="flex items-center text-xs text-slate-700">
                  <input
                    type="checkbox"
                    checked={stTimeCritical}
                    onChange={(e) => setStTimeCritical(e.target.checked)}
                    className="mr-2"
                  />
                  Time Critical (No Batching Delay)
                </label>
              </div>
              <button
                type="submit"
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded text-xs font-bold shadow"
              >
                Create Sample Type
              </button>
            </form>
          )}

          {/* USER MANAGEMENT TAB */}
          {activeTab === 'users' && (
            <form onSubmit={handleCreateUser} className="max-w-md space-y-4 bg-slate-50 p-4 rounded-lg border border-slate-200">
              <div className="text-xs font-bold text-slate-800">Create New User Account</div>
              <div>
                <label className="block text-[11px] text-slate-600 mb-1">Username</label>
                <input
                  type="text"
                  value={uUsername}
                  onChange={(e) => setUUsername(e.target.value)}
                  placeholder="e.g. collector_jane"
                  className="w-full text-xs p-2 rounded border border-slate-300"
                  required
                />
              </div>
              <div>
                <label className="block text-[11px] text-slate-600 mb-1">Full Name</label>
                <input
                  type="text"
                  value={uFullName}
                  onChange={(e) => setUFullName(e.target.value)}
                  placeholder="e.g. Jane Doe"
                  className="w-full text-xs p-2 rounded border border-slate-300"
                  required
                />
              </div>
              <div>
                <label className="block text-[11px] text-slate-600 mb-1">Password</label>
                <input
                  type="password"
                  value={uPassword}
                  onChange={(e) => setUPassword(e.target.value)}
                  className="w-full text-xs p-2 rounded border border-slate-300"
                  required
                />
              </div>
              <div>
                <label className="block text-[11px] text-slate-600 mb-1">Assigned Roles (comma-separated)</label>
                <input
                  type="text"
                  value={uRoles}
                  onChange={(e) => setURoles(e.target.value)}
                  placeholder="e.g. collection_professional, delivery_partner"
                  className="w-full text-xs p-2 rounded border border-slate-300"
                  required
                />
              </div>
              <button
                type="submit"
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded text-xs font-bold shadow"
              >
                Create User
              </button>
            </form>
          )}

        </div>
      </div>
    </div>
  );
};

