			return
		}
		if !auth.HasRole(user, "administrator", "dispatcher") {
			SendError(w, http.StatusForbidden, "forbidden", "Only dispatcher or administrator can cancel journey")
			return
		}

		var req struct {
			JourneyId           string `json:"journeyId"`
			ExpectedPlanVersion int    `json:"expectedPlanVersion"`
			Reason              string `json:"reason"`
			IdempotencyKey      string `json:"idempotencyKey"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			SendError(w, http.StatusBadRequest, "invalid_json", "Invalid JSON")
			return
		}
		if req.IdempotencyKey == "" {
			SendError(w, http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
			return
		}

		sampleIds, err := service.CancelJourney(db, user, req.JourneyId, req.ExpectedPlanVersion, req.Reason)
