func ConfirmHandoff(db *sql.DB, actor *models.User, handoffId, confirmationSide, confirmedAt string) (string, bool, bool, string, error) {
	var h struct {
		HandoffId        string
		SampleId         string
		FromAssignmentId string
		ToAssignmentId   string
		SenderId         string
		ReceiverId       string
		SenderConfirmed  bool
		ReceiverConfirmed bool
		Status           string
	}
	err := db.QueryRow(`
		SELECT handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, sender_confirmed, receiver_confirmed, status
		FROM handoffs
		WHERE handoff_id = $1
	`, handoffId).Scan(&h.HandoffId, &h.SampleId, &h.FromAssignmentId, &h.ToAssignmentId, &h.SenderId, &h.ReceiverId, &h.SenderConfirmed, &h.ReceiverConfirmed, &h.Status)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return "", false, false, "", ErrNotFound
		}
		return "", false, false, "", err
	}

	senderConf := h.SenderConfirmed
	receiverConf := h.ReceiverConfirmed

	if confirmationSide == "sender" {
		senderConf = true
		_, _ = db.Exec("UPDATE handoffs SET sender_confirmed = true, sender_confirmed_at = NOW() WHERE handoff_id = $1", handoffId)
	} else if confirmationSide == "receiver" {
		receiverConf = true
		_, _ = db.Exec("UPDATE handoffs SET receiver_confirmed = true, receiver_confirmed_at = NOW() WHERE handoff_id = $1", handoffId)
	}

	status := "pending"
	currentHolder := h.SenderId

	if senderConf && receiverConf {
		status = "confirmed"
		currentHolder = h.ReceiverId
		_, _ = db.Exec("UPDATE handoffs SET status = 'confirmed' WHERE handoff_id = $1", handoffId)
		_, _ = db.Exec("UPDATE samples SET current_holder_id = $1, pending_handoff_id = NULL, updated_at = NOW() WHERE sample_id = $2", h.ReceiverId, h.SampleId)
		_, _ = db.Exec("UPDATE assignments SET status = 'completed', updated_at = NOW() WHERE assignment_id = $1", h.FromAssignmentId)
		_, _ = db.Exec("UPDATE assignments SET status = 'in_progress', worker_id = $1, updated_at = NOW() WHERE assignment_id = $2", h.ReceiverId, h.ToAssignmentId)
	}

	LogAudit(db, actor.UserId, actor.ActiveRole, "confirm_handoff", "handoff", handoffId, true, map[string]interface{}{
		"confirmationSide": confirmationSide,
		"status":           status,
		"currentHolderId":  currentHolder,
	})

	LogTimeline(db, &h.SampleId, nil, &h.ToAssignmentId, "handoff_confirmed", actor.UserId, actor.ActiveRole, "handoff", handoffId, true, map[string]interface{}{
		"side":            confirmationSide,
		"status":          status,
		"currentHolderId": currentHolder,
	})

	BroadcastRealtimeEvent(db, "custody_transferred", "sample", h.SampleId, map[string]interface{}{
		"sampleId":        h.SampleId,
		"currentHolderId": currentHolder,
		"handoffStatus":   status,
	})

	return status, senderConf, receiverConf, currentHolder, nil
}

func RecordCheckpoint(db *sql.DB, actor *models.User, sampleId string, assignmentId *string, locationId *string, containerType string, observedTemp float64) (string, bool, string, error) {
	var s struct {
		SampleId  string
		Container string
		TempMin   float64
		TempMax   float64
		Status    string
	}
	err := db.QueryRow(`
		SELECT sample_id, container_type, temperature_min_c, temperature_max_c, status
		FROM samples
		WHERE sample_id = $1
	`, sampleId).Scan(&s.SampleId, &s.Container, &s.TempMin, &s.TempMax, &s.Status)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return "", false, "", ErrNotFound
		}
		return "", false, "", err
	}

	compliant := true
	if (containerType != "" && containerType != s.Container) || observedTemp < s.TempMin || observedTemp > s.TempMax {
		compliant = false
	}

	checkpointId := uuid.New().String()
	_, err = db.Exec(`
		INSERT INTO checkpoints (checkpoint_id, sample_id, assignment_id, location_id, recorder_id, container_type, observed_temperature_c, compliant, recorded_at)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8, NOW())
	`, checkpointId, sampleId, assignmentId, locationId, actor.UserId, containerType, observedTemp, compliant)
	if err != nil {
		return "", false, "", err
	}

	finalStatus := s.Status
	if !compliant {
		finalStatus = "exception"
		_, _ = db.Exec(`
			UPDATE samples
			SET status = 'exception', exception = jsonb_build_object('reason', 'checkpoint_excursion', 'observedTemp', $1, 'containerType', $2), updated_at = NOW()
			WHERE sample_id = $3
		`, observedTemp, containerType, sampleId)
	}

	LogAudit(db, actor.UserId, actor.ActiveRole, "record_handling_checkpoint", "checkpoint", checkpointId, compliant, map[string]interface{}{
		"sampleId":     sampleId,
		"compliant":    compliant,
		"sampleStatus": finalStatus,
	})

	LogTimeline(db, &sampleId, nil, assignmentId, "checkpoint_recorded", actor.UserId, actor.ActiveRole, "checkpoint", checkpointId, compliant, map[string]interface{}{
		"containerType": containerType,
		"observedTemp":  observedTemp,
		"compliant":     compliant,
	})

	return checkpointId, compliant, finalStatus, nil
}

