func FindShortestRoute(startLocId string, targetLabs []models.OperationsLocation, allLocs []models.OperationsLocation, allConns []models.OperationsConnection, requiresCooled bool) ([]string, string, int, float64, error) {
	labMap := make(map[string]bool)
	for _, l := range targetLabs {
		labMap[l.LocationId] = true
	}

	// Direct check: if startLoc is already an accepting lab
	if labMap[startLocId] {
		return []string{startLocId}, startLocId, 0, 0, nil
	}

	// Graph adjacency
	type Edge struct {
		ToLocId string
		Minutes int
		Cost    float64
	}
	adj := make(map[string][]Edge)
	for _, c := range allConns {
		if !c.Active {
			continue
		}
		if requiresCooled && (!c.Cooled || (c.Capacity != nil && c.Capacity.CooledAvailableUnits <= 0)) {
			continue
		}
		if !requiresCooled && c.Capacity != nil && c.Capacity.AvailableUnits <= 0 {
			continue
		}
		adj[c.FromLocationId] = append(adj[c.FromLocationId], Edge{
			ToLocId: c.ToLocationId,
			Minutes: c.TravelMinutes,
			Cost:    c.CostUnits,
		})
	}

	locMap := make(map[string]models.OperationsLocation)
	for _, l := range allLocs {
		locMap[l.LocationId] = l
	}

	// Dijkstra
	dist := make(map[string]int)
	costDist := make(map[string]float64)
	prev := make(map[string]string)
	visited := make(map[string]bool)

	for _, l := range allLocs {
		dist[l.LocationId] = math.MaxInt32
		costDist[l.LocationId] = math.MaxFloat64
	}
	dist[startLocId] = 0
	costDist[startLocId] = 0

	for len(visited) < len(allLocs) {
		u := ""
		minD := math.MaxInt32
		for locId, d := range dist {
			if !visited[locId] && d < minD {
				minD = d
				u = locId
			}
		}
		if u == "" || minD == math.MaxInt32 {
			break
		}
		visited[u] = true

		if labMap[u] {
			// Found shortest path to a lab!
			path := []string{}
			curr := u
			for curr != "" {
				path = append([]string{curr}, path...)
				curr = prev[curr]
			}
			return path, u, dist[u], costDist[u], nil
		}

		handling := 0
		if loc, ok := locMap[u]; ok && u != startLocId {
			handling = loc.HandlingMinutes
		}

		for _, edge := range adj[u] {
			if visited[edge.ToLocId] {
				continue
			}
			newDist := dist[u] + edge.Minutes + handling
			newCost := costDist[u] + edge.Cost
			if newDist < dist[edge.ToLocId] {
				dist[edge.ToLocId] = newDist
				costDist[edge.ToLocId] = newCost
				prev[edge.ToLocId] = u
			}
		}
	}

