	}

	return &models.ServiceabilitySnapshot{
		Version:                    newVer,
		Status:                     "complete",
		ComputedAt:                 now.Format(time.RFC3339Nano),
		NetworkRevision:            newRev,
		Regions:                    regions,
		ActiveCollectionPointCount: len(regions),
	}, nil
}

func GetLatestServiceabilitySnapshot(db *sql.DB) (*models.ServiceabilitySnapshot, error) {
	var snap models.ServiceabilitySnapshot
	var computedAt time.Time
	var regionsJSON []byte
	err := db.QueryRow(`
		SELECT version, status, network_revision, computed_at, regions, active_collection_point_count
		FROM serviceability_snapshots
		WHERE status = 'complete'
