package service

import (
	"database/sql"
	"encoding/json"
	"math"
	"time"

	"lab-transport/internal/models"
)

func HaversineDistance(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0 // Earth radius in kilometers
	dLat := (lat2 - lat1) * math.Pi / 180.0
	dLon := (lon2 - lon1) * math.Pi / 180.0

	lat1Rad := lat1 * math.Pi / 180.0
	lat2Rad := lat2 * math.Pi / 180.0

	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(lat1Rad)*math.Cos(lat2Rad)*
			math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}

type CheckServiceabilityParams struct {
	Origin               *models.Coordinate `json:"origin"`
	OriginType           string             `json:"originType"`
	OriginNodeId         *string            `json:"originNodeId"`
	SampleTypeId         string             `json:"sampleTypeId"`
	RequestedAt          string             `json:"requestedAt"`
	DeliveryDeadline     string             `json:"deliveryDeadline"`
	EarliestCollectionAt string             `json:"earliestCollectionAt"`
	LatestCollectionAt   string             `json:"latestCollectionAt"`
}

type CheckServiceabilityResult struct {
	Serviceable           bool    `json:"serviceable"`
	Reason                string  `json:"reason"`
	TargetLaboratoryId    *string `json:"targetLaboratoryId,omitempty"`
	EstimatedArrivalAt    *string `json:"estimatedArrivalAt,omitempty"`
	ServiceabilityVersion int     `json:"serviceabilityVersion"`
	ClosestNodeId         *string `json:"-"`
	RoutePath             []string `json:"-"`
	TotalTravelMinutes    int     `json:"-"`
	TotalCostUnits        float64 `json:"-"`
}

func CheckServiceability(db *sql.DB, params CheckServiceabilityParams) (*CheckServiceabilityResult, error) {
	// 1. Get latest serviceability snapshot version
	var snapVersion int
	err := db.QueryRow("SELECT version FROM serviceability_snapshots ORDER BY version DESC LIMIT 1").Scan(&snapVersion)
	if err != nil {
		snapVersion = 1
	}

	result := &CheckServiceabilityResult{
		Serviceable:           false,
		ServiceabilityVersion: snapVersion,
	}

	// Validate times
	var earliestTime time.Time
	var latestTime time.Time
	var deadlineTime time.Time

	if params.RequestedAt != "" {
		earliestTime, _ = time.Parse(time.RFC3339, params.RequestedAt)
	}
	if earliestTime.IsZero() {
		earliestTime = time.Now()
	}

	if params.EarliestCollectionAt != "" {
		if t, err := time.Parse(time.RFC3339, params.EarliestCollectionAt); err == nil {
			earliestTime = t
		}
	}

	latestTime = earliestTime.Add(1 * time.Hour)
	if params.LatestCollectionAt != "" {
		if t, err := time.Parse(time.RFC3339, params.LatestCollectionAt); err == nil {
			latestTime = t
		}
	}

	if params.DeliveryDeadline != "" {
		if t, err := time.Parse(time.RFC3339, params.DeliveryDeadline); err == nil {
			deadlineTime = t
		} else {
			result.Reason = "deadline_unreachable"
			return result, nil
		}
	} else {
		result.Reason = "deadline_unreachable"
		return result, nil
	}

	if earliestTime.After(latestTime) || latestTime.After(deadlineTime) {
		result.Reason = "deadline_unreachable"
		return result, nil
	}

	// 2. Fetch Sample Type
	var st models.SampleType
	var incompJSON []byte
	row := db.QueryRow(`
		SELECT sample_type_id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed
		FROM sample_types
		WHERE sample_type_id = $1
