		if funcLab {
			// Check if lab accepts sample type
			accepted := false
			for _, tid := range loc.AcceptedSampleTypeIds {
				if tid == params.SampleTypeId {
					accepted = true
					break
				}
			}
			if accepted || len(loc.AcceptedSampleTypeIds) == 0 {
				labLocations = append(labLocations, loc)
			}
		}

		if params.OriginNodeId != nil && *params.OriginNodeId == loc.LocationId {
			closestNode = &models.Location{
				LocationId:      loc.LocationId,
				Name:            loc.Name,
				Coordinate:      loc.Coordinate,
				CoverageKm:      loc.CoverageKm,
				HandlingMinutes: loc.HandlingMinutes,
				Active:          loc.Active,
				Functions:       loc.Functions,
			}
			minDist = 0
		} else if params.Origin != nil && funcCP {
			dist := HaversineDistance(params.Origin.Latitude, params.Origin.Longitude, loc.Coordinate.Latitude, loc.Coordinate.Longitude)
			if dist <= loc.CoverageKm && dist < minDist {
				minDist = dist
				closestNode = &models.Location{
					LocationId:      loc.LocationId,
					Name:            loc.Name,
					Coordinate:      loc.Coordinate,
					CoverageKm:      loc.CoverageKm,
					HandlingMinutes: loc.HandlingMinutes,
					Active:          loc.Active,
					Functions:       loc.Functions,
				}
			}
		}
	}

	if closestNode == nil {
		result.Reason = "outside_service_coverage"
		return result, nil
	}
	result.ClosestNodeId = &closestNode.LocationId

	if len(labLocations) == 0 {
		result.Reason = "no_accepting_laboratory"
		return result, nil
	}

	// 4. Fetch connections
	connRows, err := db.Query(`
		SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
		FROM connections
		WHERE active = true
	`)
	if err != nil {
		return nil, err
	}
	defer connRows.Close()

	var allConnections []models.OperationsConnection
	for connRows.Next() {
		var c models.OperationsConnection
		var capUnits, resUnits, coolCapUnits, coolResUnits int
		if err := connRows.Scan(&c.ConnectionId, &c.FromLocationId, &c.ToLocationId, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active, &capUnits, &resUnits, &coolCapUnits, &coolResUnits); err != nil {
			return nil, err
		}
		c.ID = c.ConnectionId
		c.Capacity = &models.Capacity{
			CapacityUnits:        capUnits,
			ReservedUnits:        resUnits,
			AvailableUnits:       capUnits - resUnits,
			CooledCapacityUnits:  coolCapUnits,
			CooledReservedUnits:  coolResUnits,
			CooledAvailableUnits: coolCapUnits - coolResUnits,
		}
		allConnections = append(allConnections, c)
	}

	// 5. Shortest path (Dijkstra) from closestNode to any labLocation
	bestPath, bestLabId, totalTravel, totalCost, err := FindShortestRoute(closestNode.LocationId, labLocations, allLocations, allConnections, st.RequiresCooledRoute)
	if err != nil || len(bestPath) == 0 {
		// Check if failure is due to capacity
		result.Reason = "no_route"
		return result, nil
	}

	// Collection leg time: estimated 15 mins for home collection + handling
	collectionMins := 15 + closestNode.HandlingMinutes
	totalMinutes := collectionMins + totalTravel

	estimatedArrival := earliestTime.Add(time.Duration(totalMinutes) * time.Minute)
	if estimatedArrival.After(deadlineTime) {
		result.Reason = "deadline_unreachable"
		return result, nil
	}

	estStr := estimatedArrival.Format(time.RFC3339Nano)
	result.Serviceable = true
	result.Reason = "serviceable"
	result.TargetLaboratoryId = &bestLabId
	result.EstimatedArrivalAt = &estStr
	result.RoutePath = bestPath
	result.TotalTravelMinutes = totalMinutes
	result.TotalCostUnits = totalCost

	return result, nil
}

